    pub const KIND_NFT_REGISTRY: u8 = 7;

    // ── Sync unit W2-S1b (upstream `d57411f8`, "prevent whole-market address
    // reuse") ───────────────────────────────────────────────────────────
    // Upstream introduces its OWN `KIND_CLOSED_MARKET = 5`. That literal value
