    #[inline(never)]
    fn handle_init_market<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        max_portfolio_assets: u16,
        h_min: u64,
        h_max: u64,
        initial_price: u64,
        min_nonzero_mm_req: u128,
        min_nonzero_im_req: u128,
        maintenance_margin_bps: u64,
        initial_margin_bps: u64,
        max_trading_fee_bps: u64,
        trade_fee_base_bps: u64,
        liquidation_fee_bps: u64,
        liquidation_fee_cap: u128,
        min_liquidation_abs: u128,
        max_price_move_bps_per_slot: u64,
        max_accrual_dt_slots: u64,
        max_abs_funding_e9_per_slot: u64,
        min_funding_lifetime_slots: u64,
        max_account_b_settlement_chunks: u64,
        max_bankrupt_close_chunks: u64,
        max_bankrupt_close_lifetime_slots: u64,
        public_b_chunk_atoms: u128,
        maintenance_fee_per_slot: u128,
    ) -> ProgramResult {
        let admin = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let mint_ai = account(accounts, 2)?;
        expect_signer(admin)?;
        expect_writable(market_ai)?;
        expect_owner(market_ai, program_id)?;
        verify_mint(mint_ai)?;
        if trade_fee_base_bps > max_trading_fee_bps
            || max_portfolio_assets == 0
            || max_portfolio_assets > constants::WRAPPER_MAX_PORTFOLIO_ASSETS
            || h_max as u128 > BOUND_SCALE
            || maintenance_fee_per_slot > percolator::MAX_PROTOCOL_FEE_ABS
        {
            return Err(PercolatorError::EngineInvalidConfig.into());
        }
        let mut cfg = V16Config::public_user_fund(max_portfolio_assets, h_min, h_max);
        cfg.min_nonzero_mm_req = min_nonzero_mm_req;
        cfg.min_nonzero_im_req = min_nonzero_im_req;
        cfg.maintenance_margin_bps = maintenance_margin_bps;
        cfg.initial_margin_bps = initial_margin_bps;
        cfg.max_trading_fee_bps = max_trading_fee_bps;
        cfg.liquidation_fee_bps = liquidation_fee_bps;
        cfg.liquidation_fee_cap = liquidation_fee_cap;
        cfg.min_liquidation_abs = min_liquidation_abs;
        cfg.max_price_move_bps_per_slot = max_price_move_bps_per_slot;
        cfg.max_accrual_dt_slots = max_accrual_dt_slots;
        cfg.max_abs_funding_e9_per_slot = max_abs_funding_e9_per_slot;
        cfg.min_funding_lifetime_slots = min_funding_lifetime_slots;
        cfg.max_account_b_settlement_chunks = max_account_b_settlement_chunks;
        cfg.max_bankrupt_close_chunks = max_bankrupt_close_chunks;
        cfg.max_bankrupt_close_lifetime_slots = max_bankrupt_close_lifetime_slots;
        cfg.public_b_chunk_atoms = public_b_chunk_atoms;
        if initial_price == 0 || initial_price > percolator::MAX_ORACLE_PRICE {
            return Err(PercolatorError::EngineInvalidConfig.into());
        }
        // WARNING (not a repair): say so loudly when this market's funding
        // cannot accrue at its genesis price. See `warn_if_funding_cannot_accrue`
        // for why this warns rather than rejects. The flooring itself lives in
        // the engine and is NOT changed.
        warn_if_funding_cannot_accrue(
            max_abs_funding_e9_per_slot,
            max_accrual_dt_slots,
            initial_price,
        );
        let init_slot = Clock::get().map(|c| c.slot).unwrap_or(0);
        let wrapper = WrapperConfigV16 {
            marketauth: admin.key.to_bytes(),
            collateral_mint: mint_ai.key.to_bytes(),
            secondary_collateral_mint: [0u8; 32],
            maintenance_fee_per_slot,
            permissionless_market_init_fee: 0,
            // No fee-split floor check applies here, and none is needed:
            // InitMarket hardcodes the DEFAULT shares (1600/4800/1600), which
            // sum to FEE_SHARE_TOTAL_BPS and clear every floor by construction.
            // A market that never calls a setter is already compliant.
            //
            // CORRECTED: this used to say the floor "is enforced once
            // backing/insurance shares are actually configured, via the two
            // setters", pointing at `policy_v16::fee_split_floor_ok`. Both
            // setters dropped that check and `fee_split_floor_ok` is retired.
            // The only floor enforcement point is `handle_update_fee_split`
            // (tag 86) via `policy_v16::validate_fee_split`.
            trade_fee_base_bps,
            permissionless_resolve_stale_slots: 0,
            force_close_delay_slots: 0,
            last_good_oracle_slot: init_slot,
            insurance_withdraw_deposit_remaining: 0,
            insurance_withdraw_max_bps: 0,
            liquidation_cranker_fee_share_bps: 0,
            maintenance_cranker_fee_share_bps: 0,
            backing_trade_fee_bps_long: 0,
            backing_trade_fee_bps_short: 0,
            unit_scale: 0,
            conf_filter_bps: 0,
            insurance_withdraw_deposits_only: 0,
            oracle_mode: constants::ORACLE_MODE_MANUAL,
            oracle_leg_count: 0,
            oracle_leg_flags: 0,
            invert: 0,
            _padding0: 0,
            free_market_slot_count: 0,
            insurance_withdraw_cooldown_slots: 0,
            last_insurance_withdraw_slot: 0,
            max_staleness_secs: 0,
            hybrid_soft_stale_slots: 0,
            mark_ewma_e6: initial_price,
            mark_ewma_last_slot: init_slot,
            mark_ewma_halflife_slots: constants::DEFAULT_MARK_EWMA_HALFLIFE_SLOTS,
            mark_min_fee: 0,
            oracle_target_price_e6: initial_price,
            oracle_target_publish_time: 0,
            oracle_leg_feeds: [[0u8; 32]; constants::ORACLE_LEG_CAP],
            oracle_leg_prices_e6: [0u64; constants::ORACLE_LEG_CAP],
            oracle_leg_publish_times: [0i64; constants::ORACLE_LEG_CAP],
            backing_trade_fee_policy_count: 0,
            backing_trade_fee_insurance_share_bps_long: 0,
            backing_trade_fee_insurance_share_bps_short: 0,
            fee_redirect_to_market_0_bps: 0,
            // Protocol-fee program change: unconditionally set to the
            // hardcoded default at construction, never a caller-supplied
            // argument -- no code path can create a market with a
            // zero/attacker-controlled protocol_fee_authority.
            protocol_fee_authority: constants::PROTOCOL_FEE_AUTHORITY_DEFAULT.to_bytes(),
            protocol_fee_accrued_atoms: 0,
            protocol_fee_withdrawn_atoms: 0,
            // Fee-split: hardcoded defaults, never caller-supplied, so no market
            // can be created with a zero or hostile split. A market that never
            // calls UpdateFeeSplit still pays all four legs correctly.
            lp_fee_accrued_atoms: 0,
            lp_fee_withdrawn_atoms: 0,
            insurance_reserve_accrued_atoms: 0,
            insurance_reserve_withdrawn_atoms: 0,
            creator_share_bps: constants::DEFAULT_CREATOR_SHARE_BPS,
            lp_share_bps: constants::DEFAULT_LP_SHARE_BPS,
            insurance_share_bps: constants::DEFAULT_INSURANCE_SHARE_BPS,
            _padding_split: [0u8; 2],
            // Creator fee claim: a brand-new market has earned nothing yet.
            creator_fee_claimable_atoms: 0,
        };
        state::init_market_account_zero_copy(
            &mut market_ai.try_borrow_mut_data()?,
            &wrapper,
            cfg,
            market_ai.key.to_bytes(),
            initial_price,
            init_slot,
        )
    }

    #[inline(never)]
    fn handle_init_portfolio<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
    ) -> ProgramResult {
        let owner = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let portfolio_ai = account(accounts, 2)?;
        expect_signer(owner)?;
        expect_writable(market_ai)?;
        expect_writable(portfolio_ai)?;
        expect_owner(market_ai, program_id)?;
        expect_owner(portfolio_ai, program_id)?;
        if state::is_initialized(&portfolio_ai.try_borrow_data()?) {
            return Err(PercolatorError::AlreadyInitialized.into());
        }
        let (cfg, mode, max_market_slots, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        if mode != MarketModeV16::Live {
            return Err(PercolatorError::EngineLockActive.into());
        }
        let source_domain_count =
            v16_domain_count_for_market_slots(max_market_slots as u32).map_err(map_v16_error)?;
        let required_portfolio_len =
            state::portfolio_account_len_for_market_slots(max_market_slots)?;
        // ADOPT upstream 2c8c5ba3 (LENGTH half only): InitPortfolio is the one
        // instruction allowed to canonicalize storage -- an oversized, still-
        // uninitialized System-Program-created account is shrunk to the exact
        // canonical length here (realloc both grows AND shrinks), rather than
        // being left oversized to accumulate ambiguous trailing bytes.
        if portfolio_ai.data_len() != required_portfolio_len {
            portfolio_ai.realloc(required_portfolio_len, true)?;
        }
        {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (cfg, mut group) = state::market_view_mut(&mut market_data)?;
            if group.header.mode != 0 {
                return Err(PercolatorError::EngineLockActive.into());
            }
            reject_permissionless_resolve_matured_live_view(&cfg, &group)?;
            let last_fee_slot = authenticated_market_slot_or_fallback_view(&group);
            // TB-1a: allocate this portfolio's permanent `portfolio_id` from the
            // market-scoped counter carried in asset 0's `AssetOracleProfileV16`
            // spare tail (see that field's doc comment for why it lives there,
            // not in `WrapperConfigV16`). Every market always has an asset 0
            // (`DEFAULT_MARKET_SLOT_CAPACITY = 1`), and asset 0 can never be
            // retired/re-activated, so this storage is permanent for the
            // market's whole life.
            let mut profile0 = read_oracle_profile_from_view(&group, &cfg, 0)?;
            let (portfolio_id, next_portfolio_id) =
                state::allocate_portfolio_id(profile0.next_portfolio_id)?;
            state::init_portfolio_account_zero_copy(
                &mut portfolio_ai.try_borrow_mut_data()?,
                market_ai.key.to_bytes(),
                portfolio_ai.key.to_bytes(),
                owner.key.to_bytes(),
                last_fee_slot,
                max_market_slots,
                portfolio_id,
            )?;
            let mut portfolio_data = portfolio_ai.try_borrow_mut_data()?;
            let portfolio =
                state::portfolio_view_mut_for_market_slots(&mut portfolio_data, max_market_slots)?;
            portfolio
                .as_view()
                .validate_with_market(&group.as_view())
                .map_err(map_v16_error)?;
            group
                .register_empty_materialized_portfolio_not_atomic(&portfolio.as_view())
                .map_err(map_v16_error)?;
            profile0.next_portfolio_id = next_portfolio_id;
            write_oracle_profile_to_view(&mut group, 0, &profile0)?;
        }
        let _ = (cfg, source_domain_count);
        Ok(())
    }

    #[inline(never)]
    fn handle_deposit<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        expected_portfolio_id: u64,
        expected_sequence: u64,
        amount: u128,
    ) -> ProgramResult {
        let owner = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let portfolio_ai = account(accounts, 2)?;
        let source_token = account(accounts, 3)?;
        let vault_token = account(accounts, 4)?;
        let token_program = account(accounts, 5)?;
        expect_signer(owner)?;
        expect_writable(market_ai)?;
        expect_writable(portfolio_ai)?;
        expect_writable(source_token)?;
        expect_writable(vault_token)?;
        expect_owner(market_ai, program_id)?;
        expect_owner(portfolio_ai, program_id)?;
        verify_token_program(token_program)?;
        // TB-1b (ADOPT upstream 0492ebbc): fail fast, before any token-account
        // verification work, if this Deposit was built against an
        // incarnation/sequence this account has since moved past.
        expect_portfolio_sequence_binding(
            &portfolio_ai.try_borrow_data()?,
            expected_portfolio_id,
            expected_sequence,
        )?;

        let (cfg, mode, max_market_slots, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        if mode != MarketModeV16::Live {
            return Err(PercolatorError::EngineLockActive.into());
        }
        let mint = primary_collateral_mint(&cfg);
        let (vault_authority, _) = derive_vault_authority(program_id, market_ai.key);
        let source_balance = verify_user_token_account(source_token, owner.key, &mint)?;
        verify_vault_token_account(vault_token, &vault_authority, &mint)?;
        let amount_u64 = amount_to_u64(amount)?;
        require_token_balance(source_balance, amount_u64)?;

        ensure_portfolio_storage_for_market_slots(portfolio_ai, max_market_slots)?;
        {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (cfg, mut group) = state::market_view_mut(&mut market_data)?;
            if group.header.mode != 0 {
                return Err(PercolatorError::EngineLockActive.into());
            }
            reject_permissionless_resolve_matured_live_view(&cfg, &group)?;
            let mut portfolio_data = portfolio_ai.try_borrow_mut_data()?;
            // TB-1b: live re-check right before mutation, against the current bytes
            // (the account may have grown via `ensure_portfolio_storage_for_market_slots`
            // above, and this is the read that actually gates the mutation below).
            expect_portfolio_sequence_binding(
                &portfolio_data,
                expected_portfolio_id,
                expected_sequence,
            )?;
            {
                let mut portfolio = state::portfolio_view_mut_for_market_slots(
                    &mut portfolio_data,
                    max_market_slots,
                )?;
                expect_portfolio_view_account_key(&portfolio, portfolio_ai.key)?;
                // E2: owner==signer OR the signer holds the bound NFT (escrowed position).
                // Optional trailing accounts [6]=nft_registry [7]=PositionNft PDA [8]=signer NFT ATA.
                // Lets an NFT holder margin-defend a wrapped position (#146).
                let nft = optional_nft_holder_accounts(accounts, 6);
                authorize_owner_or_nft_holder(
                    &portfolio,
                    portfolio_ai.key,
                    owner.key,
                    nft,
                    program_id,
                )?;
                group
                    .deposit_not_atomic(&mut portfolio, amount)
                    .map_err(map_v16_error)?;
            }
            // TB-1b (ADOPT upstream 0492ebbc): one-shot -- a landed Deposit always
            // advances the shared retained-owner-state sequence, so a stale
            // Deposit/Withdraw/SetMatcherConfig/ClosePortfolio built against the
            // pre-deposit sequence can never replay against this account again.
            state::advance_portfolio_matcher_sequence(&mut portfolio_data, expected_sequence)?;
        }
        transfer_tokens(token_program, source_token, vault_token, owner, amount_u64)?;
        Ok(())
    }

    #[inline(never)]
    fn handle_withdraw<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        expected_portfolio_id: u64,
        expected_sequence: u64,
        amount: u128,
    ) -> ProgramResult {
        let owner = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let portfolio_ai = account(accounts, 2)?;
        let dest_token = account(accounts, 3)?;
        let vault_token = account(accounts, 4)?;
        let vault_authority_ai = account(accounts, 5)?;
        let token_program = account(accounts, 6)?;
        expect_signer(owner)?;
        expect_writable(market_ai)?;
        expect_writable(portfolio_ai)?;
        expect_writable(dest_token)?;
        expect_writable(vault_token)?;
        expect_owner(market_ai, program_id)?;
        expect_owner(portfolio_ai, program_id)?;
        verify_token_program(token_program)?;
        // TB-1b (ADOPT upstream 0492ebbc): same fail-fast binding check as Deposit.
        expect_portfolio_sequence_binding(
            &portfolio_ai.try_borrow_data()?,
            expected_portfolio_id,
            expected_sequence,
        )?;

        let (cfg, mode, max_market_slots, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        if mode != MarketModeV16::Live {
            return Err(PercolatorError::EngineLockActive.into());
        }
        let (vault_authority, bump) = derive_vault_authority(program_id, market_ai.key);
        expect_key(vault_authority_ai, &vault_authority)?;
        let vault_balance = verify_withdrawable_token_accounts(
            dest_token,
            owner.key,
            vault_token,
            &vault_authority,
            &cfg,
            false,
        )?;
        // FIX (ADOPT upstream a84b45dd, folded with d1bff017): the balance check below moves
        // past the fee-crystallization block and is re-derived from the ACTUAL withdrawn
        // amount, not the caller-submitted one -- see `withdrawn_amount` below for why those
        // can differ.
        if amount == 0 {
            return Ok(());
        }
        amount_to_u64(amount)?;

        ensure_portfolio_storage_for_market_slots(portfolio_ai, max_market_slots)?;
        let withdrawn_amount = {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (cfg, mut group) = state::market_view_mut(&mut market_data)?;
            if group.header.mode != 0 {
                return Err(PercolatorError::EngineLockActive.into());
            }
            reject_permissionless_resolve_matured_live_view(&cfg, &group)?;
            let mut portfolio_data = portfolio_ai.try_borrow_mut_data()?;
            // TB-1b: live re-check right before mutation.
            expect_portfolio_sequence_binding(
                &portfolio_data,
                expected_portfolio_id,
                expected_sequence,
            )?;
            let withdrawn_amount = {
                let mut portfolio = state::portfolio_view_mut_for_market_slots(
                    &mut portfolio_data,
                    max_market_slots,
                )?;
                expect_portfolio_view_account_key(&portfolio, portfolio_ai.key)?;
                // E2: owner==signer OR signer holds the bound NFT. Optional trailing
                // accounts [7]=nft_registry [8]=PositionNft PDA [9]=signer NFT ATA.
                // FUND-SAFETY: the dest-token check uses `owner.key` (the SIGNER), so an
                // NFT-holder withdrawal pays the HOLDER, never the escrow PDA.
                let nft = optional_nft_holder_accounts(accounts, 7);
                authorize_owner_or_nft_holder(
                    &portfolio,
                    portfolio_ai.key,
                    owner.key,
                    nft,
                    program_id,
                )?;
                // FIX (ADOPT upstream a84b45dd/d1bff017, "collect maintenance before value
                // debits"): crystallize this account's accrued maintenance fee against its
                // capital BEFORE the withdraw below debits that same capital. Without this a
                // Withdraw could dodge every maintenance fee accrued since the account's last
                // sync -- an ongoing insurance-funding leak. A revert here (including
                // `EngineBStale`) is acceptable: this is a user-initiated action, and the caller
                // can crank the account current and retry.
                let capital_before_fee = portfolio.header.capital.get();
                collect_maintenance_fee_before_value_debit_view(&cfg, &mut group, &mut portfolio)?;
                // Preserve an atomic withdraw-all path when the submitted balance became stale
                // only because this instruction just crystallized its fee: a caller who asked to
                // withdraw exactly their pre-fee capital still gets everything left after the
                // fee, in one instruction, instead of hitting `EngineLockActive` because `amount`
                // now exceeds the freshly-reduced capital. Partial withdrawals remain exact.
                let withdrawn_amount = if amount == capital_before_fee {
                    portfolio.header.capital.get()
                } else {
                    amount
                };
                group
                    .withdraw_not_atomic(&mut portfolio, withdrawn_amount)
                    .map_err(map_v16_error)?;
                withdrawn_amount
            };
            // TB-1b (ADOPT upstream 0492ebbc): one-shot -- a landed nonzero Withdraw
            // also advances the shared sequence (same rationale as Deposit).
            state::advance_portfolio_matcher_sequence(&mut portfolio_data, expected_sequence)?;
            withdrawn_amount
        };
        let amount_u64 = amount_to_u64(withdrawn_amount)?;
        require_token_balance(vault_balance, amount_u64)?;
        let bump_arr = [bump];
        let signer_seeds: &[&[&[u8]]] = &[&[b"vault", market_ai.key.as_ref(), &bump_arr]];
        transfer_tokens_signed(
            token_program,
            vault_token,
            dest_token,
            vault_authority_ai,
            amount_u64,
            signer_seeds,
        )
    }

    #[inline(never)]
    // TB-1b: grew past the clippy threshold with the 4 new portfolio-identity
    // binding params (account_{a,b}_portfolio_id/position_epoch); matches the
    // existing allow on this file's other multi-account trade handlers.
    #[allow(clippy::too_many_arguments)]
    fn handle_trade_nocpi_zero_copy<'a>(
        _program_id: &Pubkey,
        account_a_owner_key: &Pubkey,
        account_b_owner_key: &Pubkey,
        market_ai: &AccountInfo<'a>,
        account_a_ai: &AccountInfo<'a>,
        account_b_ai: &AccountInfo<'a>,
        account_a_portfolio_id: u64,
        account_a_position_epoch: u64,
        account_b_portfolio_id: u64,
        account_b_position_epoch: u64,
        asset_index: u16,
        expected_market_id: u64,
        size_q: i128,
        exec_price: u64,
        fee_bps: u64,
        account_a_backing_fee_cap_bps: Option<u16>,
        account_b_backing_fee_cap_bps: Option<u16>,
        max_market_slots: usize,
    ) -> ProgramResult {
        ensure_portfolio_storage_for_market_slots(account_a_ai, max_market_slots)?;
        ensure_portfolio_storage_for_market_slots(account_b_ai, max_market_slots)?;
        let mut cfg_after = None;
        {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (mut cfg, mut group) = state::market_view_mut(&mut market_data)?;
            require_asset_generation_view(&group, asset_index as usize, expected_market_id)?;
            let mut oracle_profile =
                read_oracle_profile_from_view(&group, &cfg, asset_index as usize)?;
            reject_permissionless_resolve_matured_live_for_profile_view(
                &cfg,
                &oracle_profile,
                &group,
            )?;
            let mut account_a_data = account_a_ai.try_borrow_mut_data()?;
            let mut account_b_data = account_b_ai.try_borrow_mut_data()?;
            // TB-1b (ADOPT upstream 0492ebbc): live re-check right before mutation --
            // this is the shared low-level executor both TradeNoCpi and TradeCpi funnel
            // through, so this is where the binding actually gates the engine call.
            expect_portfolio_position_binding(
                &account_a_data,
                account_a_portfolio_id,
                account_a_position_epoch,
            )?;
            expect_portfolio_position_binding(
                &account_b_data,
                account_b_portfolio_id,
                account_b_position_epoch,
            )?;
            let mut account_a =
                state::portfolio_view_mut_for_market_slots(&mut account_a_data, max_market_slots)?;
            let mut account_b =
                state::portfolio_view_mut_for_market_slots(&mut account_b_data, max_market_slots)?;
            expect_portfolio_view_account_key(&account_a, account_a_ai.key)?;
            expect_portfolio_view_account_key(&account_b, account_b_ai.key)?;
            expect_portfolio_view_owner(&account_a, account_a_owner_key)?;
            expect_portfolio_view_owner(&account_b, account_b_owner_key)?;
            let size_abs = if size_q == i128::MIN || size_q == 0 {
                return Err(PercolatorError::InvalidInstruction.into());
            } else {
                size_q.unsigned_abs()
            };
            // w1-s3: current signed position on the traded asset, needed below to decide
            // whether this trade's delta can newly touch a source domain.
            let account_a_position =
                signed_position_for_asset_view(&group, &account_a, asset_index as usize)?;
            let account_b_position =
                signed_position_for_asset_view(&group, &account_b, asset_index as usize)?;
            // FIX (ADOPT upstream 06192caa/7a050c25, "canonical zero-move funding
            // accrual", adapted -- Wave-1 S4): settle any owed stationary-premium
            // funding on THIS asset before the engine applies the position change
            // below. A reducing leg on either account must fully catch up in this
            // same instruction (no dodging already-accrued funding by closing
            // between crank sweeps); an opening/increasing leg may proceed with a
            // partial, bounded catch-up.
            let reduces_existing = trade_delta_reduces_existing(account_a_position, size_q)
                || trade_delta_reduces_existing(account_b_position, -size_q);
            accrue_zero_move_funding_before_position_change_for_profile_view(
                &mut oracle_profile,
                &mut group,
                asset_index as usize,
                reduces_existing,
            )
            .map_err(map_v16_error)?;
            // F-TRADENOCPI-FEE: the position enters/settles at the asset mark (effective_price), NOT at
            // the caller-supplied exec_price. The engine uses request.exec_price ONLY as the fee notional
            // basis (fee = size_q*exec_price/POS_SCALE * fee_bps), so without pinning it two cooperating
            // accounts could declare a tiny exec_price to pay an arbitrarily small fee on a full
            // mark-valued trade. Bill the fee on the mark (the price the trade actually settles at),
            // mirroring TradeCpi where the matcher's exec_price_e6 must equal the oracle price.
            // NOTE: the ORIGINAL caller exec_price is still passed to update_hybrid_mark_after_trade_view
            // below — in hybrid mode that is the reported trade price that drives mark discovery (bounded
            // by the EWMA/clamp), a distinct role from the fee basis.
            let fee_basis_price = group.markets[asset_index as usize]
                .engine
                .asset
                .effective_price
                .get();
            let fee_bps = hybrid_trade_fee_bps_view(
                &cfg,
                &oracle_profile,
                &group,
                asset_index as usize,
                size_abs,
                fee_basis_price,
                fee_bps,
            )?;
            let req = TradeRequestV16 {
                asset_index: asset_index as usize,
                // size_q is signed (i128) in the engine; direction is carried by the long/short
                // account orientation chosen below (size_q > 0 ? (a,b) : (b,a)), so pass the
                // positive magnitude here to preserve the existing single-trade semantics.
                size_q: size_abs as i128,
                exec_price: fee_basis_price,
                fee_bps,
            };
            ensure_trade_portfolios_current_for_requests_view(
                &group,
                &account_a,
                &account_b,
                core::slice::from_ref(&req),
            )?;
            // FIX (ADOPT upstream a84b45dd/d1bff017, "collect maintenance before value
            // debits"): crystallize each account's accrued maintenance fee BEFORE the trade
            // below can move capital/positions, so a trade cannot dodge fee accrued since the
            // account's last sync. Ordered before the w1-s3 admission snapshot immediately
            // below, so that snapshot (and the value debit further down) reflect
            // post-fee-crystallization state; a revert here (including `EngineBStale`) is
            // acceptable on this user-initiated path -- the caller cranks first, then retries.
            collect_maintenance_fee_before_trade_view(&cfg, &mut group, &mut account_a)?;
            collect_maintenance_fee_before_trade_view(&cfg, &mut group, &mut account_b)?;
            // w1-s3 (upstream `cf0ce5d3`/`7a3a6f30`): reserve latent domains of surviving,
            // untouched legs before the engine's own trade-application primitive runs, so this
            // trade cannot fill either account's source-domain table and starve a sibling leg's
            // later liquidation/ADL/force-close of the slot it will need. Only pays the O(active
            // legs) snapshot cost when this trade's own delta could newly touch a domain.
            let account_a_needs_source_capacity =
                trade_delta_may_require_source_domain_capacity(account_a_position, size_q)?;
            let account_b_needs_source_capacity =
                trade_delta_may_require_source_domain_capacity(account_b_position, -size_q)?;
            if account_a_needs_source_capacity || account_b_needs_source_capacity {
                let mut admitted_source_domains_a =
                    reserved_source_domains_snapshot_for_trade_view(
                        &group,
                        &account_a,
                        core::slice::from_ref(&req),
                        size_q < 0,
                    )?;
                let mut admitted_source_domains_b =
                    reserved_source_domains_snapshot_for_trade_view(
                        &group,
                        &account_b,
                        core::slice::from_ref(&req),
                        size_q > 0,
                    )?;
                ensure_trade_delta_source_domain_capacity_view(
                    &mut admitted_source_domains_a,
                    asset_index as usize,
                    account_a_position,
                    size_q,
                )?;
                ensure_trade_delta_source_domain_capacity_view(
                    &mut admitted_source_domains_b,
                    asset_index as usize,
                    account_b_position,
                    -size_q,
                )?;
            }
            // sync/w1-abacking (adopt upstream 57d04a7d, "reject newly backed liens after
            // expiry"): these snapshots used to be gated on `backing_trade_fee_policy_count`
            // (they only existed to drive the fee split below). The freshness check right
            // after the engine call needs them unconditionally -- a domain can back a NEW
            // counterparty-backed lien via this trade even when no backing-domain FEE policy
            // is configured for it, and a lien landing after that domain's signed backing
            // expiry must still be rejected.
            let backing_before_a = source_counterparty_backing_snapshot_view(&account_a)?;
            let backing_before_b = source_counterparty_backing_snapshot_view(&account_b)?;
            let source_lien_before_a =
                source_lien_effective_reserved_snapshot_for_trade_view(&account_a)?;
            let source_lien_before_b =
                source_lien_effective_reserved_snapshot_for_trade_view(&account_b)?;
            // Taker-only (design §1A): account_a is always the taker/fee-payer
            // (§1A.2). Whether account_a occupies the engine's first
            // (long_account) or second (short_account) positional slot
            // depends on the sign of the caller-supplied size_q, since this
            // single-trade path reorders (a,b) by sign (§1A.3) -- so
            // `taker_is_long_account` must mirror that same reordering.
            let outcome = if size_q > 0 {
                group
                    .execute_trade_with_fee_loss_stale_scoped_not_atomic(
                        &mut account_a,
                        &mut account_b,
                        req,
                        true, // account_a (taker) is long_account here
                    )
                    .map_err(map_v16_error)?
            } else {
                group
                    .execute_trade_with_fee_loss_stale_scoped_not_atomic(
                        &mut account_b,
                        &mut account_a,
                        req,
                        false, // account_a (taker) is short_account here
                    )
                    .map_err(map_v16_error)?
            };
            // FIX (ADOPT upstream 3496acf0, "enforce side OI caps"): checked immediately
            // after the engine mutates OI on this trade, before any other post-trade
            // check, so an over-cap post-state aborts the instruction.
            ensure_trade_side_oi_cap_view(&group, asset_index as usize)?;
            // sync/w1-abacking (57d04a7d): a retained transaction can land after the engine's
            // cached slot and a provider's signed backing expiry. Only newly-created
            // counterparty-backed liens need this landing-time check; insurance-backed liens
            // and trades that do not increase a lien remain live.
            ensure_new_counterparty_backed_liens_fresh_for_trade_view(
                &group,
                authenticated_market_slot_or_fallback_view(&group),
                backing_before_a.as_ref(),
                &account_a,
                backing_before_b.as_ref(),
                &account_b,
            )?;
            let backing_domain_fee = if cfg.backing_trade_fee_policy_count == 0 {
                0
            } else {
                apply_backing_domain_fees_after_trade_view(
                    &cfg,
                    &mut group,
                    &mut account_a,
                    backing_before_a.as_ref(),
                    &mut account_b,
                    backing_before_b.as_ref(),
                    account_a_backing_fee_cap_bps,
                    account_b_backing_fee_cap_bps,
                )?
            };
            // Four-way split (2026-07-19 design). Both aggregates are split and the two
            // results are added leg by leg below, so this site is correct whether the taker
            // paid the whole fee, the maker paid it under the N1 fallback, or -- since engine
            // #160 (`percolator 2c38570a:src/v16.rs:18224-18230`) -- the taker paid part and
            // the maker the remainder. Splitting 0 is all-zeros, so a side that paid nothing
            // gets exactly the 0 credit it should and no special-casing is needed. (This
            // comment used to claim taker-only guarantees exactly one of the two is nonzero;
            // that guarantee, and the proof it rested on, are gone at the linked engine -- see
            // `batch_fee_charge_within_owed`. The arithmetic here never depended on it.)
            let split_a = policy_v16::split_trade_fee(
                outcome.fee_a,
                constants::PROTOCOL_FEE_BPS,
                cfg.creator_share_bps,
                cfg.lp_share_bps,
                cfg.insurance_share_bps,
            )?;
            let split_b = policy_v16::split_trade_fee(
                outcome.fee_b,
                constants::PROTOCOL_FEE_BPS,
                cfg.creator_share_bps,
                cfg.lp_share_bps,
                cfg.insurance_share_bps,
            )?;
            // Creator-fee-claim change (2026-07-23): the creator leg NO LONGER
            // goes to the domain insurance budget. That budget is the loss
            // backstop the engine draws down via
            // `consume_domain_insurance_for_negative_pnl`, and its only exit
            // (tag 57 `WithdrawInsuranceAsset`) let a creator drain the
            // backstop while the market was healthy. The leg now accrues to a
            // dedicated counter claimable only via tag 90.
            let creator_cut_total = split_a
                .creator
                .checked_add(split_b.creator)
                .ok_or(PercolatorError::EngineArithmeticOverflow)?;

            let protocol_cut_total = split_a
                .protocol
                .checked_add(split_b.protocol)
                .ok_or(PercolatorError::EngineArithmeticOverflow)?;
            let lp_cut_total = split_a
                .lp
                .checked_add(split_b.lp)
                .ok_or(PercolatorError::EngineArithmeticOverflow)?;
            let insurance_cut_total = split_a
                .insurance
                .checked_add(split_b.insurance)
                .ok_or(PercolatorError::EngineArithmeticOverflow)?;

            if protocol_cut_total != 0
                || lp_cut_total != 0
                || insurance_cut_total != 0
                || creator_cut_total != 0
            {
                cfg.protocol_fee_accrued_atoms = cfg
                    .protocol_fee_accrued_atoms
                    .checked_add(protocol_cut_total)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                cfg.lp_fee_accrued_atoms = cfg
                    .lp_fee_accrued_atoms
                    .checked_add(lp_cut_total)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                cfg.insurance_reserve_accrued_atoms = cfg
                    .insurance_reserve_accrued_atoms
                    .checked_add(insurance_cut_total)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                // u128 -> u64 narrowing: the counter is u64 because it had to
                // fit the 8 spare bytes of `_padding_split`. Overflow (either
                // the narrowing or the add) ERRORS the whole trade rather than
                // wrapping or saturating.
                // GH#420: the creator cut accrues to THIS ASSET's profile, not to
                // the market-wide config counter. The old global accumulator paid
                // out against asset 0's `asset_admin` only, so in a multi-asset
                // market the base deployer could drain fees earned on assets 1..N
                // and those assets' creators could never claim their own.
                // Mutate the `oracle_profile` ALREADY IN SCOPE rather than doing a
                // fresh read/write here. That profile was read earlier in this
                // function and is written back below; a separate write at this
                // point is silently CLOBBERED by that later write-back, which is
                // exactly what happened in the first version of this change and
                // what `..._creator_fee_accrual_is_written_back_to_the_account_...`
                // caught. Same pattern as the batch path.
                oracle_profile.creator_fee_claimable_atoms = oracle_profile
                    .creator_fee_claimable_atoms
                    .checked_add(
                        u64::try_from(creator_cut_total)
                            .map_err(|_| PercolatorError::EngineArithmeticOverflow)?,
                    )
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                // CRITICAL: force the write-back below even if nothing else in
                // this instruction would otherwise have dirtied cfg. The cfg_after
                // pattern is opt-in per mutation -- a missed write-back here
                // SILENTLY DISCARDS accrued fees for all four legs.
                cfg_after = Some(cfg);
            }
            update_hybrid_mark_after_trade_view(
                &mut oracle_profile,
                &group,
                asset_index as usize,
                exec_price,
                outcome
                    .fee_a
                    .checked_add(outcome.fee_b)
                    .and_then(|v| v.checked_add(backing_domain_fee))
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?,
            )?;
            write_oracle_profile_to_view(&mut group, asset_index as usize, &oracle_profile)?;
            if asset_index == 0 && oracle_v16::profile_is_price_managed(&oracle_profile) {
                cfg.mark_ewma_e6 = oracle_profile.mark_ewma_e6;
                cfg.mark_ewma_last_slot = oracle_profile.mark_ewma_last_slot;
                cfg_after = Some(cfg);
            }
            group.validate_shape().map_err(map_v16_error)?;
            let source_lien_after_a =
                source_lien_effective_reserved_snapshot_for_trade_view(&account_a)?;
            let source_lien_after_b =
                source_lien_effective_reserved_snapshot_for_trade_view(&account_b)?;
            ensure_new_source_lien_domains_full_rate_for_trade_view(
                &group,
                source_lien_before_a.as_ref(),
                source_lien_after_a.as_ref(),
                source_lien_before_b.as_ref(),
                source_lien_after_b.as_ref(),
            )?;
            // w1-s3: independent post-hoc backstop -- the trade that just ran must not leave
            // either account occupying more source-domain slots than the wrapper's own bound
            // allows, regardless of whether the pre-trade admission check above already covered
            // the reason why (defense in depth, not a substitute for it).
            ensure_source_domain_growth_within_wrapper_bound(
                source_lien_before_a.len(),
                source_lien_after_a.len(),
            )?;
            ensure_source_domain_growth_within_wrapper_bound(
                source_lien_before_b.len(),
                source_lien_after_b.len(),
            )?;
        }
        if let Some(cfg) = cfg_after {
            state::write_wrapper_config(&mut market_ai.try_borrow_mut_data()?, &cfg)?;
        }
        Ok(())
    }

    /// Reconstruct the exact per-leg fee the engine charges for one leg, so wrapper-side
    /// per-asset/per-domain fee accounting can be split out of the engine's AGGREGATE batch
    /// outcome. FIX E4 (upstream engine 8f25aa5d, "charge sub-atom trade fees on ceil
    /// notional"): the engine now computes the fee on `trade_fee_notional_ceil` (ceil), NOT the
    /// `trade_notional_floor` (floor) used for margin/PnL bookkeeping -- a sub-atom fill
    /// (abs_size_q * exec_price / POS_SCALE < 1) floors to notional=0 (and therefore fee=0) even
    /// though it opens nonzero OI. Mirrors that: `fee_notional` here is the ceil (matching engine
    /// `risk_notional_ceil` / `trade_fee_notional_ceil`), then `checked_fee_bps`-equivalent ceil
    /// division on top for the fee itself. Extreme sizes that would need the engine's U256
    /// widening error out (the batch then rejects rather than mis-accounting — see the aggregate
    /// cross-check below). Before this fix, batch_leg_fee still used floor notional post-E4,
    /// so any NoCpi batch containing a sub-atom-notional leg would reconstruct fee=0 for that
    /// leg while the engine's aggregate outcome.fee_a/fee_b included its ceil-rounded fee atom,
    /// tripping the `reconstructed_total != engine_total` guard and hard-reverting the whole
    /// batch (fails closed, but an availability gap for otherwise-legitimate batches).
    pub fn batch_leg_fee(
        abs_size_q: u128,
        exec_price: u64,
        fee_bps: u64,
    ) -> Result<u128, ProgramError> {
        if abs_size_q == 0 || fee_bps == 0 {
            return Ok(0);
        }
        let product = abs_size_q
            .checked_mul(exec_price as u128)
            .ok_or(PercolatorError::EngineArithmeticOverflow)?;
        let pos_scale = percolator::POS_SCALE;
        let fee_notional = (product / pos_scale) + u128::from(product % pos_scale != 0);
        if fee_notional == 0 {
            return Ok(0);
        }
        let product = fee_notional
            .checked_mul(fee_bps as u128)
            .ok_or(PercolatorError::EngineArithmeticOverflow)?;
        let den = percolator::MAX_MARGIN_BPS as u128;
        Ok((product / den) + u128::from(product % den != 0))
    }

    /// B-4 (wrapper impact W-14) — the batch-aggregate fee invariant the engine ACTUALLY
    /// guarantees, replacing the exclusivity guard this wrapper used to enforce.
    ///
    /// The old guard refused any batch whose outcome had both `fee_a > 0` and `fee_b > 0`,
    /// citing `proof_v16_taker_only_charges_exactly_one_side`. That harness does not exist at
    /// the engine this wrapper builds against (`percolator 2c38570a`, `git grep -c` over the
    /// tree -> 0): engine #160 retired it and replaced it with
    /// `proof_v16_taker_only_never_overcharges_and_maker_pays_only_shortfall`
    /// (`2c38570a:tests/proofs_v16.rs:14466`), because the charge shape changed. The taker is
    /// charged first and, on a SHORTFALL rather than only on a zero payment, the solvent maker
    /// is charged the REMAINDER `fee - taker_fee`, bounded by `min(fee, C_m)`
    /// (`2c38570a:src/v16.rs:18213`, `:18224-18227`, `:19306`). The engine says so itself at
    /// `2c38570a:src/v16.rs:18229-18230`: "Second, BOTH return values can now be non-zero --
    /// previously exactly one was."
    ///
    /// So exclusivity is not an invariant of the linked engine; the AMOUNT is. Across the whole
    /// batch the two aggregates together never exceed the fee the batch owes: the maker is only
    /// ever asked for what the taker did not pay, and a remainder neither side can pay is
    /// FORGIVEN, never over-collected from the other side or socialized
    /// (`percolator:src/v16.rs` `uncollectible_fees_forgiven_not_socialized`; `av:spec.md:61`
    /// §0 #26 "No fee seniority"). "The maker is charged only when the taker fell short"
    /// (`fee_b > 0` implies `fee_a < fee_owed`) is a CONSEQUENCE of this bound, not a separate
    /// test: with `fee_a + fee_b <= fee_owed`, any nonzero `fee_b` forces `fee_a < fee_owed`.
    ///
    /// This is the wrapper's cross-ABI distrust check, kept in the same place the exclusivity
    /// guard sat: before any per-asset fee accounting or mark movement. The post-pass
    /// `reconstructed_total != engine_total` cross-check is STRICTER still (it pins the sum
    /// exactly) and is unchanged; this bound is the named invariant, stated where an
    /// over-collecting engine is caught before the wrapper credits anything.
    ///
    /// Returns false on overflow: an aggregate pair that cannot even be summed is refused.
    pub fn batch_fee_charge_within_owed(fee_a: u128, fee_b: u128, fee_owed: u128) -> bool {
        match fee_a.checked_add(fee_b) {
            Some(total) => total <= fee_owed,
            None => false,
        }
    }

    /// Atomic multi-leg batch trade. `account_a` (taker) is the long side, `account_b` (LP) the
    /// short side; each leg's SIGNED `size_q` decides that leg's direction, so one batch can carry
    /// a mixed long/short spread. The engine settles both accounts ONCE, applies every leg, then
    /// runs a SINGLE end-state initial-margin check — interim legs need not be individually
    /// margin-feasible. The wrapper still does its per-asset bookkeeping (fee basis, per-domain fee
    /// crediting, hybrid-mark discovery, oracle-profile writeback) for each leg around that one
    /// engine call.
    #[inline(never)]
    fn handle_batch_trade_nocpi<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        account_a_portfolio_id: u64,
        account_a_position_epoch: u64,
        account_b_portfolio_id: u64,
        account_b_position_epoch: u64,
        legs: &[ix::BatchTradeLeg],
    ) -> ProgramResult {
        let signer_a = account(accounts, 0)?;
        let signer_b = account(accounts, 1)?;
        let market_ai = account(accounts, 2)?;
        let account_a_ai = account(accounts, 3)?;
        let account_b_ai = account(accounts, 4)?;
        expect_signer(signer_a)?;
        expect_signer(signer_b)?;
        expect_writable(market_ai)?;
        expect_writable(account_a_ai)?;
        expect_writable(account_b_ai)?;
        expect_owner(market_ai, program_id)?;
        expect_owner(account_a_ai, program_id)?;
        expect_owner(account_b_ai, program_id)?;
        if account_a_ai.key == account_b_ai.key {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        // TB-1b (ADOPT upstream 0492ebbc): fail fast, before any market-state
        // work, if either side's leg-binding is stale.
        expect_portfolio_position_binding(
            &account_a_ai.try_borrow_data()?,
            account_a_portfolio_id,
            account_a_position_epoch,
        )?;
        expect_portfolio_position_binding(
            &account_b_ai.try_borrow_data()?,
            account_b_portfolio_id,
            account_b_position_epoch,
        )?;
        let (cfg_pre, mode_pre, max_market_slots, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        if mode_pre != MarketModeV16::Live {
            return Err(PercolatorError::EngineLockActive.into());
        }
        // Both owners sign every leg. Treat that value as their ceiling for the mutable base-fee
        // policy so a retained transaction cannot be charged a fee floor installed after signing.
        if legs
            .iter()
            .any(|leg| cfg_pre.trade_fee_base_bps > leg.fee_bps)
        {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        handle_batch_execute_zero_copy(
            program_id,
            signer_a.key,
            signer_b.key,
            market_ai,
            account_a_ai,
            account_b_ai,
            account_a_portfolio_id,
            account_a_position_epoch,
            account_b_portfolio_id,
            account_b_position_epoch,
            legs,
            max_market_slots,
            None,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn handle_batch_execute_zero_copy<'a>(
        _program_id: &Pubkey,
        account_a_owner_key: &Pubkey,
        account_b_owner_key: &Pubkey,
        market_ai: &AccountInfo<'a>,
        account_a_ai: &AccountInfo<'a>,
        account_b_ai: &AccountInfo<'a>,
        account_a_portfolio_id: u64,
        account_a_position_epoch: u64,
        account_b_portfolio_id: u64,
        account_b_position_epoch: u64,
        legs: &[ix::BatchTradeLeg],
        max_market_slots: usize,
        // ADOPT upstream 42ec8ab6: the signing taker's (account_a's) caller-supplied ceiling on
        // the AGGREGATE engine fee across this batch. `None` for `BatchTradeNoCpi` (both sides
        // sign every leg's `fee_bps` directly, no CPI-return-controlled aggregate to bound).
        // `Some(max_fee_atoms)` for `BatchTradeCpi`, where an external matcher's per-leg returns
        // otherwise decide the charged aggregate unilaterally.
        max_account_a_fee_atoms: Option<u128>,
    ) -> ProgramResult {
        if legs.is_empty() {
            return Err(PercolatorError::EngineNonProgress.into());
        }
        ensure_portfolio_storage_for_market_slots(account_a_ai, max_market_slots)?;
        ensure_portfolio_storage_for_market_slots(account_b_ai, max_market_slots)?;
        let mut cfg_after = None;
        {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (mut cfg, mut group) = state::market_view_mut(&mut market_data)?;
            // v1 scope: per-leg backing-domain trade fees are not split in a batch yet. If a backing
            // fee policy is configured, reject so we never silently skip those fees.
            if cfg.backing_trade_fee_policy_count != 0 {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            let mut account_a_data = account_a_ai.try_borrow_mut_data()?;
            let mut account_b_data = account_b_ai.try_borrow_mut_data()?;
            // TB-1b (ADOPT upstream 0492ebbc): live re-check right before mutation --
            // shared by BatchTradeNoCpi and BatchTradeCpi (both funnel through this
            // helper), same as the outer handlers' fail-fast checks above.
            expect_portfolio_position_binding(
                &account_a_data,
                account_a_portfolio_id,
                account_a_position_epoch,
            )?;
            expect_portfolio_position_binding(
                &account_b_data,
                account_b_portfolio_id,
                account_b_position_epoch,
            )?;
            let mut account_a =
                state::portfolio_view_mut_for_market_slots(&mut account_a_data, max_market_slots)?;
            let mut account_b =
                state::portfolio_view_mut_for_market_slots(&mut account_b_data, max_market_slots)?;
            expect_portfolio_view_account_key(&account_a, account_a_ai.key)?;
            expect_portfolio_view_account_key(&account_b, account_b_ai.key)?;
            expect_portfolio_view_owner(&account_a, account_a_owner_key)?;
            expect_portfolio_view_owner(&account_b, account_b_owner_key)?;

            // Pre-pass: per leg, read its oracle profile, pin the fee basis to the asset mark, and
            // build the SIGNED engine request. Reject duplicate assets (one leg per asset per batch).
            let mut requests: Vec<TradeRequestV16> = Vec::with_capacity(legs.len());
            // (asset_index, oracle_profile, reported_exec_price, fee_leg).
            //
            // A 7th element, `leg_size_q` (the raw signed per-leg size), used to
            // be carried through so the taker-only post-pass could pick the
            // correct single DOMAIN per leg (§1A.3) for the creator-leg budget
            // credit. The creator-fee-claim change (2026-07-23) routes that leg
            // to `cfg.creator_fee_claimable_atoms` instead of a domain budget,
            // so no per-leg domain is selected any more and the field is gone.
            //
            // B-4: `fee_basis_price` / `fee_bps_eff` / `abs_size` used to be carried so the
            // post-pass could call `batch_leg_fee`. The per-leg fee is now reconstructed HERE,
            // once, because the aggregate bound `batch_fee_charge_within_owed` needs the fee
            // the batch owes BEFORE the engine's aggregates are inspected. The post-pass reads
            // the cached value, so `batch_leg_fee` still runs exactly once per leg.
            // w1-s3: two trailing `i128` fields carry each leg's PRE-trade signed position on
            // both accounts (account_a's, account_b's), needed by the source-domain admission
            // gate below without re-reading the legs a second time.
            let mut leg_ctx: Vec<(usize, state::AssetOracleProfileV16, u64, u128, i128, i128)> =
                Vec::with_capacity(legs.len());
            // The fee this batch owes in total, reconstructed leg by leg. This is the ceiling
            // the engine's two aggregates must respect (see `batch_fee_charge_within_owed`).
            let mut fee_owed_total: u128 = 0;
            // w1-s3: whether ANY leg in this batch could newly touch a source domain on either
            // account -- gates whether the O(active legs) admission snapshot below is built at
            // all.
            let mut needs_source_domain_capacity = false;
            for leg in legs {
                let asset_index = leg.asset_index as usize;
                if requests.iter().any(|r| r.asset_index == asset_index) {
                    return Err(PercolatorError::InvalidInstruction.into());
                }
                require_asset_generation_view(&group, asset_index, leg.market_id)?;
                let mut oracle_profile = read_oracle_profile_from_view(&group, &cfg, asset_index)?;
                reject_permissionless_resolve_matured_live_for_profile_view(
                    &cfg,
                    &oracle_profile,
                    &group,
                )?;
                if leg.size_q == i128::MIN || leg.size_q == 0 {
                    return Err(PercolatorError::InvalidInstruction.into());
                }
                let abs_size = leg.size_q.unsigned_abs();
                // FIX (ADOPT upstream 06192caa/7a050c25, "canonical zero-move
                // funding accrual", adapted -- Wave-1 S4): same pre-position-change
                // settlement as the single-trade route, applied per leg (a batch
                // can span several assets, each with its own funding checkpoint).
                let account_a_position_for_accrual =
                    signed_position_for_asset_view(&group, &account_a, asset_index)?;
                let account_b_position_for_accrual =
                    signed_position_for_asset_view(&group, &account_b, asset_index)?;
                let reduces_existing =
                    trade_delta_reduces_existing(account_a_position_for_accrual, leg.size_q)
                        || trade_delta_reduces_existing(
                            account_b_position_for_accrual,
                            -leg.size_q,
                        );
                accrue_zero_move_funding_before_position_change_for_profile_view(
                    &mut oracle_profile,
                    &mut group,
                    asset_index,
                    reduces_existing,
                )
                .map_err(map_v16_error)?;
                let fee_basis_price = group.markets[asset_index]
                    .engine
                    .asset
                    .effective_price
                    .get();
                let fee_bps_eff = hybrid_trade_fee_bps_view(
                    &cfg,
                    &oracle_profile,
                    &group,
                    asset_index,
                    abs_size,
                    fee_basis_price,
                    leg.fee_bps,
                )?;
                requests.push(TradeRequestV16 {
                    asset_index,
                    size_q: leg.size_q,
                    exec_price: fee_basis_price,
                    fee_bps: fee_bps_eff,
                });
                let fee_leg = batch_leg_fee(abs_size, fee_basis_price, fee_bps_eff)?;
                fee_owed_total = fee_owed_total
                    .checked_add(fee_leg)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                // w1-s3: this leg's PRE-trade signed position on each account, and whether its
                // signed delta could newly touch either account's source-domain table.
                let account_a_position =
                    signed_position_for_asset_view(&group, &account_a, asset_index)?;
                let account_b_position =
                    signed_position_for_asset_view(&group, &account_b, asset_index)?;
                needs_source_domain_capacity |=
                    trade_delta_may_require_source_domain_capacity(account_a_position, leg.size_q)?
                        || trade_delta_may_require_source_domain_capacity(
                            account_b_position,
                            -leg.size_q,
                        )?;
                leg_ctx.push((
                    asset_index,
                    oracle_profile,
                    leg.exec_price,
                    fee_leg,
                    account_a_position,
                    account_b_position,
                ));
            }
            ensure_trade_portfolios_current_for_requests_view(
                &group, &account_a, &account_b, &requests,
            )?;
            // FIX (ADOPT upstream a84b45dd/d1bff017, "collect maintenance before value
            // debits"): crystallize each account's accrued maintenance fee BEFORE the batch
            // below can move capital/positions, so a batch trade cannot dodge fee accrued
            // since the account's last sync. Shared by BatchTradeNoCpi and BatchTradeCpi (both
            // funnel through this helper). Ordered before the w1-s3 admission snapshot
            // immediately below for the same reason as the single-trade path; a revert here
            // (including `EngineBStale`) is acceptable on this user-initiated path -- the
            // caller cranks first, then retries.
            collect_maintenance_fee_before_trade_view(&cfg, &mut group, &mut account_a)?;
            collect_maintenance_fee_before_trade_view(&cfg, &mut group, &mut account_b)?;
            // w1-s3 (upstream `cf0ce5d3`/`7a3a6f30`): reserve latent domains of surviving,
            // untouched legs before the engine's own batch-application primitive runs, using the
            // WHOLE leg request set so a leg that fully closes within this same batch correctly
            // releases its latent pair while a leg only touched (not closed) keeps both reserved
            // -- a per-leg-in-isolation check cannot make that distinction within one batch.
            if needs_source_domain_capacity {
                let mut admitted_source_domains_a =
                    reserved_source_domains_snapshot_for_trade_view(
                        &group, &account_a, &requests, false,
                    )?;
                let mut admitted_source_domains_b =
                    reserved_source_domains_snapshot_for_trade_view(
                        &group, &account_b, &requests, true,
                    )?;
                for (
                    asset_index,
                    _oracle_profile,
                    _reported_price,
                    _fee_leg,
                    account_a_position,
                    account_b_position,
                ) in leg_ctx.iter()
                {
                    let request = requests
                        .iter()
                        .find(|request| request.asset_index == *asset_index)
                        .ok_or(PercolatorError::InvalidInstruction)?;
                    ensure_trade_delta_source_domain_capacity_view(
                        &mut admitted_source_domains_a,
                        *asset_index,
                        *account_a_position,
                        request.size_q,
                    )?;
                    ensure_trade_delta_source_domain_capacity_view(
                        &mut admitted_source_domains_b,
                        *asset_index,
                        *account_b_position,
                        -request.size_q,
                    )?;
                }
            }

            // sync/w1-abacking (57d04a7d): the wrapper's per-leg backing-domain FEE policy is
            // already refused above when configured (`v1 scope` guard), but a source domain can
            // still back a NEW counterparty-backed lien through this batch independent of that
            // fee policy, so the landing-time freshness check below needs these snapshots
            // regardless.
            let backing_before_a = source_counterparty_backing_snapshot_view(&account_a)?;
            let backing_before_b = source_counterparty_backing_snapshot_view(&account_b)?;
            let source_lien_before_a =
                source_lien_effective_reserved_snapshot_for_trade_view(&account_a)?;
            let source_lien_before_b =
                source_lien_effective_reserved_snapshot_for_trade_view(&account_b)?;

            // Taker-only (design §1A.3): batches never reorder -- account_a is
            // always the engine's first (long_account) positional slot for
            // the whole call, and account_a is always the taker (§1A.2).
            let outcome = group
                .execute_batch_with_fee_loss_stale_scoped_not_atomic(
                    &mut account_a,
                    &mut account_b,
                    &requests,
                    true,
                )
                .map_err(map_v16_error)?;
            // FIX (ADOPT upstream 42ec8ab6, "bound aggregate batch cpi consent"): for
            // BatchTradeCpi, the taker's signed `max_fee_atoms` is a hard ceiling on the
            // AGGREGATE engine fee charged to account_a across this batch (distinct from
            // `batch_fee_charge_within_owed` below, which only checks the two aggregates never
            // exceed what the RECONSTRUCTED per-leg `fee_bps` consent already owes -- a matcher
            // that returns adverse-but-still-"owed" fills can still land within that bound while
            // exceeding what the taker was willing to pay in absolute atoms for this specific
            // batch). Checked immediately once `outcome` exists, same placement as upstream, so
            // an over-cap batch aborts before any further post-trade accounting.
            if max_account_a_fee_atoms.is_some_and(|cap| outcome.fee_a > cap) {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            // FIX (ADOPT upstream 3496acf0, "enforce side OI caps"): checked per-leg
            // immediately after the engine mutates OI on this batch, before any other
            // post-trade check, so an over-cap post-state on ANY leg's asset aborts the
            // whole batch atomically.
            for request in &requests {
                ensure_trade_side_oi_cap_view(&group, request.asset_index)?;
            }
            // sync/w1-abacking (57d04a7d): a retained transaction can land after the engine's
            // cached slot and a provider's signed backing expiry. Only newly-created
            // counterparty-backed liens need this landing-time check; insurance-backed liens
            // and legs that do not increase a lien remain live.
            ensure_new_counterparty_backed_liens_fresh_for_trade_view(
                &group,
                authenticated_market_slot_or_fallback_view(&group),
                backing_before_a.as_ref(),
                &account_a,
                backing_before_b.as_ref(),
                &account_b,
            )?;

            // Taker-only + N1 (design §1A.3/§1A.4). `outcome.fee_a`/`outcome.fee_b` are the
            // engine's AGGREGATE totals across all legs.
            //
            // B-4 (W-14): this used to refuse `fee_a > 0 && fee_b > 0` outright, on the ground
            // that exactly one physical account pays across the whole batch. Engine #160 makes
            // that state LEGITIMATE: a batch runs several fills against a RUNNING capital, and
            // a taker that can pay one leg's fee in full but the next only in part is charged
            // what it has while the solvent maker is charged the REMAINDER through the N1
            // fallback (`percolator 2c38570a:src/v16.rs:18172-18178`, `:18213`, `:18224-18227`,
            // and `:18229-18230` "BOTH return values can now be non-zero"). The proof the old
            // comment cited, `proof_v16_taker_only_charges_exactly_one_side`, no longer exists
            // at that ref. Refusing the state would block exactly the batches the engine fix
            // was written to make chargeable.
            //
            // The wrapper still does not trust the ABI blindly -- it checks the invariant that
            // DOES hold, in the same position, before any fee is credited or any mark moved:
            // the two aggregates together never exceed the fee this batch owes.
            if !batch_fee_charge_within_owed(outcome.fee_a, outcome.fee_b, fee_owed_total) {
                return Err(PercolatorError::EngineArithmeticOverflow.into());
            }

            // Post-pass: accrue each leg's four-way fee split into the four config counters and
            // drive each asset's hybrid mark. Fees are reconstructed deterministically per leg;
            // the running total must equal the engine's aggregate or we refuse the batch (no
            // silent mis-accounting). Symmetric with the single-trade credit site above.
            //
            // Creator-fee-claim change (2026-07-23): the creator leg no longer lands in a domain
            // insurance budget here either -- it accrues into
            // `cfg.creator_fee_claimable_atoms` via `creator_cut_running_total`, exactly like the
            // other three legs' running totals, and is folded in once after the loop.
            let mut reconstructed_total: u128 = 0;
            let mut cfg_dirty = false;
            let mut protocol_cut_running_total: u128 = 0;
            let mut lp_cut_running_total: u128 = 0;
            let mut insurance_cut_running_total: u128 = 0;
            let mut creator_cut_running_total: u128 = 0;
            for (
                asset_index,
                oracle_profile,
                reported_price,
                fee_leg,
                _account_a_position,
                _account_b_position,
            ) in leg_ctx.iter_mut()
            {
                let fee_leg = *fee_leg;
                if fee_leg != 0 {
                    let split_leg = policy_v16::split_trade_fee(
                        fee_leg,
                        constants::PROTOCOL_FEE_BPS,
                        cfg.creator_share_bps,
                        cfg.lp_share_bps,
                        cfg.insurance_share_bps,
                    )?;
                    protocol_cut_running_total = protocol_cut_running_total
                        .checked_add(split_leg.protocol)
                        .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                    lp_cut_running_total = lp_cut_running_total
                        .checked_add(split_leg.lp)
                        .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                    insurance_cut_running_total = insurance_cut_running_total
                        .checked_add(split_leg.insurance)
                        .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                    creator_cut_running_total = creator_cut_running_total
                        .checked_add(split_leg.creator)
                        .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                    // GH#420: credit THIS leg's creator cut to THIS leg's asset
                    // profile. A batch can span several assets, so a single
                    // post-loop total cannot say which creator earned what — that
                    // is precisely how every asset's fees ended up in one pot
                    // payable to asset 0's admin.
                    //
                    // Persisted by the existing `write_oracle_profile_to_view` at
                    // the end of this same iteration; no extra write.
                    oracle_profile.creator_fee_claimable_atoms = oracle_profile
                        .creator_fee_claimable_atoms
                        .checked_add(
                            u64::try_from(split_leg.creator)
                                .map_err(|_| PercolatorError::EngineArithmeticOverflow)?,
                        )
                        .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                    // NOTE (behaviour preserved): the creator leg used to be
                    // credited only under `if taker_paid { .. } else if
                    // maker_paid { .. }`, i.e. dropped when NEITHER side paid.
                    // Accruing it unconditionally (as the other three legs
                    // already did) is equivalent: if neither side paid,
                    // `engine_total` is 0 while `reconstructed_total` is
                    // nonzero, so the post-loop cross-check below hard-rejects
                    // the whole batch and no counter is ever written back.
                }
                reconstructed_total = reconstructed_total
                    .checked_add(fee_leg)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                update_hybrid_mark_after_trade_view(
                    oracle_profile,
                    &group,
                    *asset_index,
                    *reported_price,
                    fee_leg,
                )?;
                write_oracle_profile_to_view(&mut group, *asset_index, oracle_profile)?;
                if *asset_index == 0 && oracle_v16::profile_is_price_managed(oracle_profile) {
                    cfg.mark_ewma_e6 = oracle_profile.mark_ewma_e6;
                    cfg.mark_ewma_last_slot = oracle_profile.mark_ewma_last_slot;
                    cfg_dirty = true;
                }
            }
            let engine_total = outcome
                .fee_a
                .checked_add(outcome.fee_b)
                .ok_or(PercolatorError::EngineArithmeticOverflow)?;
            if reconstructed_total != engine_total {
                return Err(PercolatorError::EngineArithmeticOverflow.into());
            }
            if protocol_cut_running_total != 0
                || lp_cut_running_total != 0
                || insurance_cut_running_total != 0
                || creator_cut_running_total != 0
            {
                cfg.protocol_fee_accrued_atoms = cfg
                    .protocol_fee_accrued_atoms
                    .checked_add(protocol_cut_running_total)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                cfg.lp_fee_accrued_atoms = cfg
                    .lp_fee_accrued_atoms
                    .checked_add(lp_cut_running_total)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                cfg.insurance_reserve_accrued_atoms = cfg
                    .insurance_reserve_accrued_atoms
                    .checked_add(insurance_cut_running_total)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                // u128 -> u64 narrowing, same as the single-trade site: the
                // counter is u64 because it had to fit the spare 8 bytes of
                // `_padding_split`. Overflow ERRORS the whole batch rather
                // than wrapping or saturating.
                // GH#420: intentionally NOT folded into the config counter here.
                // The batch's creator cut is credited PER LEG to that leg's own
                // asset profile inside the loop above, because a batch can span
                // several assets and a single running total cannot say which
                // creator earned what. `creator_cut_running_total` is retained
                // solely as the write-back trigger below and as the value the
                // conservation assertions compare against.
                let _ = creator_cut_running_total;
                // CRITICAL: same write-back-forcing requirement as the
                // single-trade site -- a missed write-back here would
                // silently discard accrued fees for all four legs.
                cfg_dirty = true;
            }
            if cfg_dirty {
                cfg_after = Some(cfg);
            }

            group.validate_shape().map_err(map_v16_error)?;

            let source_lien_after_a =
                source_lien_effective_reserved_snapshot_for_trade_view(&account_a)?;
            let source_lien_after_b =
                source_lien_effective_reserved_snapshot_for_trade_view(&account_b)?;
            ensure_new_source_lien_domains_full_rate_for_trade_view(
                &group,
                source_lien_before_a.as_ref(),
                source_lien_after_a.as_ref(),
                source_lien_before_b.as_ref(),
                source_lien_after_b.as_ref(),
            )?;
            // w1-s3: independent post-hoc backstop, mirroring the single-trade site.
            ensure_source_domain_growth_within_wrapper_bound(
                source_lien_before_a.len(),
                source_lien_after_a.len(),
            )?;
            ensure_source_domain_growth_within_wrapper_bound(
                source_lien_before_b.len(),
                source_lien_after_b.len(),
            )?;
        }
        if let Some(cfg) = cfg_after {
            state::write_wrapper_config(&mut market_ai.try_borrow_mut_data()?, &cfg)?;
        }
        Ok(())
    }

    #[inline(never)]
    // TB-1b: grew past the clippy threshold with the 4 new portfolio-identity
    // binding params.
    #[allow(clippy::too_many_arguments)]
    fn handle_trade_nocpi<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        account_a_portfolio_id: u64,
        account_a_position_epoch: u64,
        account_b_portfolio_id: u64,
        account_b_position_epoch: u64,
        asset_index: u16,
        market_id: u64,
        size_q: i128,
        exec_price: u64,
        fee_bps: u64,
        backing_fee_cap_bps: u16,
    ) -> ProgramResult {
        let signer_a = account(accounts, 0)?;
        let signer_b = account(accounts, 1)?;
        let market_ai = account(accounts, 2)?;
        let account_a_ai = account(accounts, 3)?;
        let account_b_ai = account(accounts, 4)?;
        expect_signer(signer_a)?;
        expect_signer(signer_b)?;
        expect_writable(market_ai)?;
        expect_writable(account_a_ai)?;
        expect_writable(account_b_ai)?;
        expect_owner(market_ai, program_id)?;
        expect_owner(account_a_ai, program_id)?;
        expect_owner(account_b_ai, program_id)?;
        if account_a_ai.key == account_b_ai.key {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        // TB-1b (ADOPT upstream 0492ebbc): fail fast, before any market-state work.
        expect_portfolio_position_binding(
            &account_a_ai.try_borrow_data()?,
            account_a_portfolio_id,
            account_a_position_epoch,
        )?;
        expect_portfolio_position_binding(
            &account_b_ai.try_borrow_data()?,
            account_b_portfolio_id,
            account_b_position_epoch,
        )?;
        let (cfg_pre, mode_pre, max_market_slots, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        if mode_pre != MarketModeV16::Live {
            return Err(PercolatorError::EngineLockActive.into());
        }
        // Both owners sign `fee_bps`; a later policy update cannot increase either owner's base
        // fee. Dynamic mark-movement fees remain derived by the shared trade path.
        if cfg_pre.trade_fee_base_bps > fee_bps {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        // ADOPT upstream 2d9eb5e9 ("Bind single trades to backing fee consent"): both owners
        // co-sign this single `backing_fee_cap_bps`, so it binds both sides of a direct trade
        // symmetrically -- previously neither had ANY way to cap the backing-domain fee they
        // could be charged (only a matcher-CPI counterparty had that option, via e24cf78e).
        if backing_fee_cap_bps > 10_000 {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        handle_trade_nocpi_zero_copy(
            program_id,
            signer_a.key,
            signer_b.key,
            market_ai,
            account_a_ai,
            account_b_ai,
            account_a_portfolio_id,
            account_a_position_epoch,
            account_b_portfolio_id,
            account_b_position_epoch,
            asset_index,
            market_id,
            size_q,
            exec_price,
            fee_bps,
            Some(backing_fee_cap_bps),
            Some(backing_fee_cap_bps),
            max_market_slots,
        )
    }

    fn active_leg_for_asset_view(
        portfolio: &percolator::PortfolioV16ViewMut<'_>,
        asset_index: usize,
    ) -> Result<percolator::PortfolioLegV16, ProgramError> {
        let mut found = None;
        let mut slot = 0usize;
        while slot < portfolio.header.legs.len() {
            let leg = portfolio.header.legs[slot]
                .try_to_runtime()
                .map_err(map_v16_error)?;
            if leg.active && leg.asset_index as usize == asset_index {
                if found.replace(leg).is_some() {
                    return Err(PercolatorError::EngineHiddenLeg.into());
                }
            }
            slot += 1;
        }
        found.ok_or(PercolatorError::EngineInvalidLeg.into())
    }

    fn source_credit_has_live_amounts(source: SourceCreditStateV16) -> bool {
        source.positive_claim_bound_num != 0
            || source.exact_positive_claim_num != 0
            || source.fresh_reserved_backing_num != 0
            || source.spent_backing_num != 0
            || source.provider_receivable_num != 0
            || source.valid_liened_backing_num != 0
            || source.impaired_liened_backing_num != 0
            || source.insurance_credit_reserved_num != 0
            || source.valid_liened_insurance_num != 0
            || source.impaired_liened_insurance_num != 0
    }

    fn ensure_source_credit_full_rate_for_domain_view(
        group: &state::MarketViewMutV16<'_>,
        domain: usize,
    ) -> ProgramResult {
        let max_market_slots = group.header.config.max_market_slots.get() as usize;
        let asset_index = domain / 2;
        if max_market_slots > group.markets.len() || asset_index >= max_market_slots {
            return Err(PercolatorError::EngineInvalidConfig.into());
        }
        let slot = &group.markets[asset_index].engine;
        let source = if domain % 2 == 0 {
            slot.source_credit_long
                .try_to_runtime()
                .map_err(map_v16_error)?
        } else {
            slot.source_credit_short
                .try_to_runtime()
                .map_err(map_v16_error)?
        };
        if source_credit_has_live_amounts(source)
            && source.credit_rate_num != percolator::CREDIT_RATE_SCALE
        {
            return Err(PercolatorError::EngineLockActive.into());
        }
        Ok(())
    }

    fn ensure_new_source_lien_domains_full_rate_for_trade_view(
        group: &state::MarketViewMutV16<'_>,
        before_a: &[(u32, u128)],
        after_a: &[(u32, u128)],
        before_b: &[(u32, u128)],
        after_b: &[(u32, u128)],
    ) -> ProgramResult {
        // For each account, any domain whose source-lien effective reserve INCREASED across the trade
        // must have its source credit at full rate. After-state is the sparse occupied set (<= CAP);
        // look up the before value by domain (default 0 for a freshly-occupied domain).
        for (after, before) in [(after_a, before_a), (after_b, before_b)] {
            let mut i = 0usize;
            while i < after.len() {
                let (domain, after_val) = after[i];
                if after_val > sparse_domain_value_lookup(before, domain) {
                    ensure_source_credit_full_rate_for_domain_view(group, domain as usize)?;
                }
                i += 1;
            }
        }
        Ok(())
    }

    /// sync/w1-abacking (adopt upstream 57d04a7d, "reject newly backed liens after expiry").
    ///
    /// A retained transaction can land after the engine's cached slot and a provider's signed
    /// backing expiry. Only newly-created counterparty-backed liens need this landing-time
    /// check; insurance-backed liens and trades that do not increase a lien remain live.
    fn ensure_new_counterparty_backed_liens_fresh_for_trade_view(
        group: &state::MarketViewMutV16<'_>,
        authenticated_slot: u64,
        before_a: &[(u32, u128)],
        account_a: &percolator::PortfolioV16ViewMut<'_>,
        before_b: &[(u32, u128)],
        account_b: &percolator::PortfolioV16ViewMut<'_>,
    ) -> ProgramResult {
        for (account, before) in [(account_a, before_a), (account_b, before_b)] {
            for source in account.header.source_domains.iter() {
                if !source.is_occupied() {
                    continue;
                }
                let domain = source.domain.get();
                let after = source.source_lien_counterparty_backing_num.get();
                if after <= sparse_domain_value_lookup(before, domain) {
                    continue;
                }
                let (_, bucket) = backing_domain_parts_view(group, domain as usize)?;
                if bucket.status != percolator::BackingBucketStatusV16::Fresh
                    || bucket.expiry_slot <= authenticated_slot
                {
                    return Err(PercolatorError::EngineStale.into());
                }
            }
        }
        Ok(())
    }

    // Sparse before/after trade snapshots: one (domain, value) entry per OCCUPIED source-domain slot
    // (<= PORTFOLIO_SOURCE_DOMAIN_CAP), so the trade path is O(active source-domains), not O(N).
    fn sparse_domain_value_lookup(snapshot: &[(u32, u128)], domain: u32) -> u128 {
        let mut i = 0usize;
        while i < snapshot.len() {
            if snapshot[i].0 == domain {
                return snapshot[i].1;
            }
            i += 1;
        }
        0
    }

    fn source_lien_effective_reserved_snapshot_for_trade_view(
        account: &percolator::PortfolioV16ViewMut<'_>,
    ) -> Result<alloc::boxed::Box<[(u32, u128)]>, ProgramError> {
        let mut out = Vec::new();
        for slot in account.header.source_domains.iter() {
            if slot.is_occupied() {
                out.push((slot.domain.get(), slot.source_lien_effective_reserved.get()));
            }
        }
        Ok(out.into_boxed_slice())
    }

    // ---------------------------------------------------------------------------------------
    // Sync unit w1-s3 (upstream `cf0ce5d3` + `7a3a6f30`, "reserve latent domains of surviving
    // positions at admission"): the engine's own `source_domain_slot_or_insert` is a hard
    // fail-closed backstop (`V16Error::LockActive`) if a portfolio tries to claim a
    // `source_domains` slot beyond its fixed `PORTFOLIO_SOURCE_DOMAIN_CAP` array, so an
    // over-full table always reverts atomically, with or without this gate. What this gate buys
    // is correctness of *when* and *for whom* that revert happens: without it, an admission
    // check that only asks "does *this* trade's delta need a new domain slot?" can admit a
    // trade that fills the account's slot table with domains for the legs it touches, while
    // failing to reserve the LATENT (currently-unoccupied) domain of *other*, untouched, still-
    // open legs on the same portfolio. Those other legs may later need that latent domain (flip
    // side, force-close, ADL, backing-expiry crank) and by then the table can be full, so *that*
    // liveness-critical operation is the one that hits `LockActive`, not the trade that actually
    // caused the exhaustion. Wrapper-local, zero engine change, zero wire/ABI change (operates
    // entirely on the already-shared `PortfolioAccountV16Account.source_domains` array). Worst-
    // case regression from a botched port is an over-eager reject on a legitimate trade (a
    // liveness regression, not a fund-safety issue) -- the engine's own hard backstop is
    // unchanged either way. See ABI_LANDMINE_REGISTRY.md: this struct/const are fresh names,
    // zero collisions with any tracked wrapper struct.
    struct SourceDomainAdmissionSnapshot {
        domains: [u32; percolator::PORTFOLIO_SOURCE_DOMAIN_CAP],
        len: usize,
    }

    impl SourceDomainAdmissionSnapshot {
        fn contains(&self, domain: u32) -> bool {
            let mut i = 0usize;
            while i < self.len {
                if self.domains[i] == domain {
                    return true;
                }
                i += 1;
            }
            false
        }

        fn push_reserved(&mut self, domain: u32) -> ProgramResult {
            if self.contains(domain) {
                return Ok(());
            }
            if self.len >= constants::WRAPPER_MAX_BOUNDED_SOURCE_DOMAINS {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            if self.len >= self.domains.len() {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            self.domains[self.len] = domain;
            self.len += 1;
            Ok(())
        }
    }

    /// Builds the admission snapshot for one account ahead of a trade/batch: every domain the
    /// account already OCCUPIES, plus -- for every OTHER active leg not being fully closed by
    /// this trade's own request set -- BOTH of that leg's (long, short) domains, reserved as
    /// latent even though the leg currently occupies only one. `requests` is the full leg
    /// request set for this instruction (one element for a single trade, N for a batch);
    /// `invert_requests` flips the sign of each request's `size_q` before comparing it to the
    /// account's current signed position, since a single-trade request is expressed relative to
    /// account_a and must be negated to evaluate account_b's side of the same trade.
    fn reserved_source_domains_snapshot_for_trade_view(
        group: &state::MarketViewMutV16<'_>,
        account: &percolator::PortfolioV16ViewMut<'_>,
        requests: &[TradeRequestV16],
        invert_requests: bool,
    ) -> Result<SourceDomainAdmissionSnapshot, ProgramError> {
        let mut out = SourceDomainAdmissionSnapshot {
            domains: [0u32; percolator::PORTFOLIO_SOURCE_DOMAIN_CAP],
            len: 0,
        };
        for slot in account.header.source_domains.iter() {
            if slot.is_occupied() {
                if out.len >= out.domains.len() {
                    return Err(PercolatorError::InvalidInstruction.into());
                }
                out.domains[out.len] = slot.domain.get();
                out.len += 1;
            }
        }
        // Other active legs retain both future settlement domains. A leg fully closed
        // by this trade can release its latent pair, but never its occupied claims.
        for pod in &account.header.legs {
            let leg = pod.try_to_runtime().map_err(map_v16_error)?;
            if !leg.active {
                continue;
            }
            let asset_index = leg.asset_index as usize;
            if let Some(request) = requests.iter().find(|r| r.asset_index == asset_index) {
                let current_q = signed_position_for_asset_view(group, account, asset_index)?;
                let delta = if invert_requests {
                    -request.size_q
                } else {
                    request.size_q
                };
                if current_q.checked_add(delta) == Some(0) {
                    continue;
                }
            }
            let (long_domain, short_domain) =
                percolator::v16_domain_pair_for_asset_index(asset_index).map_err(map_v16_error)?;
            out.push_reserved(long_domain as u32)?;
            out.push_reserved(short_domain as u32)?;
        }
        Ok(out)
    }

    fn ensure_trade_delta_source_domain_capacity_view(
        occupied_domains: &mut SourceDomainAdmissionSnapshot,
        asset_index: usize,
        current_q: i128,
        delta_q: i128,
    ) -> ProgramResult {
        if !trade_delta_may_require_source_domain_capacity(current_q, delta_q)? {
            return Ok(());
        }
        if occupied_domains.len > constants::WRAPPER_MAX_BOUNDED_SOURCE_DOMAINS {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        let (long_domain, short_domain) =
            percolator::v16_domain_pair_for_asset_index(asset_index).map_err(map_v16_error)?;
        for domain in [long_domain as u32, short_domain as u32] {
            if occupied_domains.contains(domain) {
                continue;
            }
            occupied_domains.push_reserved(domain)?;
        }
        Ok(())
    }

    fn trade_delta_may_require_source_domain_capacity(
        current_q: i128,
        delta_q: i128,
    ) -> Result<bool, ProgramError> {
        let post_q = current_q
            .checked_add(delta_q)
            .ok_or(PercolatorError::EngineArithmeticOverflow)?;
        if current_q == 0 {
            return Ok(delta_q != 0);
        }
        if current_q > 0 {
            return Ok(delta_q > 0 || post_q < 0);
        }
        Ok(delta_q < 0 || post_q > 0)
    }

    fn ensure_source_domain_growth_within_wrapper_bound(
        before_count: usize,
        after_count: usize,
    ) -> ProgramResult {
        if after_count > before_count && after_count > constants::WRAPPER_MAX_BOUNDED_SOURCE_DOMAINS
        {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        Ok(())
    }
    // ---------------------------------------------------------------------------------------

    #[inline(never)]
    fn handle_force_close_abandoned_asset<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        asset_index: u16,
        now_slot: u64,
        close_q: u128,
    ) -> ProgramResult {
        let cranker = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let account_a_ai = account(accounts, 2)?;
        let account_b_ai = account(accounts, 3)?;
        expect_signer(cranker)?;
        expect_writable(market_ai)?;
        expect_writable(account_a_ai)?;
        expect_writable(account_b_ai)?;
        expect_owner(market_ai, program_id)?;
        expect_owner(account_a_ai, program_id)?;
        expect_owner(account_b_ai, program_id)?;
        if account_a_ai.key == account_b_ai.key || close_q == 0 {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        let asset_index_usize = asset_index as usize;
        let authenticated_slot = authenticated_slot_or_fallback(now_slot);
        let (_, mode_pre, max_market_slots, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        if mode_pre != MarketModeV16::Live {
            return Err(PercolatorError::EngineLockActive.into());
        }
        ensure_portfolio_storage_for_market_slots(account_a_ai, max_market_slots)?;
        ensure_portfolio_storage_for_market_slots(account_b_ai, max_market_slots)?;

        let mut market_data = market_ai.try_borrow_mut_data()?;
        let (cfg, mut group) = state::market_view_mut(&mut market_data)?;
        if group.header.mode != 0
            || asset_index_usize >= group.header.config.max_market_slots.get() as usize
            || asset_index_usize >= group.markets.len()
            || cfg.force_close_delay_slots == 0
        {
            return Err(PercolatorError::EngineLockActive.into());
        }
        // W-23(a): restore the upstream maturity gate missing from this handler. Once
        // a Live market has matured into a permissionless resolve, a cranker-driven
        // force-close must not still mutate positions — the same gate guards every
        // other Live-mode mutation path in this file (13 other call sites); this
        // handler is the one place it was never wired, in upstream's position
        // (`percolator-prog upstream/main:src/v16_program.rs:9083`, right after the
        // mode/config early-return and before the asset lifecycle check).
        reject_permissionless_resolve_matured_live_view(&cfg, &group)?;
        let asset = group.markets[asset_index_usize].engine.asset;
        if asset.lifecycle != ASSET_LIFECYCLE_RECOVERY {
            return Err(PercolatorError::EngineLockActive.into());
        }
        let profile = read_oracle_profile_from_view(&group, &cfg, asset_index_usize)?;
        let shutdown_slot = profile.last_good_oracle_slot;
        if shutdown_slot == 0
            || authenticated_slot < shutdown_slot
            || authenticated_slot.saturating_sub(shutdown_slot) < cfg.force_close_delay_slots
        {
            return Err(PercolatorError::EngineLockActive.into());
        }
        let frozen_mark = asset.effective_price.get();
        if frozen_mark == 0 || frozen_mark > percolator::MAX_ORACLE_PRICE {
            return Err(PercolatorError::OracleInvalid.into());
        }

        let mut account_a_data = account_a_ai.try_borrow_mut_data()?;
        let mut account_b_data = account_b_ai.try_borrow_mut_data()?;
        let mut account_a =
            state::portfolio_view_mut_for_market_slots(&mut account_a_data, max_market_slots)?;
        let mut account_b =
            state::portfolio_view_mut_for_market_slots(&mut account_b_data, max_market_slots)?;
        expect_portfolio_view_account_key(&account_a, account_a_ai.key)?;
        expect_portfolio_view_account_key(&account_b, account_b_ai.key)?;
        account_a
            .validate_with_market(&group.as_view())
            .map_err(map_v16_error)?;
        account_b
            .validate_with_market(&group.as_view())
            .map_err(map_v16_error)?;
        // FIX (ADOPT upstream a84b45dd/d1bff017, "collect maintenance before value debits"):
        // crystallize each account's accrued maintenance fee BEFORE this force-close can move
        // capital/positions, so an abandoned-asset force-close cannot dodge fee accrued since
        // either account's last sync. A revert here (including `EngineBStale`) is acceptable:
        // this permissionless force-close path is retried after a plain crank makes the
        // account current again, unlike the crank handler itself which must never revert on
        // this specific error (see `handle_permissionless_crank_zero_copy`).
        collect_maintenance_fee_before_value_debit_view(&cfg, &mut group, &mut account_a)?;
        collect_maintenance_fee_before_value_debit_view(&cfg, &mut group, &mut account_b)?;
        let leg_a = active_leg_for_asset_view(&account_a, asset_index_usize)?;
        let leg_b = active_leg_for_asset_view(&account_b, asset_index_usize)?;
        if leg_a.side == leg_b.side {
            return Err(PercolatorError::EngineInvalidLeg.into());
        }
        // C-W-02 / B-3 — size the close through the ENGINE primitive, not a raw-basis clamp.
        //
        // This used to clamp the caller's budget with
        // `close_q.min(|leg_a.basis_pos_q|).min(|leg_b.basis_pos_q|)` and hand the result to
        // `execute_trade_with_fee_loss_stale_scoped_not_atomic` itself. On a Recovery pair that
        // has taken an ADL haircut the RAW basis exceeds the EFFECTIVE quantity, so the clamp
        // asked to close more than the position that exists; the route then classified as a
        // sign flip (`percolator 2c38570a:spec.md:1215`), `kernel_position_route_requires_unit_adl`
        // fired and `require_asset_risk_change_allowed` refused the whole call with
        // `LockActive` -> `Custom(21)`. Measured on an ADL'd pair: raw 1_990_000 / 1_989_949 vs
        // effective 1_980_000 on both sides, and tag 64 with the documented "pass the full size"
        // budget was unclosable.
        //
        // The spec draws the line at the QUANTITY, not the instruction: "liquidation sizing,
        // full-close detection ... all use `effective_pos_q`; raw basis remains only for K/F
        // settlement and social-loss weight accounting" (`av:spec.md:108-112`).
        // `force_close_recovery_pair_not_atomic` (`2c38570a:src/v16.rs:18542`) is the engine's
        // own implementation of that rule -- it clamps
        // `close_request_q.min(effective_a).min(effective_b).min(oi_eff_long_q).min(oi_eff_short_q)`
        // (`:18565-18571`), settles at the same frozen mark (`asset.effective_price`, `:18581`)
        // with `fee_bps: 0` and the same `taker_is_long_account: true` selector in both
        // orientations (`:18586-18594`), and returns the quantity it landed. This fork shipped
        // that primitive with NO caller; upstream's wrapper calls it
        // (`percolator-prog upstream/main:src/v16_program.rs:9078-9085`). Adopting the call is
        // B-3: the caller's `close_q` stays a work BUDGET, and the engine decides the size.
        //
        // NOT adopted from upstream: its preceding one-sided-residue branch
        // (`upstream/main:9037-9077`), which routes a pair with one zero-position side through
        // `forfeit_recovery_leg_not_atomic` under this PERMISSIONLESS instruction. See the
        // `cw02_` tests and `verify/fixes/C-W-02.md` for the measurements behind that decision:
        // it would pass a POSITION quantity into an engine parameter that is a collateral-ATOM
        // budget (`b_loss_atom_budget`, `2c38570a:src/v16.rs:21391`), letting any cranker spend
        // an owner's principal. Our fork keeps that case on the owner-signed tag 43
        // `ForfeitRecoveryLeg`.
        group
            .force_close_recovery_pair_not_atomic(
                &mut account_a,
                &mut account_b,
                asset_index_usize,
                close_q,
            )
            .map_err(map_v16_error)?;
        group.validate_shape().map_err(map_v16_error)?;
        account_a
            .validate_with_market(&group.as_view())
            .map_err(map_v16_error)?;
        account_b
            .validate_with_market(&group.as_view())
            .map_err(map_v16_error)
    }

    fn matcher_tail_start_or_verify_lp_config<'a>(
        account_b_ai: &AccountInfo<'a>,
        expected_matcher_sequence: u64,
        matcher_prog_key: &Pubkey,
        matcher_ctx_key: &Pubkey,
        matcher_delegate_key: &Pubkey,
    ) -> Result<(usize, u16), ProgramError> {
        let account_b_data = account_b_ai.try_borrow_data()?;
        // W3-matcher (ADOPT upstream `edc8ce74`, "bind cpi trades to matcher
        // incarnation"): must be checked BEFORE reading/trusting `cfg` below --
        // the signing taker's `account_b_matcher_sequence` has to match the
        // LIVE sequence on account_b, or a CPI trade signed under an OLD
        // matcher-config incarnation (tuple/cap/expiry may still coincidentally
        // match post-reconfigure) could otherwise still execute.
        if state::read_portfolio_matcher_sequence(&account_b_data)? != expected_matcher_sequence {
            return Err(PercolatorError::EngineStale.into());
        }
        let cfg = state::read_portfolio_matcher_config(&account_b_data)?;
        if cfg.enabled() != 1
            || cfg.matcher_program != matcher_prog_key.to_bytes()
            || cfg.matcher_context != matcher_ctx_key.to_bytes()
            || cfg.matcher_delegate != matcher_delegate_key.to_bytes()
        {
            return Err(PercolatorError::Unauthorized.into());
        }
        // TB-1b (ADOPT upstream 0b838425, "expire matcher capabilities"): a
        // `SetMatcherConfig` grant is only live while the current slot is
        // strictly before the LP's own signed `expiry_slot` -- an expired grant
        // (or one that was never given a `expiry_slot`, i.e. still 0) must not
        // authorize a CPI trade even though `enabled == 1` and the
        // program/context/delegate triple still matches.
        //
        // `authenticated_slot_or_fallback(0)` (never a bare `Clock::get()?`):
        // a native/LiteSVM test harness with no Clock sysvar installed must not
        // hard-fail every CPI trade through an already-configured, non-expiring
        // matcher -- falling back to slot 0 preserves "live" for any nonzero
        // `expiry_slot` (the common case) while still enforcing real expiry
        // wherever the Clock sysvar IS available (devnet/mainnet/LiteSVM).
        let expiry_slot = state::read_portfolio_matcher_expiry(&account_b_data)?;
        if !state::matcher_capability_is_live(expiry_slot, authenticated_slot_or_fallback(0)) {
            return Err(PercolatorError::Unauthorized.into());
        }
        Ok((7, cfg.trade_fee_cap_bps()))
    }

    #[allow(clippy::too_many_arguments)]
    fn validate_matcher_tail<'a>(
        tail: &'a [AccountInfo<'a>],
        signer_a_ai: &AccountInfo,
        market_ai: &AccountInfo,
        account_a_ai: &AccountInfo,
        account_b_ai: &AccountInfo,
        matcher_prog: &AccountInfo,
        matcher_ctx: &AccountInfo,
        matcher_delegate: &AccountInfo,
        program_id: &Pubkey,
    ) -> ProgramResult {
        if tail.len() > constants::MAX_MATCHER_TAIL_ACCOUNTS {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        for ai in tail {
            // FIX W1 (upstream #152, CRITICAL): a tail account forwarded to the untrusted
            // external matcher previously carried its `is_signer` flag verbatim. A hostile
            // matcher could re-list the taker's own wallet (or any other signer) in the tail
            // and use its forwarded signer privilege in a nested CPI (e.g. a System Program
            // transfer) before returning an otherwise-valid fill -- wallet-drain-grade, zero
            // privilege required beyond routing a trade through a malicious LP-registered
            // matcher. Reject any tail entry that is a signer, and (matching upstream) also
            // reject aliasing any of the trusted accounts this call already knows about.
            if ai.is_signer
                || ai.key == signer_a_ai.key
                || ai.key == market_ai.key
                || ai.key == account_a_ai.key
                || ai.key == account_b_ai.key
                || ai.key == matcher_prog.key
                || ai.key == matcher_ctx.key
                || ai.key == matcher_delegate.key
                || ai.key == program_id
                || ai.owner == program_id
            {
                return Err(PercolatorError::InvalidInstruction.into());
            }
        }
        Ok(())
    }

    #[inline(never)]
    // TB-1b: grew past the clippy threshold with the 4 new portfolio-identity
    // binding params.
    #[allow(clippy::too_many_arguments)]
    fn handle_trade_cpi<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        account_a_portfolio_id: u64,
        account_a_position_epoch: u64,
        account_b_portfolio_id: u64,
        account_b_position_epoch: u64,
        account_b_matcher_sequence: u64,
        asset_index: u16,
        expected_market_id: u64,
        size_q: i128,
        fee_bps: u64,
        limit_price: u64,
        backing_fee_cap_bps: u16,
    ) -> ProgramResult {
        let signer_a = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let account_a_ai = account(accounts, 2)?;
        let account_b_ai = account(accounts, 3)?;
        let matcher_prog = account(accounts, 4)?;
        let matcher_ctx = account(accounts, 5)?;
        let matcher_delegate = account(accounts, 6)?;

        expect_signer(signer_a)?;
        expect_writable(market_ai)?;
        expect_writable(account_a_ai)?;
        expect_writable(account_b_ai)?;
        expect_writable(matcher_ctx)?;
        expect_owner(market_ai, program_id)?;
        expect_owner(account_a_ai, program_id)?;
        expect_owner(account_b_ai, program_id)?;
        if account_a_ai.key == account_b_ai.key
            || matcher_prog.key == program_id
            || !matcher_prog.executable
            || matcher_ctx.executable
            || matcher_ctx.owner != matcher_prog.key
            || matcher_ctx.data_len() < constants::MATCHER_CONTEXT_MIN_LEN
        {
            return Err(PercolatorError::InvalidInstruction.into());
        }

        let (cfg_pre, mode_pre, current_slot_pre, market_id, oracle_price, max_trading_fee_bps) =
            state::read_market_trade_preflight(
                &market_ai.try_borrow_data()?,
                asset_index as usize,
            )?;
        if !state::asset_generation_binding_matches(market_id, expected_market_id) {
            return Err(PercolatorError::AssetGenerationMismatch.into());
        }
        let (account_a_header, account_a_owner) =
            state::read_portfolio_owner_preflight(&account_a_ai.try_borrow_data()?)?;
        let (account_b_header, account_b_owner) =
            state::read_portfolio_owner_preflight(&account_b_ai.try_borrow_data()?)?;
        if mode_pre != MarketModeV16::Live {
            return Err(PercolatorError::EngineLockActive.into());
        }
        let oracle_profile_pre = read_oracle_profile_for_asset(
            &market_ai.try_borrow_data()?,
            &cfg_pre,
            asset_index as usize,
        )?;
        let stale_matured = global_or_profile_resolve_matured_at_slot(
            &cfg_pre,
            &oracle_profile_pre,
            authenticated_slot_or_fallback(current_slot_pre),
        );
        if stale_matured {
            return Err(PercolatorError::OracleStale.into());
        }
        // The taker signs fee_bps independently of the LP's matcher capability cap.
        if cfg_pre.trade_fee_base_bps > fee_bps {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        let fee_floor_pre = core::cmp::max(fee_bps, cfg_pre.trade_fee_base_bps);
        if fee_floor_pre > max_trading_fee_bps {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        // ADOPT upstream 2d9eb5e9: the signing taker's (account_a) own cap on the
        // backing-domain fee charged to its side of this CPI trade. Independent of account_b
        // (the LP)'s matcher-CPI-derived cap below -- account_a never goes through the
        // matcher, so before this it had no way to bound this fee at all.
        if backing_fee_cap_bps > 10_000 {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        if account_a_header.portfolio_account_id != account_a_ai.key.to_bytes()
            || account_b_header.portfolio_account_id != account_b_ai.key.to_bytes()
        {
            return Err(PercolatorError::EngineProvenanceMismatch.into());
        }
        // TB-1b (ADOPT upstream 0492ebbc): incarnation + position-episode binding,
        // in addition to the account-KEY binding just above. Re-borrows are cheap
        // (both accounts' data was already borrowed transiently for the preflight
        // reads above, and those borrows have already been dropped).
        expect_portfolio_position_binding(
            &account_a_ai.try_borrow_data()?,
            account_a_portfolio_id,
            account_a_position_epoch,
        )?;
        expect_portfolio_position_binding(
            &account_b_ai.try_borrow_data()?,
            account_b_portfolio_id,
            account_b_position_epoch,
        )?;
        // E2: the taker (account_a) — owner==signer OR signer holds the bound NFT.
        // Pre-view path: use the scalar auth core with the preflight (owner, market_group).
        // Optional trailing accounts [7]=nft_registry [8]=PositionNft PDA [9]=signer NFT ATA.
        let nft = optional_nft_holder_accounts(accounts, 7);
        authorize_owner_or_nft_holder_raw(
            &account_a_owner,
            account_a_ai.key,
            &account_a_header.market_group_id,
            signer_a.key,
            nft,
            program_id,
        )?;
        let account_b_owner_key = Pubkey::new_from_array(account_b_owner);
        let (delegate, bump) = derive_matcher_delegate(
            program_id,
            market_ai.key,
            account_b_ai.key,
            &account_b_owner_key,
            matcher_prog.key,
            matcher_ctx.key,
        );
        expect_key(matcher_delegate, &delegate)?;
        let (tail_start, lp_trade_fee_cap_bps) = matcher_tail_start_or_verify_lp_config(
            account_b_ai,
            account_b_matcher_sequence,
            matcher_prog.key,
            matcher_ctx.key,
            matcher_delegate.key,
        )?;
        // FIX (upstream 6b627b43, "require LP consent for CPI base fees"): the taker's own
        // fee_bps consent (checked above) is independent of the LP's matcher capability
        // cap. Without this, a market authority raising trade_fee_base_bps after an LP
        // registered a matcher would route CPI trades through that LP regardless of
        // whether the LP ever agreed to accept a fee that high.
        if cfg_pre.trade_fee_base_bps > u64::from(lp_trade_fee_cap_bps) {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        let tail = accounts
            .get(tail_start..)
            .ok_or(ProgramError::NotEnoughAccountKeys)?;
        validate_matcher_tail(
            tail,
            signer_a,
            market_ai,
            account_a_ai,
            account_b_ai,
            matcher_prog,
            matcher_ctx,
            matcher_delegate,
            program_id,
        )?;
        if size_q == 0 || size_q == i128::MIN {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        if oracle_price == 0 {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        let req_id = state::next_market_matcher_req_id(&market_ai.try_borrow_data()?)?;
        let lp_account_id = matcher_lp_account_id(&delegate);
        let (_, _, max_market_slots_pre, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        ensure_cpi_trade_portfolios_current_before_matcher(
            market_ai,
            account_a_ai,
            account_b_ai,
            max_market_slots_pre,
            &[(asset_index, size_q)],
        )?;

        invoke_matcher(
            matcher_prog,
            matcher_ctx,
            matcher_delegate,
            tail,
            req_id,
            asset_index,
            lp_account_id,
            oracle_price,
            size_q,
            &[
                b"matcher",
                market_ai.key.as_ref(),
                account_b_ai.key.as_ref(),
                account_b_owner_key.as_ref(),
                matcher_prog.key.as_ref(),
                matcher_ctx.key.as_ref(),
                &[bump],
            ],
        )?;

        let ret = {
            let data = matcher_ctx.try_borrow_data()?;
            matcher_abi::read_matcher_return(&data)?
        };
        matcher_abi::validate_matcher_return(
            &ret,
            lp_account_id,
            asset_index,
            oracle_price,
            size_q,
            req_id,
        )?;
        if limit_price != 0 {
            let limit_ok = if size_q > 0 {
                ret.exec_price_e6 <= limit_price
            } else {
                ret.exec_price_e6 >= limit_price
            };
            if !limit_ok {
                return Err(PercolatorError::InvalidInstruction.into());
            }
        }
        if ret.exec_size == 0 {
            state::commit_market_matcher_req_id(&mut market_ai.try_borrow_mut_data()?, req_id)?;
            return Ok(());
        }
        let (_, _, max_market_slots, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        handle_trade_nocpi_zero_copy(
            program_id,
            signer_a.key,
            &account_b_owner_key,
            market_ai,
            account_a_ai,
            account_b_ai,
            account_a_portfolio_id,
            account_a_position_epoch,
            account_b_portfolio_id,
            account_b_position_epoch,
            asset_index,
            expected_market_id,
            ret.exec_size,
            ret.exec_price_e6,
            // ADOPT upstream 42e70c84 (#489, wrapper-only, logic-only): account_b (the
            // unsigned CPI/matcher-routed side) never signs `fee_bps`, and the matcher
            // ABI carries no fee approval from it. Normally that's fine — the taker-only
            // fee design means account_b pays nothing. But the engine's N1 maker-fallback
            // (`charge_trade_fee_taker_only_not_atomic`) shifts the charge onto account_b
            // whenever the taker's own charge resolves to a shortfall (negative-PnL
            // waiver or capital exhaustion) — and that fallback amount was still derived
            // from the taker's own floor-only-bounded `fee_bps`, letting a taker structure
            // a losing/capital-exhausted leg to shift an inflated, self-chosen fee onto
            // the never-signing counterparty. Pin the amount routed into the fee/fallback
            // computation to the market's own `cfg_pre.trade_fee_base_bps` instead — the
            // one fee figure account_b implicitly consents to by registering as an LP.
            cfg_pre.trade_fee_base_bps,
            // ADOPT upstream 2d9eb5e9: account_a's (the signing taker) own declared cap --
            // separate consent from account_b's below, and from the trade-fee floor above.
            Some(backing_fee_cap_bps),
            // ADOPT upstream e24cf78e: the backing-domain fee this trade may charge against
            // the LP's own (account_b) side is a SEPARATE consent from the trade fee above —
            // only the matcher can authorize it, via `backing_fee_cap_bps()` on its CPI return.
            Some(ret.backing_fee_cap_bps()),
            max_market_slots,
        )?;
        state::commit_market_matcher_req_id(&mut market_ai.try_borrow_mut_data()?, req_id)?;
        Ok(())
    }

    #[inline(never)]
    #[allow(clippy::too_many_arguments)]
    fn handle_set_matcher_config<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        portfolio_id: u64,
        expected_sequence: u64,
        asset_generation_frontier: u64,
        enabled: u8,
        trade_fee_cap_bps: u16,
        expiry_slot: u64,
    ) -> ProgramResult {
        // TB-1b (ADOPT upstream 0b838425, "expire matcher capabilities"): replaces
        // the old bespoke `enabled > 1 || ... ` bound check with the shared
        // predicate that also enforces the `expiry_slot` shape (0 when disabling,
        // a live future slot when granting). `authenticated_slot_or_fallback(0)`
        // (never a bare `Clock::get()?`) -- see the matching comment on
        // `matcher_tail_start_or_verify_lp_config` above for why: a native/
        // LiteSVM test harness with no Clock sysvar must not hard-fail every
        // SetMatcherConfig call.
        let current_slot = authenticated_slot_or_fallback(0);
        if !state::matcher_capability_config_is_valid(
            enabled,
            trade_fee_cap_bps,
            expiry_slot,
            current_slot,
        ) {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        let lp_owner = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let lp_portfolio_ai = account(accounts, 2)?;
        expect_signer(lp_owner)?;
        expect_writable(lp_portfolio_ai)?;
        expect_owner(market_ai, program_id)?;
        expect_owner(lp_portfolio_ai, program_id)?;
        let (header, owner) =
            state::read_portfolio_owner_preflight(&lp_portfolio_ai.try_borrow_data()?)?;
        if header.market_group_id != market_ai.key.to_bytes()
            || header.portfolio_account_id != lp_portfolio_ai.key.to_bytes()
            || owner != lp_owner.key.to_bytes()
        {
            return Err(PercolatorError::Unauthorized.into());
        }
        // W3-matcher (ADOPT upstream `8f62a5c5`, "bind matcher grants to asset
        // frontier"): checked LIVE, before any mutation, against
        // `market_ai`'s CURRENT `next_market_id` frontier -- a SetMatcherConfig
        // grant/renewal authorized against a stale asset frontier must not
        // land after the market's asset set has moved on.
        {
            let data = market_ai.try_borrow_data()?;
            let live_frontier = state::read_market_asset_generation_frontier(&data)?;
            if live_frontier != asset_generation_frontier {
                return Err(PercolatorError::EngineStale.into());
            }
        }
        // TB-1b (ADOPT upstream 597f8dcc, "sequence-bind matcher consent
        // mutations"): a SetMatcherConfig granting/revoking matcher trust must
        // supply the account's CURRENT portfolio_id + sequence -- otherwise a
        // stale/replayed authorization (e.g. one built before the LP itself
        // revoked and re-registered a matcher) could re-grant trust the LP no
        // longer intends. Shares the same retained-owner-state sequence lane as
        // Deposit/Withdraw.
        expect_portfolio_sequence_binding(
            &lp_portfolio_ai.try_borrow_data()?,
            portfolio_id,
            expected_sequence,
        )?;
        // ADOPT upstream 2c8c5ba3 (LENGTH half only): consolidate onto the shared
        // `ensure_portfolio_storage_for_market_slots` helper instead of a bespoke
        // grow-only check, so this call site also picks up the oversized-account
        // rejection added there.
        ensure_portfolio_storage_for_market_slots(lp_portfolio_ai, 0)?;
        // TB-1b (ADOPT upstream's current `prior_control` pattern, beyond the 5
        // named SHAs but load-bearing for this unit): the branches below used to
        // rebuild the WHOLE control word from `0`/`default()`, which silently
        // reset `position_epoch` to 0 on every SetMatcherConfig call. That would
        // let a portfolio owner rewind their own position-episode counter and
        // resurrect a stale signed Trade/ForfeitRecoveryLeg/RebalanceReduce/
        // ConvertReleasedPnl/CureAndCancelClose built against the old (lower)
        // episode -- defeating the position_epoch binding this unit wires
        // everywhere else. Carry the account's CURRENT control word forward so
        // only the ENABLED_MASK/TRADE_FEE_CAP_MASK bits `set_enabled`/
        // `set_trade_fee_cap_bps` below actually touch change; POSITION_EPOCH_MASK
        // is untouched (the two mask ranges are disjoint, per the compile-time
        // guard above).
        let prior_control =
            state::read_portfolio_matcher_config(&lp_portfolio_ai.try_borrow_data()?)?.control;
        let mut cfg = if enabled == 0 {
            state::PortfolioMatcherConfigV16 {
                control: prior_control,
                ..state::PortfolioMatcherConfigV16::default()
            }
        } else {
            let matcher_prog = account(accounts, 3)?;
            let matcher_ctx = account(accounts, 4)?;
            let matcher_delegate = account(accounts, 5)?;
            if matcher_prog.key == program_id
                || !matcher_prog.executable
                || matcher_ctx.executable
                || matcher_ctx.owner != matcher_prog.key
                || matcher_ctx.data_len() < constants::MATCHER_CONTEXT_MIN_LEN
            {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            let (delegate, _) = derive_matcher_delegate(
                program_id,
                market_ai.key,
                lp_portfolio_ai.key,
                lp_owner.key,
                matcher_prog.key,
                matcher_ctx.key,
            );
            expect_key(matcher_delegate, &delegate)?;
            state::PortfolioMatcherConfigV16 {
                matcher_program: matcher_prog.key.to_bytes(),
                matcher_context: matcher_ctx.key.to_bytes(),
                matcher_delegate: matcher_delegate.key.to_bytes(),
                control: prior_control,
            }
        };
        cfg.set_enabled(enabled)?;
        cfg.set_trade_fee_cap_bps(trade_fee_cap_bps)?;
        let mut data = lp_portfolio_ai.try_borrow_mut_data()?;
        state::write_portfolio_matcher_config(&mut data, &cfg)?;
        // TB-1b (ADOPT upstream 0b838425): persist the caller's `expiry_slot`
        // grant (already validated live-or-zero above by
        // `matcher_capability_config_is_valid`).
        state::write_portfolio_matcher_expiry(&mut data, expiry_slot)?;
        // TB-1b (ADOPT upstream 597f8dcc): one-shot -- advance the shared
        // sequence so this authorization cannot replay.
        state::advance_portfolio_matcher_sequence(&mut data, expected_sequence)?;
        Ok(())
    }

    /// InitMatcherCtx (tag 83) — bootstrap a matcher context via CPI.
    ///
    /// This is the only path that can call the matcher's tag-2 `process_init` with the
    /// `matcher_delegate` PDA as signer — a PDA cannot sign top-level transactions, so
    /// only an `invoke_signed` from this wrapper can supply the required signature.
    ///
    /// Pre-conditions (checked here):
    ///   - `lp_owner` is a signer
    ///   - `market_ai` is owned by this program
    ///   - `lp_portfolio_ai` is owned by this program and its recorded owner matches `lp_owner`
    ///   - `matcher_ctx` is owned by `matcher_prog` and is writable with len >= MATCHER_CONTEXT_MIN_LEN
    ///   - `matcher_prog` is executable
    ///   - `matcher_delegate` matches the PDA derived from the six seeds
    ///   - The LP portfolio's stored matcher config matches the supplied accounts (via
    ///     `matcher_tail_start_or_verify_lp_config`), ensuring the LP owner cannot
    ///     bootstrap a context for an arbitrary matcher — only the one they previously
    ///     registered via SetMatcherConfig
    ///
    /// After this instruction the matcher program's `process_init` has written the
    /// `MatcherCtx` into `matcher_ctx`, and subsequent `TradeCpi`/`BatchTradeCpi`
    /// calls will succeed.
    ///
    /// Ported verbatim from percolator-prog@6ca7b97b so the wire format, account
    /// list, and behavior byte-match the deployed program (DECISIONS-LEDGER.md
    /// "Pinned deployed revisions").
    ///
    /// Accounts:
    ///   0  lp_owner       [signer]           — owns the LP portfolio
    ///   1  market_ai      [ro]               — wrapper-owned market account
    ///   2  lp_portfolio   [ro]               — LP's portfolio (provenance checked)
    ///   3  matcher_ctx    [writable]         — matcher context account to initialise
    ///   4  matcher_prog   [ro, executable]   — the matcher program
    ///   5  matcher_delegate [ro]             — `["matcher", market, lp_portfolio,
    ///                                          lp_owner, matcher_prog, matcher_ctx]`
    #[allow(clippy::too_many_arguments)]
    #[inline(never)]
    fn handle_init_matcher_ctx<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        kind: u8,
        trading_fee_bps: u32,
        base_spread_bps: u32,
        max_total_bps: u32,
        impact_k_bps: u32,
        liquidity_notional_e6: u128,
        max_fill_abs: u128,
        max_inventory_abs: u128,
        fee_to_insurance_bps: u16,
        skew_spread_mult_bps: u16,
    ) -> ProgramResult {
        if accounts.len() < 6 {
            return Err(ProgramError::NotEnoughAccountKeys);
        }
        let lp_owner = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let lp_portfolio_ai = account(accounts, 2)?;
        let matcher_ctx = account(accounts, 3)?;
        let matcher_prog = account(accounts, 4)?;
        let matcher_delegate = account(accounts, 5)?;

        // Caller must sign.
        expect_signer(lp_owner)?;
        // matcher_ctx must be writable (it will be written by the matcher CPI).
        expect_writable(matcher_ctx)?;
        // Verify wrapper owns the market and LP portfolio accounts.
        expect_owner(market_ai, program_id)?;
        expect_owner(lp_portfolio_ai, program_id)?;

        // Verify LP portfolio is valid and caller owns it.
        let (portfolio_header, portfolio_owner) =
            state::read_portfolio_owner_preflight(&lp_portfolio_ai.try_borrow_data()?)?;
        if portfolio_header.portfolio_account_id != lp_portfolio_ai.key.to_bytes() {
            return Err(PercolatorError::EngineProvenanceMismatch.into());
        }
        if portfolio_header.market_group_id != market_ai.key.to_bytes() {
            return Err(PercolatorError::EngineProvenanceMismatch.into());
        }
        if portfolio_owner != lp_owner.key.to_bytes() {
            return Err(PercolatorError::Unauthorized.into());
        }

        // Validate matcher shape: must be executable, ctx owned by prog, right size.
        if matcher_prog.key == program_id
            || !matcher_prog.executable
            || matcher_ctx.executable
            || matcher_ctx.owner != matcher_prog.key
            || matcher_ctx.data_len() < constants::MATCHER_CONTEXT_MIN_LEN
        {
            return Err(PercolatorError::InvalidInstruction.into());
        }

        // Derive the delegate PDA and verify the caller supplied the right account.
        let lp_owner_key = Pubkey::new_from_array(portfolio_owner);
        let (delegate, bump) = derive_matcher_delegate(
            program_id,
            market_ai.key,
            lp_portfolio_ai.key,
            &lp_owner_key,
            matcher_prog.key,
            matcher_ctx.key,
        );
        expect_key(matcher_delegate, &delegate)?;

        // Verify the LP's stored matcher config matches — this prevents an LP owner
        // from re-initializing with a different (matcher_prog, matcher_ctx) pair than
        // they registered via SetMatcherConfig.
        //
        // W3-matcher: `matcher_tail_start_or_verify_lp_config` now also requires the
        // LIVE matcher sequence (ADOPT upstream `edc8ce74`). InitMatcherCtx is signed
        // live by `lp_owner` in this same transaction (unlike TradeCpi/BatchTradeCpi,
        // which honor a taker's OFF-CHAIN-signed message against an LP grant it does
        // not control), so there is no stale-replay surface here -- read the account's
        // CURRENT sequence immediately before the call and pass it straight through.
        let account_b_matcher_sequence =
            state::read_portfolio_matcher_sequence(&lp_portfolio_ai.try_borrow_data()?)?;
        matcher_tail_start_or_verify_lp_config(
            lp_portfolio_ai,
            account_b_matcher_sequence,
            matcher_prog.key,
            matcher_ctx.key,
            matcher_delegate.key,
        )?;

        // The lp_account_id stored in the matcher context is the first 8 bytes of
        // the delegate PDA — the same value used in every subsequent TradeCpi call.
        let lp_account_id = matcher_lp_account_id(&delegate);

        // Build the 78-byte matcher init payload (tag=2, InitParams layout).
        // Byte layout:
        //   [0]     MATCHER_INIT_VAMM_TAG = 2
        //   [1]     kind
        //   [2..6]  trading_fee_bps (u32 le)
        //   [6..10] base_spread_bps (u32 le)
        //   [10..14] max_total_bps (u32 le)
        //   [14..18] impact_k_bps (u32 le)
        //   [18..34] liquidity_notional_e6 (u128 le)
        //   [34..50] max_fill_abs (u128 le)
        //   [50..66] max_inventory_abs (u128 le)
        //   [66..68] fee_to_insurance_bps (u16 le)
        //   [68..70] skew_spread_mult_bps (u16 le)
        //   [70..78] lp_account_id (u64 le)
        let mut cpi_data = [0u8; 78];
        cpi_data[0] = 2; // MATCHER_INIT_VAMM_TAG
        cpi_data[1] = kind;
        cpi_data[2..6].copy_from_slice(&trading_fee_bps.to_le_bytes());
        cpi_data[6..10].copy_from_slice(&base_spread_bps.to_le_bytes());
        cpi_data[10..14].copy_from_slice(&max_total_bps.to_le_bytes());
        cpi_data[14..18].copy_from_slice(&impact_k_bps.to_le_bytes());
        cpi_data[18..34].copy_from_slice(&liquidity_notional_e6.to_le_bytes());
        cpi_data[34..50].copy_from_slice(&max_fill_abs.to_le_bytes());
        cpi_data[50..66].copy_from_slice(&max_inventory_abs.to_le_bytes());
        cpi_data[66..68].copy_from_slice(&fee_to_insurance_bps.to_le_bytes());
        cpi_data[68..70].copy_from_slice(&skew_spread_mult_bps.to_le_bytes());
        cpi_data[70..78].copy_from_slice(&lp_account_id.to_le_bytes());

        // matcher's process_init accounts: [lp_pda (signer), ctx_account (writable)]
        let metas = [
            AccountMeta::new_readonly(*matcher_delegate.key, true),
            AccountMeta::new(*matcher_ctx.key, false),
        ];
        let ix = SolInstruction {
            program_id: *matcher_prog.key,
            accounts: metas.to_vec(),
            data: cpi_data.to_vec(),
        };

        // Signs the CPI as the delegate PDA using invoke_signed.
        let bump_arr = [bump];
        let seeds: &[&[u8]] = &[
            b"matcher",
            market_ai.key.as_ref(),
            lp_portfolio_ai.key.as_ref(),
            lp_owner_key.as_ref(),
            matcher_prog.key.as_ref(),
            matcher_ctx.key.as_ref(),
            &bump_arr,
        ];
        invoke_signed(
            &ix,
            &[
                matcher_delegate.clone(),
                matcher_ctx.clone(),
                matcher_prog.clone(),
            ],
            &[seeds],
        )
    }

    /// Maximum legs in a single matcher batch CPI: the matcher returns N*64 bytes via
    /// `set_return_data`, bounded by Solana's 1024-byte return-data cap.
    /// Maximum legs in one BatchTradeCpi / BatchTradeNoCpi.
    ///
    /// LOWERED 16 -> 11 for #436 (2026-08-29), on MEASUREMENT rather than estimate. Sweeping the
    /// two axes independently against the deployed program, with the tail held at 1:
    ///
    /// ```text
    /// 2 legs    441,854 CU        10 legs  1,194,739 CU
    /// 4 legs    585,796 CU        11 legs  1,332,184 CU   <- the most that fits
    /// 8 legs    960,738 CU        12 legs  CU EXHAUSTED
    /// ```
    ///
    /// A leg costs ~120,000 CU; a tail account ~840 CU — about 140x apart. So the sibling
    /// `MATCHER_BATCH_TAIL_FANOUT_BUDGET` (legs * tail <= 64) bounds the WRONG QUANTITY: a
    /// product of 12 (12 legs x 1 tail) FAILS while a product of 64 (4 legs x 16 tail) succeeds
    /// comfortably at 596,913 CU. No value of a product budget is simultaneously safe and
    /// useful — lowering it to 11 to catch 12x1 would forbid 4x16, which works.
    ///
    /// 12..=16 could therefore NEVER succeed. Advertising them was a lie that cost callers an
    /// opaque failure: pass the declared check, then die on compute with
    /// ProgramFailedToComplete. Lowering to 11 forbids nothing that works and converts that into
    /// an immediate, attributable InvalidInstruction.
    ///
    /// NECESSARY, NOT SUFFICIENT. Per-leg cost varies with market state, so 11 legs is not
    /// guaranteed to fit in every fixture — it is the ceiling observed in ours. Callers must
    /// still handle CU exhaustion below this bound; this only removes the range that is
    /// impossible everywhere.
    ///
    /// UPSTREAM DIVERGENCE, deliberate: aeyakovenko/percolator-prog still has 16. The product
    /// budget itself came FROM upstream (91129168 "Cap batch CPI matcher tail fanout"), so this
    /// defect exists there too and no upstream branch bounds the leg count. Worth sending back.
    const MATCHER_BATCH_MAX_LEGS: usize = 11;
    // W4 [HIGH]: legs.len()<=16 and tail.len()<=32 are each bounded independently, but their
    // PRODUCT (up to 512) is not -- a batch with many legs AND a full matcher tail multiplies
    // per-leg tail-account validation/CPI-account-resolution work, blowing the CU budget before
    // any single guard fires. Cap the product directly (upstream wrapper 449e7d55, #145).
    const MATCHER_BATCH_TAIL_FANOUT_BUDGET: usize = constants::MAX_MATCHER_TAIL_ACCOUNTS * 2;

    #[allow(clippy::too_many_arguments)]
    fn invoke_matcher_batch<'a>(
        matcher_prog: &AccountInfo<'a>,
        matcher_ctx: &AccountInfo<'a>,
        matcher_delegate: &AccountInfo<'a>,
        tail: &[AccountInfo<'a>],
        req_id: u64,
        lp_account_id: u64,
        // (asset_index, oracle_price_e6, signed req_size) per leg
        legs: &[(u16, u64, i128)],
        seeds: &[&[u8]],
    ) -> ProgramResult {
        let mut data = Vec::with_capacity(18 + legs.len() * 26);
        data.push(3u8);
        data.push(legs.len() as u8);
        data.extend_from_slice(&req_id.to_le_bytes());
        data.extend_from_slice(&lp_account_id.to_le_bytes());
        for (asset_index, oracle_price_e6, req_size) in legs {
            data.extend_from_slice(&asset_index.to_le_bytes());
            data.extend_from_slice(&oracle_price_e6.to_le_bytes());
            data.extend_from_slice(&req_size.to_le_bytes());
        }
        let mut metas = Vec::with_capacity(2 + tail.len());
        metas.push(AccountMeta::new_readonly(*matcher_delegate.key, true));
        metas.push(AccountMeta::new(*matcher_ctx.key, false));
        for ai in tail {
            if ai.is_writable {
                metas.push(AccountMeta::new(*ai.key, ai.is_signer));
            } else {
                metas.push(AccountMeta::new_readonly(*ai.key, ai.is_signer));
            }
        }
        let ix = SolInstruction {
            program_id: *matcher_prog.key,
            accounts: metas,
            data,
        };
        let mut infos = Vec::with_capacity(3 + tail.len());
        infos.push(matcher_delegate.clone());
        infos.push(matcher_ctx.clone());
        infos.push(matcher_prog.clone());
        for ai in tail {
            infos.push(ai.clone());
        }
        invoke_signed(&ix, &infos, &[seeds])
    }

    /// Atomic multi-leg batch routed through one external matcher. A single batched matcher CPI
    /// fills every leg against the LP (account_b), the per-leg returns are validated under the same
    /// anti-spoof binding as the single-fill path, and all fills then apply through the batch
    /// engine path with one end-state margin check.
    #[inline(never)]
    // TB-1b: grew past the clippy threshold with the 4 new portfolio-identity
    // binding params.
    #[allow(clippy::too_many_arguments)]
    fn handle_batch_trade_cpi<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        account_a_portfolio_id: u64,
        account_a_position_epoch: u64,
        account_b_portfolio_id: u64,
        account_b_position_epoch: u64,
        // ADOPT upstream 42ec8ab6, "bound aggregate batch cpi consent": the taker's signed
        // aggregate ceilings across every leg of this batch. TB-1b now also ports upstream's
        // `account_{a,b}_portfolio_id`/`account_{a,b}_position_epoch` identity fields onto
        // this variant (see the `BatchTradeCpi` doc comment).
        max_slippage_atoms: u128,
        max_fee_atoms: u128,
        // W3-matcher (ADOPT upstream `edc8ce74`, "bind cpi trades to matcher
        // incarnation"): see the `BatchTradeCpi` doc comment.
        account_b_matcher_sequence: u64,
        legs: &[ix::BatchTradeCpiLeg],
    ) -> ProgramResult {
        if legs.is_empty() || legs.len() > MATCHER_BATCH_MAX_LEGS {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        let signer_a = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let account_a_ai = account(accounts, 2)?;
        let account_b_ai = account(accounts, 3)?;
        let matcher_prog = account(accounts, 4)?;
        let matcher_ctx = account(accounts, 5)?;
        let matcher_delegate = account(accounts, 6)?;

        expect_signer(signer_a)?;
        expect_writable(market_ai)?;
        expect_writable(account_a_ai)?;
        expect_writable(account_b_ai)?;
        expect_writable(matcher_ctx)?;
        expect_owner(market_ai, program_id)?;
        expect_owner(account_a_ai, program_id)?;
        expect_owner(account_b_ai, program_id)?;
        if account_a_ai.key == account_b_ai.key
            || matcher_prog.key == program_id
            || !matcher_prog.executable
            || matcher_ctx.executable
            || matcher_ctx.owner != matcher_prog.key
            || matcher_ctx.data_len() < constants::MATCHER_CONTEXT_MIN_LEN
        {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        // TB-1b (ADOPT upstream 0492ebbc): fail fast, before any market-state work.
        expect_portfolio_position_binding(
            &account_a_ai.try_borrow_data()?,
            account_a_portfolio_id,
            account_a_position_epoch,
        )?;
        expect_portfolio_position_binding(
            &account_b_ai.try_borrow_data()?,
            account_b_portfolio_id,
            account_b_position_epoch,
        )?;

        // Preflight: market must be Live, the taker owner must sign, and each leg's oracle price
        // is read for matcher request/return binding.
        let mut asset_indices: Vec<u16> = Vec::with_capacity(legs.len());
        for leg in legs {
            if leg.size_q == 0 || leg.size_q == i128::MIN {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            asset_indices.push(leg.asset_index);
        }
        // One header/config parse for mode + slot + every leg's oracle price (avoids O(N^2)
        // re-parsing the market once per leg). W7: also gate the whole batch on base-or-profile
        // permissionless-resolve stale maturity BEFORE the matcher CPI -- same predicate as the
        // single-leg TradeCpi preflight and the shared trade/crank helper, so a stale base oracle
        // freezes non-base legs too and a hostile matcher is never invoked once the market has
        // matured stale (previously this preflight had NO staleness gate at all; staleness was
        // only caught after the CPI returned, inside handle_batch_execute_zero_copy).
        let (mode_pre, oracle_prices, stale_matured, trade_fee_base_bps_pre) = {
            let market_data = market_ai.try_borrow_data()?;
            let (cfg_pre, mode_pre, current_slot_pre, oracle_prices, market_ids) =
                state::read_asset_effective_prices(&market_data, &asset_indices)?;
            if legs
                .iter()
                .zip(market_ids.iter())
                .any(|(leg, market_id)| leg.market_id != *market_id)
            {
                return Err(PercolatorError::AssetGenerationMismatch.into());
            }
            let authenticated_slot = authenticated_slot_or_fallback(current_slot_pre);
            let mut stale_matured = false;
            for &asset_index in &asset_indices {
                let oracle_profile_pre =
                    read_oracle_profile_for_asset(&market_data, &cfg_pre, asset_index as usize)?;
                if global_or_profile_resolve_matured_at_slot(
                    &cfg_pre,
                    &oracle_profile_pre,
                    authenticated_slot,
                ) {
                    stale_matured = true;
                    break;
                }
            }
            (
                mode_pre,
                oracle_prices,
                stale_matured,
                cfg_pre.trade_fee_base_bps,
            )
        };
        if mode_pre != MarketModeV16::Live {
            return Err(PercolatorError::EngineLockActive.into());
        }
        if stale_matured {
            return Err(PercolatorError::OracleStale.into());
        }
        // The taker signs each leg's fee_bps independently of the LP's matcher capability cap
        // (mirrors handle_batch_trade_nocpi's and handle_trade_cpi's guards — adopts
        // upstream 93dd8719/7f319c6b's base-fee-consent reject at this 4th trade entry point).
        if legs.iter().any(|leg| trade_fee_base_bps_pre > leg.fee_bps) {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        let (account_a_header, account_a_owner) =
            state::read_portfolio_owner_preflight(&account_a_ai.try_borrow_data()?)?;
        let (account_b_header, account_b_owner) =
            state::read_portfolio_owner_preflight(&account_b_ai.try_borrow_data()?)?;
        if account_a_header.portfolio_account_id != account_a_ai.key.to_bytes()
            || account_b_header.portfolio_account_id != account_b_ai.key.to_bytes()
        {
            return Err(PercolatorError::EngineProvenanceMismatch.into());
        }
        // E2: the taker (account_a) — owner==signer OR signer holds the bound NFT.
        // Pre-view path: use the scalar auth core with the preflight (owner, market_group).
        // Optional trailing accounts [7]=nft_registry [8]=PositionNft PDA [9]=signer NFT ATA.
        let nft = optional_nft_holder_accounts(accounts, 7);
        authorize_owner_or_nft_holder_raw(
            &account_a_owner,
            account_a_ai.key,
            &account_a_header.market_group_id,
            signer_a.key,
            nft,
            program_id,
        )?;
        let account_b_owner_key = Pubkey::new_from_array(account_b_owner);
        let (delegate, bump) = derive_matcher_delegate(
            program_id,
            market_ai.key,
            account_b_ai.key,
            &account_b_owner_key,
            matcher_prog.key,
            matcher_ctx.key,
        );
        expect_key(matcher_delegate, &delegate)?;
        let (tail_start, lp_trade_fee_cap_bps) = matcher_tail_start_or_verify_lp_config(
            account_b_ai,
            account_b_matcher_sequence,
            matcher_prog.key,
            matcher_ctx.key,
            matcher_delegate.key,
        )?;
        // FIX (upstream 6b627b43, "require LP consent for CPI base fees"): see the mirror
        // check in handle_trade_cpi -- the taker's per-leg fee_bps consent (checked above)
        // is independent of the LP's matcher capability cap.
        if trade_fee_base_bps_pre > u64::from(lp_trade_fee_cap_bps) {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        let tail = accounts
            .get(tail_start..)
            .ok_or(ProgramError::NotEnoughAccountKeys)?;
        validate_matcher_tail(
            tail,
            signer_a,
            market_ai,
            account_a_ai,
            account_b_ai,
            matcher_prog,
            matcher_ctx,
            matcher_delegate,
            program_id,
        )?;
        if legs.len().saturating_mul(tail.len()) > MATCHER_BATCH_TAIL_FANOUT_BUDGET {
            return Err(PercolatorError::InvalidInstruction.into());
        }

        let req_id = state::next_market_matcher_req_id(&market_ai.try_borrow_data()?)?;
        let lp_account_id = matcher_lp_account_id(&delegate);

        // Build the matcher batch request: per leg, (asset, that asset's oracle price, signed size).
        let mut matcher_legs: Vec<(u16, u64, i128)> = Vec::with_capacity(legs.len());
        let mut cpi_requests: Vec<(u16, i128)> = Vec::with_capacity(legs.len());
        for (i, leg) in legs.iter().enumerate() {
            if oracle_prices[i] == 0 {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            matcher_legs.push((leg.asset_index, oracle_prices[i], leg.size_q));
            cpi_requests.push((leg.asset_index, leg.size_q));
        }
        let (_, _, max_market_slots_pre, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        ensure_cpi_trade_portfolios_current_before_matcher(
            market_ai,
            account_a_ai,
            account_b_ai,
            max_market_slots_pre,
            &cpi_requests,
        )?;

        invoke_matcher_batch(
            matcher_prog,
            matcher_ctx,
            matcher_delegate,
            tail,
            req_id,
            lp_account_id,
            &matcher_legs,
            &[
                b"matcher",
                market_ai.key.as_ref(),
                account_b_ai.key.as_ref(),
                account_b_owner_key.as_ref(),
                matcher_prog.key.as_ref(),
                matcher_ctx.key.as_ref(),
                &[bump],
            ],
        )?;

        // Read the N back-to-back returns the matcher emitted via set_return_data.
        let (ret_program, ret_data) = solana_program::program::get_return_data()
            .ok_or(PercolatorError::InvalidInstruction)?;
        if ret_program != *matcher_prog.key
            || ret_data.len() != legs.len() * matcher_abi::MATCHER_RETURN_BYTES
        {
            return Err(PercolatorError::InvalidInstruction.into());
        }

        let mut exec_legs: Vec<ix::BatchTradeLeg> = Vec::with_capacity(legs.len());
        // ADOPT upstream 42ec8ab6: aggregate adverse slippage (quote atoms, summed across every
        // leg's execution away from that leg's authenticated oracle price in the taker's adverse
        // direction) must stay within the taker's signed `max_slippage_atoms` for this whole
        // batch. A favorable leg contributes zero, so it cannot offset another leg's adverse
        // movement -- this bounds worst-case taker slippage exposure to a hostile/collusive
        // matcher return, independent of (and in addition to) the per-leg `limit_price` check
        // below, which only bounds ONE leg's price in isolation.
        let mut aggregate_slippage_atoms: u128 = 0;
        for (i, leg) in legs.iter().enumerate() {
            let chunk = &ret_data[i * matcher_abi::MATCHER_RETURN_BYTES
                ..(i + 1) * matcher_abi::MATCHER_RETURN_BYTES];
            let ret = matcher_abi::read_matcher_return(chunk)?;
            matcher_abi::validate_matcher_return(
                &ret,
                lp_account_id,
                leg.asset_index,
                oracle_prices[i],
                leg.size_q,
                req_id,
            )?;
            // Atomic strategy semantics: every leg must fill (no zero/skip fills in a batch).
            if ret.exec_size == 0 {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            if leg.limit_price != 0 {
                let limit_ok = if leg.size_q > 0 {
                    ret.exec_price_e6 <= leg.limit_price
                } else {
                    ret.exec_price_e6 >= leg.limit_price
                };
                if !limit_ok {
                    return Err(PercolatorError::InvalidInstruction.into());
                }
            }
            let leg_slippage_atoms =
                adverse_trade_slippage_atoms(ret.exec_size, ret.exec_price_e6, oracle_prices[i])?;
            aggregate_slippage_atoms = accumulate_with_cap(
                aggregate_slippage_atoms,
                leg_slippage_atoms,
                max_slippage_atoms,
            )?;
            exec_legs.push(ix::BatchTradeLeg {
                asset_index: leg.asset_index,
                market_id: leg.market_id,
                size_q: ret.exec_size,
                exec_price: ret.exec_price_e6,
                // ADOPT upstream 42e70c84 (wrapper-only, logic-only): as in the single-CPI
                // route above, account_b never signs `leg.fee_bps` and the matcher ABI
                // carries no fee approval from it — pin the amount routed into the N1
                // maker-fallback computation to the market's own base fee instead of the
                // taker's caller-controlled, floor-only-bounded per-leg fee.
                fee_bps: trade_fee_base_bps_pre,
            });
        }

        let (_, _, max_market_slots, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        handle_batch_execute_zero_copy(
            program_id,
            signer_a.key,
            &account_b_owner_key,
            market_ai,
            account_a_ai,
            account_b_ai,
            account_a_portfolio_id,
            account_a_position_epoch,
            account_b_portfolio_id,
            account_b_position_epoch,
            &exec_legs,
            max_market_slots,
            Some(max_fee_atoms),
        )?;
        state::commit_market_matcher_req_id(&mut market_ai.try_borrow_mut_data()?, req_id)?;
        Ok(())
    }

    #[inline(never)]
    fn handle_close_portfolio<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        expected_portfolio_id: u64,
        expected_sequence: u64,
        expected_position_epoch: u64,
    ) -> ProgramResult {
        let closer = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let portfolio_ai = account(accounts, 2)?;
        expect_signer(closer)?;
        expect_writable(closer)?;
        expect_writable(market_ai)?;
        expect_writable(portfolio_ai)?;
        expect_owner(market_ai, program_id)?;
        expect_owner(portfolio_ai, program_id)?;
        let (_, _, max_market_slots, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        ensure_portfolio_storage_for_market_slots(portfolio_ai, max_market_slots)?;
        {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (cfg, mut group) = state::market_view_mut(&mut market_data)?;
            let mut portfolio_data = portfolio_ai.try_borrow_mut_data()?;
            // TB-1b (ADOPT upstream d60f15a1, "bind portfolio close to funded
            // state"): live re-check right before mutation, against ALL THREE
            // identity fields at once. Without this, a ClosePortfolio built while
            // the account was empty could still land -- and deregister the
            // portfolio as an "empty" close -- after a Deposit/trade/cure/forfeit
            // funded or re-opened it in the meantime, since
            // `deregister_empty_materialized_portfolio_not_atomic` only validates
            // the engine's OWN emptiness invariant, not that the caller's mental
            // model of "empty" is still current.
            let current_portfolio_id = state::read_portfolio_id(&portfolio_data)?;
            let current_sequence = state::read_portfolio_matcher_sequence(&portfolio_data)?;
            let current_position_epoch = state::read_portfolio_position_epoch(&portfolio_data)?;
            if !state::portfolio_close_binding_matches(
                current_portfolio_id,
                current_sequence,
                current_position_epoch,
                expected_portfolio_id,
                expected_sequence,
                expected_position_epoch,
            ) {
                return Err(PercolatorError::EngineStale.into());
            }
            let portfolio =
                state::portfolio_view_mut_for_market_slots(&mut portfolio_data, max_market_slots)?;
            expect_portfolio_view_account_key(&portfolio, portfolio_ai.key)?;
            let owner_signed = portfolio.header.owner == closer.key.to_bytes();
            let terminal_marketauth_cleanup =
                group.header.mode == 1 && live_authority_matches(&cfg.marketauth, closer.key);
            if !owner_signed && !terminal_marketauth_cleanup {
                return Err(PercolatorError::Unauthorized.into());
            }
            portfolio
                .validate_with_market(&group.as_view())
                .map_err(map_v16_error)?;
            group
                .deregister_empty_materialized_portfolio_not_atomic(&portfolio.as_view())
                .map_err(map_v16_error)?;
        }
        close_portfolio_account_to_market_slab(portfolio_ai, closer)?;
        Ok(())
    }

    /// F-1: insurance-withdrawal cooldown gate. `last_slot == 0` means "never withdrawn", so the
    /// first withdrawal is always allowed. Returns `InsuranceWithdrawCooldownActive` when a
    /// non-zero cooldown is configured and the window has not yet elapsed. Pure: no I/O.
    #[inline]
    pub fn check_insurance_withdraw_cooldown(
        cooldown_slots: u64,
        last_slot: u64,
        now_slot: u64,
    ) -> Result<(), ProgramError> {
        if cooldown_slots > 0 && last_slot != 0 {
            let earliest = last_slot
                .checked_add(cooldown_slots)
                .ok_or(PercolatorError::EngineArithmeticOverflow)?;
            if now_slot < earliest {
                return Err(PercolatorError::InsuranceWithdrawCooldownActive.into());
            }
        }
        Ok(())
    }

    /// F-2: deposits-only withdrawal ceiling. When `deposits_only != 0`, `amount` may not exceed
    /// `deposit_remaining`; the decremented remaining is returned. When disabled, `deposit_remaining`
    /// is returned unchanged. Returns `InsuranceWithdrawCeilingExceeded` if `amount` exceeds the
    /// remaining deposited principal. Pure: no I/O.
    #[inline]
    pub fn apply_insurance_withdraw_ceiling(
        deposits_only: u8,
        deposit_remaining: u128,
        amount: u128,
    ) -> Result<u128, ProgramError> {
        if deposits_only == 0 {
            return Ok(deposit_remaining);
        }
        if amount > deposit_remaining {
            return Err(PercolatorError::InsuranceWithdrawCeilingExceeded.into());
        }
        deposit_remaining
            .checked_sub(amount)
            .ok_or_else(|| PercolatorError::EngineCounterUnderflow.into())
    }

    #[inline(never)]
    fn handle_top_up_insurance<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        expected_market_id: u64,
        intent_id: u64,
        expected_authority_epoch: u64,
        amount: u128,
    ) -> ProgramResult {
        let signer = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let source_token = account(accounts, 2)?;
        let vault_token = account(accounts, 3)?;
        let token_program = account(accounts, 4)?;
        let ledger_ai = accounts.get(5);
        expect_signer(signer)?;
        expect_writable(market_ai)?;
        expect_writable(source_token)?;
        expect_writable(vault_token)?;
        expect_owner(market_ai, program_id)?;
        if let Some(ledger_ai) = ledger_ai {
            expect_writable(ledger_ai)?;
            expect_owner(ledger_ai, program_id)?;
        }
        verify_token_program(token_program)?;
        let (cfg_pre, mode, asset0_insurance_authority) = {
            let market_data = market_ai.try_borrow_data()?;
            // TB-4: asset-generation binding -- rejects a stale signed
            // instruction captured against an old occupant of asset-0's slot.
            let (cfg_pre, mode, _, market_id, _, _) =
                state::read_market_trade_preflight(&market_data, 0)?;
            if !state::asset_generation_binding_matches(market_id, expected_market_id) {
                return Err(PercolatorError::AssetGenerationMismatch.into());
            }
            // W3A-3: CHECK-only (mirrors upstream `238436c5`'s first
            // `require_authority_epoch_view` call site in
            // `handle_top_up_insurance`, adapted here to the fork's own
            // immutable-borrow pre-check phase via the data-slice-level
            // `state::read_asset_control_sequences` reader instead of the
            // mutable `MarketViewMutV16`-typed `require_authority_epoch_view`
            // helper -- same underlying `AssetControlSequencesV16.
            // authority_epoch` field, same `require_current_authority_epoch`
            // comparison, asset-0 lane (this market-wide top-up always
            // deposits into asset 0, matching upstream's
            // `InsuranceTopUpScope::BaseMarket` -> `scope.asset_index() == 0`).
            let sequences_pre = state::read_asset_control_sequences(&market_data, 0)?;
            state::require_current_authority_epoch(
                sequences_pre.authority_epoch,
                expected_authority_epoch,
            )?;
            let profile0 = read_oracle_profile_for_asset(&market_data, &cfg_pre, 0)?;
            (cfg_pre, mode, profile0.insurance_authority)
        };
        if mode != MarketModeV16::Live {
            return Err(PercolatorError::EngineLockActive.into());
        }
        expect_live_authority(&asset0_insurance_authority, signer.key)?;
        let mint = primary_collateral_mint(&cfg_pre);
        let (vault_authority, _) = derive_vault_authority(program_id, market_ai.key);
        let source_balance = verify_user_token_account(source_token, signer.key, &mint)?;
        verify_vault_token_account(vault_token, &vault_authority, &mint)?;
        let amount_u64 = amount_to_u64(amount)?;
        require_token_balance(source_balance, amount_u64)?;
        let mut cfg_after = None;
        {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (mut cfg, mut group) = state::market_view_mut(&mut market_data)?;
            if group.header.mode != 0 {
                return Err(PercolatorError::EngineLockActive.into());
            }
            // TB-4: re-checked in this second, independently re-borrowed
            // scope, right before mutation -- belt-and-suspenders against a
            // stale first-borrow read.
            require_asset_generation_view(&group, 0, expected_market_id)?;
            // W3A-3: re-checked in this second, independently re-borrowed
            // scope, right before mutation -- mirrors upstream's second
            // `require_authority_epoch_view` call site in the same function
            // (belt-and-suspenders against a stale first-borrow read; the
            // authoritative check for this deposit is THIS one, which
            // strictly precedes `deposit_market_zero_insurance_view` below).
            require_authority_epoch_view(&group, 0, expected_authority_epoch)?;
            reject_permissionless_resolve_matured_live_view(&cfg, &group)?;
            let asset0_insurance_authority =
                domain_authorities_from_view(&group, &cfg, 0)?.insurance_authority;
            expect_live_authority(&asset0_insurance_authority, signer.key)?;
            // sync/w2-tb3 (ADOPT upstream 20f0b9b1, intent_id slice only):
            // one-shot replay-nonce check, shared with TopUpInsuranceDomain
            // via the same asset-0 `insurance_top_up` lane.
            let mut profile0 = read_oracle_profile_from_view(&group, &cfg, 0)?;
            state::require_newer_control_sequence(profile0.insurance_top_up, intent_id)?;
            let mut ledger_data = if let Some(ledger_ai) = ledger_ai {
                Some(ledger_ai.try_borrow_mut_data()?)
            } else {
                None
            };
            let mut ledger_state = if let Some(data) = ledger_data.as_deref() {
                let (mut ledger, initialized) = read_or_new_insurance_ledger(
                    data,
                    market_ai.key.to_bytes(),
                    asset0_insurance_authority,
                    market_insurance_remaining_view(&group, 0)?,
                )?;
                sync_insurance_ledger(&mut ledger, market_insurance_remaining_view(&group, 0)?)?;
                Some((ledger, initialized))
            } else {
                None
            };
            deposit_market_zero_insurance_view(&mut group, amount)?;
            if let Some((ledger, _)) = ledger_state.as_mut() {
                ledger.total_principal_atoms = ledger
                    .total_principal_atoms
                    .checked_add(amount)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                ledger.total_deposited_atoms = ledger
                    .total_deposited_atoms
                    .checked_add(amount)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                ledger.last_observed_insurance_atoms = ledger
                    .last_observed_insurance_atoms
                    .checked_add(amount)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
            }
            if cfg.insurance_withdraw_deposits_only != 0 {
                cfg.insurance_withdraw_deposit_remaining = cfg
                    .insurance_withdraw_deposit_remaining
                    .checked_add(amount)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                cfg_after = Some(cfg);
            }
            profile0.insurance_top_up = intent_id;
            write_oracle_profile_to_view(&mut group, 0, &profile0)?;
            group.validate_shape().map_err(map_v16_error)?;
            if let (Some(data), Some((ledger, initialized))) =
                (ledger_data.as_deref_mut(), ledger_state.as_ref())
            {
                write_or_init_insurance_ledger(data, ledger, *initialized)?;
            }
        }
        transfer_tokens(token_program, source_token, vault_token, signer, amount_u64)?;
        if let Some(cfg) = cfg_after {
            state::write_wrapper_config(&mut market_ai.try_borrow_mut_data()?, &cfg)?;
        }
        Ok(())
    }

    #[inline(never)]
    fn handle_top_up_insurance_domain<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        domain: u16,
        expected_market_id: u64,
        intent_id: u64,
        expected_authority_epoch: u64,
        amount: u128,
    ) -> ProgramResult {
        let signer = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let source_token = account(accounts, 2)?;
        let vault_token = account(accounts, 3)?;
        let token_program = account(accounts, 4)?;
        let ledger_ai = accounts.get(5);
        expect_signer(signer)?;
        expect_writable(market_ai)?;
        expect_writable(source_token)?;
        expect_writable(vault_token)?;
        expect_owner(market_ai, program_id)?;
        if let Some(ledger_ai) = ledger_ai {
            expect_writable(ledger_ai)?;
            expect_owner(ledger_ai, program_id)?;
        }
        verify_token_program(token_program)?;
        let domain = domain as usize;
        let (cfg_pre, authorities) = {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (cfg, group) = state::market_view_mut(&mut market_data)?;
            let configured_slots = group.header.config.max_market_slots.get() as usize;
            let asset_index = domain / 2;
            if group.header.mode != 0
                || domain >= configured_slots.saturating_mul(2)
                || asset_index >= configured_slots
            {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            // TB-4: asset-generation binding for this domain's asset.
            require_asset_generation_view(&group, asset_index, expected_market_id)?;
            // W3A-3: mirrors upstream `238436c5`'s first
            // `require_authority_epoch_view` call site for
            // `InsuranceTopUpScope::Domain`, keyed to the TARGET DOMAIN's own
            // asset epoch (`asset_index == domain / 2`), not asset-0 -- same
            // lane `UpdateAssetAuthority` advances for this asset.
            require_authority_epoch_view(&group, asset_index, expected_authority_epoch)?;
            require_domain_accepts_live_topup_view(&group, domain)?;
            let profile = read_oracle_profile_from_view(&group, &cfg, asset_index)?;
            let authorities = domain_authorities_from_profile(&cfg, &profile, asset_index);
            (cfg, authorities)
        };
        expect_live_authority(&authorities.insurance_authority, signer.key)?;
        let mint = primary_collateral_mint(&cfg_pre);
        let (vault_authority, _) = derive_vault_authority(program_id, market_ai.key);
        let source_balance = verify_user_token_account(source_token, signer.key, &mint)?;
        verify_vault_token_account(vault_token, &vault_authority, &mint)?;
        let amount_u64 = amount_to_u64(amount)?;
        require_token_balance(source_balance, amount_u64)?;
        {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (cfg, mut group) = state::market_view_mut(&mut market_data)?;
            if group.header.mode != 0 {
                return Err(PercolatorError::EngineLockActive.into());
            }
            // TB-4: re-checked in this second, independently re-borrowed scope.
            require_asset_generation_view(&group, domain / 2, expected_market_id)?;
            // W3A-3: re-checked in this second, independently re-borrowed
            // scope, right before mutation -- the authoritative check for
            // THIS deposit, strictly preceding
            // `deposit_domain_insurance_not_atomic` below.
            require_authority_epoch_view(&group, domain / 2, expected_authority_epoch)?;
            reject_permissionless_resolve_matured_live_view(&cfg, &group)?;
            require_domain_accepts_live_topup_view(&group, domain)?;
            let authorities = domain_authorities_from_view(&group, &cfg, domain)?;
            expect_live_authority(&authorities.insurance_authority, signer.key)?;
            // sync/w2-tb3 (ADOPT upstream 20f0b9b1, intent_id slice only):
            // one-shot replay-nonce check on THIS domain's asset's
            // `insurance_top_up` lane -- when `domain / 2 == 0` this is the
            // SAME lane TopUpInsurance(9) advances, so an intent cannot be
            // replayed through the alternate route.
            let asset_index = domain / 2;
            let mut profile = read_oracle_profile_from_view(&group, &cfg, asset_index)?;
            state::require_newer_control_sequence(profile.insurance_top_up, intent_id)?;
            let mut ledger_data = if let Some(ledger_ai) = ledger_ai {
                Some(ledger_ai.try_borrow_mut_data()?)
            } else {
                None
            };
            let mut ledger_state = if let Some(data) = ledger_data.as_deref() {
                let observed = domain_budget_remaining_view(&group, domain)?;
                let (mut ledger, initialized) = read_or_new_insurance_ledger(
                    data,
                    market_ai.key.to_bytes(),
                    authorities.insurance_authority,
                    observed,
                )?;
                sync_insurance_ledger(&mut ledger, observed)?;
                Some((ledger, initialized))
            } else {
                None
            };
            group
                .deposit_domain_insurance_not_atomic(domain, amount)
                .map_err(map_v16_error)?;
            if let Some((ledger, _)) = ledger_state.as_mut() {
                ledger.total_principal_atoms = ledger
                    .total_principal_atoms
                    .checked_add(amount)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                ledger.total_deposited_atoms = ledger
                    .total_deposited_atoms
                    .checked_add(amount)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                ledger.last_observed_insurance_atoms = ledger
                    .last_observed_insurance_atoms
                    .checked_add(amount)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
            }
            profile.insurance_top_up = intent_id;
            write_oracle_profile_to_view(&mut group, asset_index, &profile)?;
            group.validate_shape().map_err(map_v16_error)?;
            if let (Some(data), Some((ledger, initialized))) =
                (ledger_data.as_deref_mut(), ledger_state.as_ref())
            {
                write_or_init_insurance_ledger(data, ledger, *initialized)?;
            }
        }
        transfer_tokens(token_program, source_token, vault_token, signer, amount_u64)?;
        Ok(())
    }

    fn backing_domain_parts_view(
        group: &state::MarketViewMutV16<'_>,
        domain: usize,
    ) -> Result<(SourceCreditStateV16, percolator::BackingBucketV16), ProgramError> {
        let max_markets = group.header.config.max_market_slots.get() as usize;
        let asset_index = domain / 2;
        if domain >= max_markets.saturating_mul(2) || asset_index >= group.markets.len() {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        let slot = &group.markets[asset_index].engine;
        let (source_acc, bucket_acc) = if domain % 2 == 0 {
            (&slot.source_credit_long, &slot.backing_long)
        } else {
            (&slot.source_credit_short, &slot.backing_short)
        };
        Ok((
            source_acc.try_to_runtime().map_err(map_v16_error)?,
            bucket_acc.try_to_runtime().map_err(map_v16_error)?,
        ))
    }

    fn backing_unavailable_principal_atoms(
        bucket: &percolator::BackingBucketV16,
    ) -> Result<u128, ProgramError> {
        bucket
            .consumed_liened_backing_num
            .checked_add(bucket.impaired_liened_backing_num)
            .map(|v| v / BOUND_SCALE)
            .ok_or(PercolatorError::EngineArithmeticOverflow.into())
    }

    /// #433: reconstruct the accounting baseline for a backing domain that
    /// was funded before its canonical BackingDomainLedger existed.
    ///
    /// This is deliberately migration-specific. `read_or_new_backing_domain_ledger`
    /// must keep its zero-principal semantics for other callers (notably LP-vault
    /// accounting, where an uninitialized ledger means that vault has not funded
    /// the domain).
    fn seed_legacy_backing_domain_ledger(
        ledger: &mut state::BackingDomainLedgerAccountV16,
        bucket: &percolator::BackingBucketV16,
    ) -> ProgramResult {
        let gross_principal_num = bucket
            .fresh_unliened_backing_num
            .checked_add(bucket.valid_liened_backing_num)
            .and_then(|v| v.checked_add(bucket.consumed_liened_backing_num))
            .and_then(|v| v.checked_add(bucket.impaired_liened_backing_num))
            .ok_or(PercolatorError::EngineArithmeticOverflow)?;

        let gross_principal_atoms = gross_principal_num / BOUND_SCALE;
        let unavailable_atoms = backing_unavailable_principal_atoms(bucket)?;

        // Seed principal and impairment together. Seeding principal alone would
        // make consumed/impaired backing appear available under:
        //
        // available = principal - (loss - recovery)
        ledger.total_principal_atoms = gross_principal_atoms;

        // Legacy buckets may already have outstanding provider earnings when
        // the canonical ledger is created. Seed that outstanding balance into
        // the migration baseline before pinning the observation watermark;
        // otherwise pre-ledger earnings would never be recognized by sync.
        ledger.total_earnings_atoms = bucket.utilization_fee_earnings;
        ledger.last_observed_bucket_earnings_atoms = bucket.utilization_fee_earnings;

        ledger.cumulative_loss_atoms = unavailable_atoms;
        ledger.cumulative_recovery_atoms = 0;

        // The unavailable amount above is a migration baseline, not a newly
        // observed loss. Pin the watermark to the same snapshot so the first
        // normal sync cannot book it again.
        ledger.last_observed_unavailable_principal_atoms = unavailable_atoms;

        Ok(())
    }

    fn sync_backing_domain_ledger(
        ledger: &mut state::BackingDomainLedgerAccountV16,
        bucket: &percolator::BackingBucketV16,
    ) -> ProgramResult {
        let bucket_earnings_atoms = bucket.utilization_fee_earnings;
        if bucket_earnings_atoms >= ledger.last_observed_bucket_earnings_atoms {
            ledger.total_earnings_atoms = ledger
                .total_earnings_atoms
                .checked_add(bucket_earnings_atoms - ledger.last_observed_bucket_earnings_atoms)
                .ok_or(PercolatorError::EngineArithmeticOverflow)?;
        }
        ledger.last_observed_bucket_earnings_atoms = bucket_earnings_atoms;

        // Deterministic farm rewards are represented as capped counter transfers:
        // the backing bucket's unavailable-principal delta is the realized-loss cap
        // source, and `cumulative_loss_atoms` is the LP-side residual_received
        // counter that a farm snapshots. Recoveries are tracked separately and do
        // not decrement residual_received.
        let unavailable_atoms = backing_unavailable_principal_atoms(bucket)?;
        if unavailable_atoms >= ledger.last_observed_unavailable_principal_atoms {
            ledger.cumulative_loss_atoms = ledger
                .cumulative_loss_atoms
                .checked_add(unavailable_atoms - ledger.last_observed_unavailable_principal_atoms)
                .ok_or(PercolatorError::EngineArithmeticOverflow)?;
        } else {
            ledger.cumulative_recovery_atoms = ledger
                .cumulative_recovery_atoms
                .checked_add(ledger.last_observed_unavailable_principal_atoms - unavailable_atoms)
                .ok_or(PercolatorError::EngineArithmeticOverflow)?;
        }
        ledger.last_observed_unavailable_principal_atoms = unavailable_atoms;
        Ok(())
    }

    fn sync_insurance_ledger(
        ledger: &mut state::InsuranceLedgerAccountV16,
        insurance_atoms: u128,
    ) -> ProgramResult {
        if insurance_atoms >= ledger.last_observed_insurance_atoms {
            ledger.cumulative_profit_atoms = ledger
                .cumulative_profit_atoms
                .checked_add(insurance_atoms - ledger.last_observed_insurance_atoms)
                .ok_or(PercolatorError::EngineArithmeticOverflow)?;
        } else {
            ledger.cumulative_loss_atoms = ledger
                .cumulative_loss_atoms
                .checked_add(ledger.last_observed_insurance_atoms - insurance_atoms)
                .ok_or(PercolatorError::EngineArithmeticOverflow)?;
        }
        ledger.last_observed_insurance_atoms = insurance_atoms;
        Ok(())
    }

    /// The sibling domain of `domain` within the SAME asset: domain = asset*2 + side,
    /// so flipping the low bit flips the side and keeps the asset. The LP vault is
    /// authorised over both (the `backing_bucket_authority` it holds is per-ASSET).
    fn sibling_domain(domain: u16) -> u16 {
        domain ^ 1
    }

    /// One domain's contribution to LP-vault NAV, synced to its bucket first.
    /// An uninitialised ledger account contributes 0 — `read_or_new_backing_domain_ledger`
    /// returns a zeroed ledger whose watermarks match the bucket, so a domain the
    /// vault has never funded adds nothing rather than failing.
    fn lp_vault_domain_nav_atoms(
        group: &state::MarketViewMutV16<'_>,
        market_group: [u8; 32],
        authority: [u8; 32],
        domain: u16,
        fee_share_bps: u16,
        ledger_data: &[u8],
    ) -> Result<u128, ProgramError> {
        let (_, bucket) = backing_domain_parts_view(group, domain as usize)?;
        let (mut ledger, _) = read_or_new_backing_domain_ledger(
            ledger_data,
            market_group,
            authority,
            domain,
            &bucket,
        )?;
        sync_backing_domain_ledger(&mut ledger, &bucket)?;
        percolator::lp_vault::lp_vault_nav_atoms(
            ledger.total_principal_atoms,
            ledger.total_earnings_atoms,
            ledger.total_earnings_withdrawn_atoms,
            ledger.cumulative_loss_atoms,
            ledger.cumulative_recovery_atoms,
            fee_share_bps,
        )
        .map_err(map_v16_error)
    }

    /// One domain's AVAILABLE principal (principal net of impairment). Mirrors
    /// `lp_vault_nav_atoms`'s internals exactly, minus the earnings term.
    fn lp_vault_domain_available_principal_atoms(
        group: &state::MarketViewMutV16<'_>,
        market_group: [u8; 32],
        authority: [u8; 32],
        domain: u16,
        ledger_data: &[u8],
    ) -> Result<u128, ProgramError> {
        let (_, bucket) = backing_domain_parts_view(group, domain as usize)?;
        let (mut ledger, _) = read_or_new_backing_domain_ledger(
            ledger_data,
            market_group,
            authority,
            domain,
            &bucket,
        )?;
        sync_backing_domain_ledger(&mut ledger, &bucket)?;
        let net_impairment = ledger
            .cumulative_loss_atoms
            .checked_sub(ledger.cumulative_recovery_atoms)
            .ok_or(PercolatorError::EngineCounterUnderflow)?;
        ledger
            .total_principal_atoms
            .checked_sub(net_impairment)
            .ok_or_else(|| PercolatorError::EngineCounterUnderflow.into())
    }

    /// AVAILABLE principal across BOTH domains. Must be summed alongside NAV: the
    /// redemption split is `principal_out = shares * available_principal / total_shares`
    /// and `earnings_out = atoms_out - principal_out`. Pairing a COMBINED nav with a
    /// SINGLE-pot available_principal inflates `earnings_out` by the sibling pot's
    /// principal, which then fails the earnings-availability gate and bricks the
    /// redemption. Both terms have to span the same set of pots.
    fn lp_vault_combined_available_principal_atoms(
        group: &state::MarketViewMutV16<'_>,
        market_group: [u8; 32],
        authority: [u8; 32],
        domain: u16,
        own_ledger_data: &[u8],
        sibling_ledger_data: &[u8],
    ) -> Result<u128, ProgramError> {
        let own = lp_vault_domain_available_principal_atoms(
            group,
            market_group,
            authority,
            domain,
            own_ledger_data,
        )?;
        let sib = lp_vault_domain_available_principal_atoms(
            group,
            market_group,
            authority,
            sibling_domain(domain),
            sibling_ledger_data,
        )?;
        own.checked_add(sib)
            .ok_or_else(|| PercolatorError::EngineArithmeticOverflow.into())
    }

    /// LP-vault NAV across BOTH domains of its asset.
    ///
    /// The vault's backing can sit in either pot (see RebalanceLpVaultBacking,
    /// tag 91), so pricing shares off `registry.domain` alone understates NAV by
    /// whatever sits in the sibling and mints incoming depositors free shares at
    /// existing holders' expense. Summing the two `lp_vault_nav_atoms` calls
    /// separately loses at most 1 atom to the `lp_earnings` floor versus summing
    /// the inputs first — that atom stays in the vault, which is the safe side.
    /// Atoms the LP-vault fee crank could harvest into NAV *right now* (#411).
    ///
    /// This is the SINGLE definition of that quantity. `handle_lp_vault_crank_fees` and
    /// `handle_deposit_to_lp_vault` both call it, deliberately: the deposit must be priced
    /// against exactly what a crank in the same slot would realize, and if the two ever
    /// computed it separately they would drift and reopen this bug.
    ///
    /// It is NOT `lp_fee_accrued - lp_fee_withdrawn`. That is the CLAIM, and three legs
    /// (protocol / LP / stake) share one surplus pool with no cross-leg accounting, so the
    /// claim is only realizable down to whatever the engine and the vault can actually
    /// cover. Pricing against the unclamped claim would overstate NAV whenever the surplus
    /// is dry — trading one mispricing for another, in the opposite direction.
    fn lp_vault_harvestable_fee_atoms(
        cfg: &state::WrapperConfigV16,
        group: &state::MarketViewMutV16<'_>,
    ) -> Result<u128, ProgramError> {
        let claim_capacity = cfg
            .lp_fee_accrued_atoms
            .checked_sub(cfg.lp_fee_withdrawn_atoms)
            .ok_or(PercolatorError::EngineCounterUnderflow)?;
        let engine_available = group
            .header
            .insurance
            .get()
            .saturating_sub(
                group
                    .header
                    .source_insurance_credit_reserved_total_atoms
                    .get(),
            )
            .saturating_sub(group.header.insurance_domain_budget_remaining_total.get());
        Ok(claim_capacity
            .min(engine_available)
            .min(group.header.vault.get()))
    }

    fn lp_vault_combined_nav_atoms(
        group: &state::MarketViewMutV16<'_>,
        market_group: [u8; 32],
        authority: [u8; 32],
        domain: u16,
        fee_share_bps: u16,
        own_ledger_data: &[u8],
        sibling_ledger_data: &[u8],
    ) -> Result<u128, ProgramError> {
        let own = lp_vault_domain_nav_atoms(
            group,
            market_group,
            authority,
            domain,
            fee_share_bps,
            own_ledger_data,
        )?;
        let sib = lp_vault_domain_nav_atoms(
            group,
            market_group,
            authority,
            sibling_domain(domain),
            fee_share_bps,
            sibling_ledger_data,
        )?;
        own.checked_add(sib)
            .ok_or_else(|| PercolatorError::EngineArithmeticOverflow.into())
    }

    /// W-GEN-L: a zeroed ledger record for `(market_group, authority, domain)`
    /// stamped with the CURRENT asset generation, its observation watermarks pinned
    /// to `bucket` so the `sync_backing_domain_ledger` that every caller runs next
    /// is a no-op rather than a phantom loss or a phantom earning.
    ///
    /// Shared by all three seed paths (fresh account, GH#453 SPENT-authority
    /// adoption, W-GEN-L generation re-seed) so they cannot drift apart.
    fn new_backing_domain_ledger(
        market_group: [u8; 32],
        authority: [u8; 32],
        domain: u16,
        bucket: &percolator::BackingBucketV16,
    ) -> Result<state::BackingDomainLedgerAccountV16, ProgramError> {
        Ok(state::BackingDomainLedgerAccountV16 {
            market_group,
            authority,
            total_principal_atoms: 0,
            total_deposited_atoms: 0,
            total_principal_withdrawn_atoms: 0,
            total_earnings_atoms: 0,
            total_earnings_withdrawn_atoms: 0,
            last_observed_bucket_earnings_atoms: bucket.utilization_fee_earnings,
            cumulative_loss_atoms: 0,
            cumulative_recovery_atoms: 0,
            last_observed_unavailable_principal_atoms: backing_unavailable_principal_atoms(bucket)?,
            domain,
            _padding: [0u8; 6],
            // The bucket IS the generation: the engine keeps
            // `backing_{long,short}.market_id == asset.market_id` and refuses any
            // slot where it does not (`EngineAssetSlotV16Account::
            // validate_market_id_binding` -> `InvalidConfig`), re-checking it on the
            // retired slot before a new id is assigned. Every call site reads
            // `bucket` from `backing_domain_parts_view(&group, domain)` for this same
            // domain, so no caller can present a bucket from elsewhere.
            market_id: bucket.market_id,
        })
    }

    fn read_or_new_backing_domain_ledger(
        data: &[u8],
        market_group: [u8; 32],
        authority: [u8; 32],
        domain: u16,
        bucket: &percolator::BackingBucketV16,
    ) -> Result<(state::BackingDomainLedgerAccountV16, bool), ProgramError> {
        // Fork adaptation of upstream caf1cc2a: `data.len() == 0` is the
        // documented sentinel for the LP vault's SIBLING-domain ledger,
        // which may never have been created (see the `sibling_ledger_ai`
        // doc comment in `handle_deposit_to_lp_vault` and the doc comment
        // on `lp_vault_domain_nav_atoms` — "an uninitialised ledger account
        // contributes 0"). That is a genuinely absent account, not a
        // malformed one, so it is exempted from the exact-length gate below
        // and falls through to the all-zero fresh-ledger branch. Any account
        // that DOES have storage (`data.len() != 0`) must still match the
        // canonical wire length exactly — upstream's hardening.
        if !data.is_empty() && data.len() != state::backing_domain_ledger_account_len() {
            return Err(PercolatorError::InvalidAccountLen.into());
        }
        if state::is_initialized(data) {
            let ledger = state::read_backing_domain_ledger(data)?;
            if ledger.market_group != market_group || ledger.domain != domain {
                return Err(PercolatorError::Unauthorized.into());
            }
            // ── W-GEN-L: the asset GENERATION gate, checked BEFORE the authority
            // gate below. ───────────────────────────────────────────────────────
            //
            // The account is a PDA of `(market_group, domain)` only, so it survives
            // a retire + re-activate of the asset slot — and tag 40's
            // `permissionless_reuse_target` lets ANY caller who pays
            // `permissionless_market_init_fee` perform that re-activation. The
            // engine then stamps a fresh `market_id` and hands the domain a bucket
            // that is `empty_for_market(new_id)`. This ledger's counters, however,
            // describe the PREVIOUS market: W-GEN PoC attempt 2b measures 700 atoms
            // deposited under generation M1 and 300 under M2 reported as a single
            // `total_deposited_atoms = 1_000`, and the same record carries
            // `cumulative_loss_atoms` (== `residual_received_atoms()`, the
            // deterministic LP-farm reward counter) and
            // `last_observed_unavailable_principal_atoms`, so an unrelated market's
            // impairment history prices the new market's rewards and NAV.
            //
            // A stale generation is therefore treated as ABSENT and re-seeded,
            // exactly as a SPENT authority is below. This destroys no payable claim:
            // the engine will not mint a new generation until the bucket is provably
            // value-free — `activate_empty_market_slot_not_atomic` requires
            // `backing_{long,short}.is_empty_amount_shape()`, which demands zero
            // fresh/valid/consumed/impaired backing AND zero
            // `utilization_fee_earnings` AND `status == Empty`; the restart path
            // (`restart_empty_asset_preserving_insurance_budget_not_atomic`) rebuilds
            // the whole slot from `empty_for_market(market_id)`. Whatever the old
            // ledger still claimed on paper was already unpayable from the new
            // bucket the moment the generation changed; keeping the number only
            // mis-prices the new market.
            //
            // Not caller-steerable: `domain` comes from the instruction but is
            // range-checked and pinned into the PDA, and the generation compared
            // against is read from engine state for that same domain, never from the
            // payload.
            //
            // `market_id == 0` is the LEGACY case, not a generation — see the
            // `stamp` branch below.
            if ledger.market_id != 0 && ledger.market_id != bucket.market_id {
                return Ok((
                    new_backing_domain_ledger(market_group, authority, domain, bucket)?,
                    true,
                ));
            }
            if ledger.authority != authority {
                // GH#453. A domain ledger outlives the authority that opened it.
                // Post-#433 `TopUpBackingBucket` creates one stamped with the
                // market-maker's `backing_bucket_authority`, and
                // `WithdrawBackingBucket` never closes it — so after a full
                // withdrawal the PDA persists with zero principal and a stale
                // authority. `CreateLpVault` then rotates the domain to the
                // registry PDA, its born-dead guard having looked only at the
                // BUCKET, and every subsequent `DepositToLpVault` died here with
                // `Unauthorized`, permanently. The only exit was `CloseLpVault`,
                // which forfeits the market's LP-vault capability for good.
                //
                // A SPENT ledger is adopted rather than refused. "Spent" is not a
                // judgement call — it means the account holds no value and owes
                // nobody anything:
                //
                //   * no principal, and none of it merely withdrawn-on-paper: the
                //     BUCKET is checked too, so the engine agrees it is empty;
                //   * no unclaimed earnings.
                //
                // Adoption RE-SEEDS rather than re-keys. Inheriting the previous
                // provider's `cumulative_loss_atoms` would import their impairment
                // history into the new authority's NAV, which is a mispricing, not
                // a permission question.
                //
                // This cannot be steered by a caller: `authority` is always read
                // from the asset profile (`domain_authorities_from_profile`), never
                // taken from the instruction, so no one can present themselves as
                // the adopter. And a ledger with ANY value left still refuses —
                // rotating a funded ledger away from its provider would strand
                // their claim, which is the thing the check exists to prevent.
                let has_principal = ledger.total_principal_atoms != 0;
                let has_unclaimed_earnings =
                    ledger.total_earnings_atoms > ledger.total_earnings_withdrawn_atoms;
                let bucket_holds_backing = bucket.fresh_unliened_backing_num != 0
                    || bucket.valid_liened_backing_num != 0
                    || bucket.consumed_liened_backing_num != 0
                    || bucket.impaired_liened_backing_num != 0;
                if has_principal || has_unclaimed_earnings || bucket_holds_backing {
                    return Err(PercolatorError::Unauthorized.into());
                }
                let adopted = new_backing_domain_ledger(market_group, authority, domain, bucket)?;
                return Ok((adopted, true));
            }
            // W-GEN-L legacy: a ledger written by a build before this change has all
            // 14 old padding bytes zero (`validate_backing_domain_ledger` refused any
            // non-zero padding), so it reads back as `market_id == 0`. That is not a
            // generation — the engine's `next_market_id` starts at 1 and an asset with
            // `market_id == 0` is refused — so it means "unstamped".
            //
            // Such a record is STAMPED, not re-seeded: its counters are kept and the
            // current generation is written in. The alternative (treat 0 as stale and
            // zero the record) would, on the flag day, wipe the `total_principal_atoms`
            // / `total_earnings_atoms` / `cumulative_loss_atoms` of every LIVE market's
            // provider and LP vault the first time anyone touched them — destroying
            // real claims to close a gap that only opens on a generation FLIP. Keeping
            // the counters loses nothing: the one flip that could straddle the upgrade
            // is the flip that happened before it, and no stamp could have caught that
            // one either. Every flip after this write is caught.
            //
            // Post-W-19 this branch is unreachable in production anyway: W-19 bumped
            // the account header `VERSION` 17 -> 18, and `read_backing_domain_ledger`
            // -> `check_header` refuses any account carrying the old version with
            // `InvalidVersion` BEFORE this function sees it, which is exactly the F-01
            // full re-seed. It is kept as the fail-safe for any path that reaches a
            // version-18 record with an unstamped tail (a ledger created by this build
            // is always stamped).
            if ledger.market_id == 0 {
                let mut stamped = ledger;
                stamped.market_id = bucket.market_id;
                return Ok((stamped, true));
            }
            Ok((ledger, true))
        } else if data.iter().any(|byte| *byte != 0) {
            Err(ProgramError::InvalidAccountData)
        } else {
            Ok((
                new_backing_domain_ledger(market_group, authority, domain, bucket)?,
                false,
            ))
        }
    }

    fn write_or_init_backing_domain_ledger(
        data: &mut [u8],
        ledger: &state::BackingDomainLedgerAccountV16,
        initialized: bool,
    ) -> ProgramResult {
        if initialized {
            state::write_backing_domain_ledger(data, ledger)
        } else {
            state::init_backing_domain_ledger(data, ledger)
        }
    }

    fn read_or_new_insurance_ledger(
        data: &[u8],
        market_group: [u8; 32],
        authority: [u8; 32],
        insurance_atoms: u128,
    ) -> Result<(state::InsuranceLedgerAccountV16, bool), ProgramError> {
        if data.len() != state::insurance_ledger_account_len() {
            return Err(PercolatorError::InvalidAccountLen.into());
        }
        if state::is_initialized(data) {
            let ledger = state::read_insurance_ledger(data)?;
            if ledger.market_group != market_group || ledger.authority != authority {
                return Err(PercolatorError::Unauthorized.into());
            }
            Ok((ledger, true))
        } else if data.iter().any(|byte| *byte != 0) {
            Err(ProgramError::InvalidAccountData)
        } else {
            Ok((
                state::InsuranceLedgerAccountV16 {
                    market_group,
                    authority,
                    total_principal_atoms: 0,
                    total_deposited_atoms: 0,
                    total_withdrawn_atoms: 0,
                    cumulative_profit_atoms: 0,
                    cumulative_loss_atoms: 0,
                    last_observed_insurance_atoms: insurance_atoms,
                },
                false,
            ))
        }
    }

    fn write_or_init_insurance_ledger(
        data: &mut [u8],
        ledger: &state::InsuranceLedgerAccountV16,
        initialized: bool,
    ) -> ProgramResult {
        if initialized {
            state::write_insurance_ledger(data, ledger)
        } else {
            state::init_insurance_ledger(data, ledger)
        }
    }

    const DOMAIN_WITHDRAW_AUTH_INSURANCE: u8 = 0;
    const DOMAIN_WITHDRAW_AUTH_BACKING: u8 = 1;

    #[inline(never)]
    fn verify_domain_withdrawal_preflight<'a>(
        program_id: &Pubkey,
        market_ai: &AccountInfo<'a>,
        authority: &AccountInfo<'a>,
        dest_token: &AccountInfo<'a>,
        vault_token: &AccountInfo<'a>,
        vault_authority_ai: &AccountInfo<'a>,
        domain: usize,
        amount: u128,
        expected_market_id: u64,
        require_live_mode: bool,
        authority_kind: u8,
    ) -> Result<(u8, u64), ProgramError> {
        let market_data = market_ai.try_borrow_data()?;
        let (cfg, mode, configured_slots, _) =
            state::read_market_config_mode_and_capacity(&market_data)?;
        // W4-PAYOUT (upstream 82f44d11 "permit beneficiary-bound public terminal reserve
        // payouts"): once a market is Resolved, reserve payouts on this preflight are
        // permissionless -- no signature is required from `authority` (any cranker may
        // submit). Live reserve management still requires consent from the authorized
        // party, exactly as before.
        if mode != MarketModeV16::Resolved {
            expect_signer(authority)?;
        }
        let asset_index = domain / 2;
        if (require_live_mode && mode != MarketModeV16::Live)
            || domain >= configured_slots.saturating_mul(2)
            || asset_index >= configured_slots
        {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        let (_, _, _, current_market_id, _, _) =
            state::read_market_trade_preflight(&market_data, asset_index)?;
        if !state::asset_generation_binding_matches(current_market_id, expected_market_id) {
            return Err(PercolatorError::AssetGenerationMismatch.into());
        }
        let profile = read_oracle_profile_for_asset(&market_data, &cfg, asset_index)?;
        let authorities = domain_authorities_from_profile(&cfg, &profile, asset_index);
        // W4-PAYOUT (upstream c162d7c7 "preserve shutdown reserve beneficiaries"): the
        // payout is bound to the domain's RECORDED beneficiary (insurance_operator /
        // backing_bucket_authority), read from state -- never to whatever pubkey the
        // caller names in the `authority` account. `authority.key` is still checked
        // against {beneficiary, marketauth} below for AUTHORIZATION (who may submit /
        // who a Live-mode signature must come from), but it never determines WHERE the
        // funds land. This is what makes the marketauth shutdown-drain fallback safe to
        // make permissionless: a permissionless submitter can name marketauth as the
        // non-signing `authority` reference to unlock the payout, but cannot redirect
        // the destination to marketauth (or itself) -- only to the bound beneficiary.
        let beneficiary = match authority_kind {
            DOMAIN_WITHDRAW_AUTH_INSURANCE => authorities.insurance_operator,
            DOMAIN_WITHDRAW_AUTH_BACKING => authorities.backing_bucket_authority,
            _ => return Err(PercolatorError::InvalidInstruction.into()),
        };
        let local_authorized = live_authority_matches(&beneficiary, authority.key);
        if !local_authorized && !live_authority_matches(&cfg.marketauth, authority.key) {
            return Err(PercolatorError::Unauthorized.into());
        }
        let (vault_authority, bump) = derive_vault_authority(program_id, market_ai.key);
        expect_key(vault_authority_ai, &vault_authority)?;
        // Fork hardening (W5 / upstream b7b6688e / #154): a payout that can complete
        // without a signature from its recipient must reject a dest_token the recipient
        // left an active delegate/close_authority on -- otherwise a pre-existing (e.g.
        // phished) delegate sweeps the funds the instant they land, with no fresh
        // consent from the beneficiary at payout time. This domain-withdrawal preflight
        // was signer-gated on every path until this unit; now that Resolved mode can run
        // it without `authority`'s signature, it needs the same dest_token poisoning
        // check the other permissionless payout paths already carry.
        // sync(W4-TOKEN22): folded into `require_unencumbered_dest` on the widened
        // `verify_withdrawable_token_accounts` instead of a second standalone call.
        let vault_balance = verify_withdrawable_token_accounts(
            dest_token,
            &Pubkey::new_from_array(beneficiary),
            vault_token,
            &vault_authority,
            &cfg,
            !authority.is_signer,
        )?;
        let amount_u64 = amount_to_u64(amount)?;
        require_token_balance(vault_balance, amount_u64)?;
        Ok((bump, amount_u64))
    }

    #[inline(never)]
    fn handle_top_up_backing_bucket<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        domain: u16,
        expected_market_id: u64,
        intent_id: u64,
        expected_authority_epoch: u64,
        amount: u128,
        expiry_slot: u64,
    ) -> ProgramResult {
        let signer = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let source_token = account(accounts, 2)?;
        let vault_token = account(accounts, 3)?;
        let token_program = account(accounts, 4)?;
        // #433 route (b): the ledger is MANDATORY here, and this handler CREATES it when it
        // does not exist. Creation is the half the first fix was missing.
        //
        // Requiring the ledger on WITHDRAWAL alone (45bba89e) stranded funds: nothing
        // allocated the PDA, so it had to already exist, and only the LP-vault handlers ever
        // made one. Requiring it on the way IN, with creation, guarantees one exists by the
        // time anyone withdraws — which is what makes the withdrawal-side requirement safe
        // instead of a trap.
        //
        // Deliberately the DEPOSIT side. A caller who cannot form this instruction simply
        // does not deposit; the same mistake on the withdrawal side locks money already in.
        // Breaking deposits is recoverable, breaking withdrawals is not.
        let ledger_ai = account(accounts, 5)?;
        let system_program_ai = account(accounts, 6)?;
        expect_signer(signer)?;
        expect_writable(market_ai)?;
        expect_writable(source_token)?;
        expect_writable(vault_token)?;
        expect_owner(market_ai, program_id)?;
        expect_writable(ledger_ai)?;
        let (ledger_pda, ledger_bump) =
            state::derive_lp_backing_ledger(program_id, market_ai.key, domain);
        expect_key(ledger_ai, &ledger_pda)?;
        if ledger_ai.data_is_empty() {
            let domain_bytes = domain.to_le_bytes();
            let bump_bytes = [ledger_bump];
            let seeds: &[&[u8]] = &[
                crate::constants::LP_BACKING_LEDGER_SEED,
                market_ai.key.as_ref(),
                domain_bytes.as_ref(),
                bump_bytes.as_ref(),
            ];
            create_pda_account(
                signer,
                ledger_ai,
                system_program_ai,
                state::backing_domain_ledger_account_len(),
                program_id,
                seeds,
            )?;
        }
        expect_owner(ledger_ai, program_id)?;
        verify_token_program(token_program)?;
        let domain_usize = domain as usize;
        let (cfg_pre, authorities) = {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (cfg, group) = state::market_view_mut(&mut market_data)?;
            let configured_slots = group.header.config.max_market_slots.get() as usize;
            let asset_index = domain_usize / 2;
            if domain_usize >= configured_slots.saturating_mul(2) || asset_index >= configured_slots
            {
                return Err(PercolatorError::EngineLockActive.into());
            }
            // TB-4: asset-generation binding for this domain's asset.
            require_asset_generation_view(&group, asset_index, expected_market_id)?;
            // W3A-3: `authority_epoch` (upstream `238436c5`) -- mirrors its
            // first `require_authority_epoch_view` call site in
            // `handle_top_up_backing_bucket`, checked (NOT advanced) BEFORE
            // the mode-specific dispatch below, against the TARGET DOMAIN's
            // own asset epoch (`domain_usize / 2`). Applies unconditionally
            // to both the Live (mode 0) and #433-migration Resolved-only
            // (mode 1, amount == 0) reconciliation paths this fork supports.
            require_authority_epoch_view(&group, asset_index, expected_authority_epoch)?;

            match group.header.mode {
                // Normal backing deposits remain strictly Live-only.
                0 => {
                    // sync/w1-abacking (adopt upstream 5314c05f, "authenticate backing top-up
                    // expiry"): a provider-signed `expiry_slot` that is already <= now would
                    // create a bucket the very next crank can advance straight to Expired --
                    // funding a "fresh" backing bucket that never backs a single lien for its
                    // provider, while callers relying on `require_domain_accepts_live_topup_view`
                    // above still treat the deposit as accepted.
                    // Wave-1 S1a v2 griefing fix (Gate-2 rejection): the LP-vault sentinel
                    // `LP_VAULT_BACKING_EXPIRY_SLOT` (`u64::MAX / 2`) marks a bucket as
                    // "LP-vault-bound" and permanently blocks `CloseSlab`'s terminal-slab
                    // scan (see the OPTION-(B) SCOPE GATE comment there). That sentinel is
                    // reserved for the LP-vault-registry call sites
                    // (`handle_deposit_to_lp_vault` / rebalance / fee-crank-reclassify),
                    // which stamp it directly via `add_fresh_counterparty_backing_view` with
                    // a hardcoded constant -- never through this handler. Without this
                    // guard, `expiry_slot` here is a RAW caller-supplied argument (only
                    // lower-bounded above), so a domain's `backing_bucket_authority` could
                    // set it to exactly the sentinel on an ordinary top-up and permanently
                    // brick `CloseSlab` (Custom(21)) for a market that never touched the
                    // LP-vault feature at all.
                    if amount != 0
                        && (expiry_slot <= authenticated_market_slot_or_fallback_view(&group)
                            || expiry_slot == crate::constants::LP_VAULT_BACKING_EXPIRY_SLOT)
                    {
                        return Err(PercolatorError::InvalidInstruction.into());
                    }
                    require_domain_accepts_live_topup_view(&group, domain_usize)?;
                }

                // #433 migration-only exception: a fully wound-down Resolved
                // market may still contain backing funded before canonical
                // BackingDomainLedger creation became mandatory.
                //
                // amount == 0 performs accounting reconciliation only. It must
                // not reopen backing deposits or mutate engine backing.
                1 if amount == 0 => {
                    if group.header.materialized_portfolio_count.get() != 0
                        || group.header.c_tot.get() != 0
                    {
                        return Err(PercolatorError::EngineLockActive.into());
                    }
                }

                // Non-zero top-ups remain forbidden after resolution.
                _ => return Err(PercolatorError::EngineLockActive.into()),
            }
            let profile = read_oracle_profile_from_view(&group, &cfg, asset_index)?;
            let authorities = domain_authorities_from_profile(&cfg, &profile, asset_index);
            (cfg, authorities)
        };
        expect_live_authority(&authorities.backing_bucket_authority, signer.key)?;
        let mint = primary_collateral_mint(&cfg_pre);
        let (vault_authority, _) = derive_vault_authority(program_id, market_ai.key);
        let source_balance = verify_user_token_account(source_token, signer.key, &mint)?;
        verify_vault_token_account(vault_token, &vault_authority, &mint)?;
        let amount_u64 = amount_to_u64(amount)?;
        require_token_balance(source_balance, amount_u64)?;
        if amount != 0 {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (cfg, mut group) = state::market_view_mut(&mut market_data)?;
            if group.header.mode != 0 {
                return Err(PercolatorError::EngineLockActive.into());
            }
            // TB-4: re-checked in this second, independently re-borrowed scope.
            require_asset_generation_view(&group, domain_usize / 2, expected_market_id)?;
            // W3A-3: re-checked in this second, independently re-borrowed
            // scope -- mirrors upstream's second `require_authority_epoch_view`
            // call site, strictly preceding
            // `deposit_fresh_counterparty_backing_not_atomic` below (the
            // authoritative check for this mutation).
            require_authority_epoch_view(&group, domain_usize / 2, expected_authority_epoch)?;
            // sync/w1-abacking (5314c05f): re-authenticate the expiry against THIS borrow's
            // slot, not just the preflight borrow's -- a stale-slot retained transaction that
            // slipped past the preflight check above must still be rejected here, against the
            // freshest available slot, before any capital moves.
            //
            // Wave-1 S1a v2: re-check the LP-vault-sentinel exclusion here too -- this is the
            // re-check/reuse branch that actually calls
            // `deposit_fresh_counterparty_backing_not_atomic` with the caller-supplied
            // `expiry_slot` below, so it must fail closed on its own, not rely solely on the
            // preflight borrow above. See the preflight comment for the full rationale.
            if expiry_slot <= authenticated_market_slot_or_fallback_view(&group)
                || expiry_slot == crate::constants::LP_VAULT_BACKING_EXPIRY_SLOT
            {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            reject_permissionless_resolve_matured_live_view(&cfg, &group)?;
            require_domain_accepts_live_topup_view(&group, domain_usize)?;
            let authorities = domain_authorities_from_view(&group, &cfg, domain_usize)?;
            expect_live_authority(&authorities.backing_bucket_authority, signer.key)?;
            // sync/w2-tb3 (ADOPT upstream 20f0b9b1, intent_id slice only):
            // one-shot replay-nonce check on this asset's per-asset
            // `backing_top_up` lane.
            let asset_index = domain_usize / 2;
            let mut profile = read_oracle_profile_from_view(&group, &cfg, asset_index)?;
            state::require_newer_control_sequence(profile.backing_top_up, intent_id)?;
            let mut ledger_data = Some(ledger_ai.try_borrow_mut_data()?);
            let mut ledger_state = if let Some(data) = ledger_data.as_deref() {
                let (_, bucket) = backing_domain_parts_view(&group, domain as usize)?;
                let (mut ledger, initialized) = read_or_new_backing_domain_ledger(
                    data,
                    market_ai.key.to_bytes(),
                    authorities.backing_bucket_authority,
                    domain,
                    &bucket,
                )?;
                if initialized {
                    sync_backing_domain_ledger(&mut ledger, &bucket)?;
                } else {
                    seed_legacy_backing_domain_ledger(&mut ledger, &bucket)?;
                }
                Some((ledger, initialized))
            } else {
                None
            };
            group
                .deposit_fresh_counterparty_backing_not_atomic(domain_usize, amount, expiry_slot)
                .map_err(map_v16_error)?;
            if let Some((ledger, initialized)) = ledger_state.as_mut() {
                ledger.total_principal_atoms = ledger
                    .total_principal_atoms
                    .checked_add(amount)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                ledger.total_deposited_atoms = ledger
                    .total_deposited_atoms
                    .checked_add(amount)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;

                // #433 migration only. A top-up may satisfy provider receivable
                // and reduce consumed backing. For a ledger reconstructed from
                // the PRE-top-up bucket, that reduction is new capital refill,
                // not a newly observed recovery. Re-baseline it so the next
                // sync cannot count the refill twice.
                if !*initialized {
                    let (_, bucket_after) = backing_domain_parts_view(&group, domain as usize)?;
                    ledger.last_observed_unavailable_principal_atoms =
                        backing_unavailable_principal_atoms(&bucket_after)?;
                }
            }
            profile.backing_top_up = intent_id;
            write_oracle_profile_to_view(&mut group, asset_index, &profile)?;
            group.validate_shape().map_err(map_v16_error)?;
            if let (Some(data), Some((ledger, initialized))) =
                (ledger_data.as_deref_mut(), ledger_state.as_ref())
            {
                write_or_init_backing_domain_ledger(data, ledger, *initialized)?;
            }
        }
        if amount == 0 {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (cfg, mut group) = state::market_view_mut(&mut market_data)?;
            // W3A-3: mirrors upstream's third `require_authority_epoch_view`
            // call site (the `amount == 0` reconciliation branch), checked
            // immediately upon obtaining this borrow's `group`, before any
            // ledger read/write below.
            require_authority_epoch_view(&group, domain_usize / 2, expected_authority_epoch)?;
            let authorities = domain_authorities_from_view(&group, &cfg, domain_usize)?;
            expect_live_authority(&authorities.backing_bucket_authority, signer.key)?;
            // sync/w2-tb3 (ADOPT upstream 20f0b9b1, intent_id slice only):
            // this is the reconciliation-only path (upstream's diff added an
            // `else` branch here too, see the commit) -- the nonce must
            // still advance even though no capital moves, or a captured
            // zero-amount reconciliation call could be replayed forever.
            let asset_index = domain_usize / 2;
            let mut profile = read_oracle_profile_from_view(&group, &cfg, asset_index)?;
            state::require_newer_control_sequence(profile.backing_top_up, intent_id)?;

            let mut ledger_data = ledger_ai.try_borrow_mut_data()?;
            if !state::is_initialized(&ledger_data) {
                let (_, bucket) = backing_domain_parts_view(&group, domain_usize)?;
                let (mut ledger, initialized) = read_or_new_backing_domain_ledger(
                    &ledger_data,
                    market_ai.key.to_bytes(),
                    authorities.backing_bucket_authority,
                    domain,
                    &bucket,
                )?;

                seed_legacy_backing_domain_ledger(&mut ledger, &bucket)?;
                group.validate_shape().map_err(map_v16_error)?;
                write_or_init_backing_domain_ledger(&mut ledger_data, &ledger, initialized)?;
            }
            profile.backing_top_up = intent_id;
            write_oracle_profile_to_view(&mut group, asset_index, &profile)?;
        }

        transfer_tokens(token_program, source_token, vault_token, signer, amount_u64)?;
        Ok(())
    }

    /// ExpireBackingBucket (tag 89) — see `Instruction::ExpireBackingBucket`
    /// for the full rationale. Permissionless liveness repair: advances a
    /// `Fresh`-but-LAPSED source-domain backing bucket to `Expired`/`Impaired`
    /// so settlement against that domain can proceed again.
    ///
    /// Moves no tokens. The only state transition is the engine's own
    /// `expire_source_backing_bucket_not_atomic`, which fails closed with
    /// `Stale` unless the bucket is `Fresh` and `now_slot >= expiry_slot`.
    #[inline(never)]
    fn handle_expire_backing_bucket<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        domain: u16,
    ) -> ProgramResult {
        let market_ai = account(accounts, 0)?;
        expect_writable(market_ai)?;
        expect_owner(market_ai, program_id)?;

        let domain_usize = domain as usize;
        let cfg_after = {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (cfg, mut group) = state::market_view_mut(&mut market_data)?;
            // Live-only. A resolved/wound-down market already reaches the
            // transition through the engine's own resolved-close path, so
            // re-entering it from outside would be a second, unsequenced
            // mutation of a terminal ledger.
            //
            // W-18: this used to name `realize_source_backed_claims_for_resolved_close_not_atomic`.
            // That function is GONE at the linked engine (`percolator 2c38570a`, grep count
            // 1 -> 0 since `9483ee90`); upstream `a0e27950` / #239 replaced the unbounded sweep
            // with the bounded per-domain pair
            // `prepare_one_source_domain_for_resolved_close_not_atomic` (`2c38570a:src/v16.rs:20399`)
            // and `realize_one_source_domain_for_resolved_close_not_atomic` (`:20277`), driven from
            // `close_resolved_account_not_atomic` (`:20597`). The gate below is unchanged and still
            // correct; only its stated reason was pointing at a missing symbol.
            if group.header.mode != 0 {
                return Err(PercolatorError::EngineLockActive.into());
            }
            let configured_slots = group.header.config.max_market_slots.get() as usize;
            if domain_usize >= configured_slots.saturating_mul(2) {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            // The slot is the runtime Clock, NEVER a caller argument: this is
            // the only thing standing between "recover a bricked domain" and
            // "let anyone forfeit live backing early". `max` against the
            // engine's own `current_slot` keeps the two monotone, matching every
            // other authenticated-slot site in this program.
            let now_slot = authenticated_market_slot_or_fallback_view(&group);
            group
                .expire_source_backing_bucket_not_atomic(domain_usize, now_slot)
                .map_err(map_v16_error)?;
            group.validate_shape().map_err(map_v16_error)?;
            cfg
        };
        state::write_wrapper_config(&mut market_ai.try_borrow_mut_data()?, &cfg_after)
    }

    #[inline(never)]
    fn handle_withdraw_backing_bucket<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        domain: u16,
        expected_market_id: u64,
        amount: u128,
        expected_authority_epoch: u64,
    ) -> ProgramResult {
        let authority = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let dest_token = account(accounts, 2)?;
        let vault_token = account(accounts, 3)?;
        let vault_authority_ai = account(accounts, 4)?;
        let token_program = account(accounts, 5)?;
        // ⚠️ OPTIONAL, and it MUST stay optional. #433 asked for it to be mandatory and a
        // first fix (45bba89e) made it so; that was DEPLOYED and immediately stranded funds.
        //
        // The backing-domain ledger PDA is only ever ALLOCATED by the LP-vault handlers.
        // `write_or_init_backing_domain_ledger` writes into an existing buffer — nothing on
        // this path can create the account. So on any market without an LP vault the ledger
        // does not exist, `expect_owner(ledger_ai, program_id)` fails, and backing deposited
        // through the 5-account `TopUpBackingBucket` could never be withdrawn again. That is
        // strictly worse than the accounting bypass #433 reports.
        //
        // Upstream keeps it optional too (`upstream/main` handle_withdraw_backing_bucket,
        // `accounts.get(6)` + `if let Some`), which is corroboration rather than coincidence.
        //
        // #433 IS REAL and is still open: when the account is omitted, both the
        // principal-consistency guard and the decrement are skipped. Closing it needs the
        // ledger to be creatable on this path (payer + system program) or mandatory on
        // TopUpBackingBucket first — not a bare `account(accounts, 6)?`.
        // MANDATORY again, and now safe: `handle_top_up_backing_bucket` CREATES this PDA, so
        // one exists before any withdrawal is possible. Requiring it WITHOUT that creation
        // path (45bba89e) is what stranded funds — see the revert note in git history.
        let ledger_ai = account(accounts, 6)?;
        // W4-PAYOUT: signer requirement moved into `verify_domain_withdrawal_preflight`,
        // conditional on market mode (Resolved reserve payouts are permissionless; Live
        // ones still require `authority`'s signature). Do NOT re-add an unconditional
        // `expect_signer(authority)` here -- that would defeat the permissionless path.
        expect_writable(market_ai)?;
        expect_writable(dest_token)?;
        expect_writable(vault_token)?;
        expect_owner(market_ai, program_id)?;
        expect_writable(ledger_ai)?;
        expect_owner(ledger_ai, program_id)?;
        let (ledger_pda, _) = state::derive_lp_backing_ledger(program_id, market_ai.key, domain);
        expect_key(ledger_ai, &ledger_pda)?;
        verify_token_program(token_program)?;
        if amount == 0 {
            return Err(PercolatorError::InvalidInstruction.into());
        }

        let domain_usize = domain as usize;
        let (bump, amount_u64) = verify_domain_withdrawal_preflight(
            program_id,
            market_ai,
            authority,
            dest_token,
            vault_token,
            vault_authority_ai,
            domain_usize,
            amount,
            expected_market_id,
            false,
            DOMAIN_WITHDRAW_AUTH_BACKING,
        )?;

        {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (cfg, mut group) = state::market_view_mut(&mut market_data)?;
            require_asset_generation_view(&group, domain_usize / 2, expected_market_id)?;
            let authorities = domain_authorities_from_view(&group, &cfg, domain_usize)?;
            let shutdown_drain = match group.header.mode {
                0 => live_domain_withdraw_health_or_shutdown_view(&cfg, &group, domain_usize)?,
                1 => {
                    if group.header.materialized_portfolio_count.get() != 0
                        || group.header.c_tot.get() != 0
                    {
                        return Err(PercolatorError::EngineLockActive.into());
                    }
                    false
                }
                _ => return Err(PercolatorError::EngineLockActive.into()),
            };
            let local_authorized =
                live_authority_matches(&authorities.backing_bucket_authority, authority.key);
            let admin_shutdown_authorized =
                shutdown_drain && live_authority_matches(&cfg.marketauth, authority.key);
            if !local_authorized && !admin_shutdown_authorized {
                return Err(PercolatorError::Unauthorized.into());
            }
            // F-3 / D-STAKE-1 guard: when backing_bucket_authority is a bound (non-zero) authority
            // — which it always is for an activated asset, and which the stake program can set to
            // its PDA — the admin shutdown-drain path MUST NOT bypass it. Mirrors the guard in
            // handle_withdraw_insurance_asset. When that authority == marketauth the local path
            // already covers a legitimate marketauth withdrawal; when it is a distinct stake PDA,
            // marketauth can no longer use shutdown-drain to bypass stake governance.
            let admin_shutdown_authorized = if authorities.backing_bucket_authority != [0u8; 32] {
                false
            } else {
                admin_shutdown_authorized
            };
            if !local_authorized && !admin_shutdown_authorized {
                return Err(PercolatorError::Unauthorized.into());
            }
            // W3A-1 (upstream `ade6f9fa`): bound AFTER both authorization gates settle
            // (so the D-STAKE-1 narrowing above is already reflected in
            // `local_authorized`), BEFORE `ledger_authority` is chosen or any state is
            // touched. `local_authorized` reads the WITHDRAWING DOMAIN's own asset
            // epoch (`domain_usize / 2`, matching `UpdateAssetAuthority`'s per-asset
            // lane); the admin shutdown-drain fallback instead reads asset-0's epoch
            // (the same slot `UpdateAuthority`/marketauth rotation advances), so an
            // admin-path withdrawal is invalidated by a marketauth rotation exactly
            // like a local-authority withdrawal is invalidated by an asset-authority
            // rotation.
            let epoch_asset_index = if local_authorized { domain_usize / 2 } else { 0 };
            require_authority_epoch_view(&group, epoch_asset_index, expected_authority_epoch)?;
            // W4-PAYOUT (upstream c162d7c7): ledger attribution is bound to the recorded
            // backing_bucket_authority always, never to `cfg.marketauth`. The prior
            // marketauth-substitution let an admin-shutdown-drain submission attribute
            // (and, before this unit, redirect) the withdrawal to marketauth itself
            // instead of the true reserve owner. The F-3/D-STAKE-1 guard above already
            // forces `admin_shutdown_authorized` false whenever `backing_bucket_authority`
            // is bound (non-zero), so this branch is only reachable with an UNBOUND
            // (zero) authority -- attributing to the zero key there is intentional: it
            // makes the fallback pay out to a destination nobody can practically hold
            // (equivalent to unreachable), rather than to whichever admin happened to
            // submit the transaction.
            let ledger_authority = authorities.backing_bucket_authority;

            let (_, bucket) = backing_domain_parts_view(&group, domain_usize)?;
            // W-21 / C-S-10b — adopt upstream's lapsed-bucket refusal
            // (`2b1d025c:src/v16_program.rs:10561-10567`), in the same position:
            // after the bucket is read, before the ledger is touched or the engine is
            // called. A Fresh bucket whose `expiry_slot` has been reached is going to
            // be forfeited into the junior residual pool by the next tag-89
            // `ExpireBackingBucket`, which is permissionless; the engine's own
            // withdrawal gate (`2c38570a:src/v16.rs:2815-2819`) tests `status != Fresh`
            // only, so without this the provider wins that race and takes principal the
            // expiry rule has already earmarked. Refusing here is not a new
            // authorization: the provider's own remedy is to re-fund the bucket at a
            // later expiry (tag 50 top-up), which the bucket family already supports.
            if !policy_v16::backing_principal_withdrawal_is_fresh(
                bucket.expiry_slot,
                authenticated_market_slot_or_fallback_view(&group),
            ) {
                return Err(PercolatorError::EngineStale.into());
            }
            {
                let mut ledger_data = ledger_ai.try_borrow_mut_data()?;
                let (mut ledger, initialized) = read_or_new_backing_domain_ledger(
                    &ledger_data,
                    market_ai.key.to_bytes(),
                    ledger_authority,
                    domain,
                    &bucket,
                )?;
                sync_backing_domain_ledger(&mut ledger, &bucket)?;
                if amount > ledger.total_principal_atoms {
                    return Err(PercolatorError::EngineCounterUnderflow.into());
                }
                group
                    .withdraw_fresh_counterparty_backing_not_atomic(domain_usize, amount)
                    .map_err(map_v16_error)?;
                ledger.total_principal_atoms = ledger
                    .total_principal_atoms
                    .checked_sub(amount)
                    .ok_or(PercolatorError::EngineCounterUnderflow)?;
                ledger.total_principal_withdrawn_atoms = ledger
                    .total_principal_withdrawn_atoms
                    .checked_add(amount)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                group.validate_shape().map_err(map_v16_error)?;
                write_or_init_backing_domain_ledger(&mut ledger_data, &ledger, initialized)?;
            }
        }

        let bump_arr = [bump];
        let signer_seeds: &[&[&[u8]]] = &[&[b"vault", market_ai.key.as_ref(), &bump_arr]];
        transfer_tokens_signed(
            token_program,
            vault_token,
            dest_token,
            vault_authority_ai,
            amount_u64,
            signer_seeds,
        )?;
        Ok(())
    }

    #[inline(never)]
    fn handle_withdraw_backing_bucket_earnings<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        domain: u16,
        expected_market_id: u64,
        amount: u128,
        expected_authority_epoch: u64,
    ) -> ProgramResult {
        let authority = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let ledger_ai = account(accounts, 2)?;
        let dest_token = account(accounts, 3)?;
        let vault_token = account(accounts, 4)?;
        let vault_authority_ai = account(accounts, 5)?;
        let token_program = account(accounts, 6)?;
        // W4-PAYOUT: signer requirement moved into `verify_domain_withdrawal_preflight`,
        // conditional on market mode. See handle_withdraw_backing_bucket for the full note.
        expect_writable(market_ai)?;
        expect_writable(ledger_ai)?;
        expect_writable(dest_token)?;
        expect_writable(vault_token)?;
        expect_owner(market_ai, program_id)?;
        expect_owner(ledger_ai, program_id)?;
        verify_token_program(token_program)?;
        if amount == 0 {
            return Err(PercolatorError::InvalidInstruction.into());
        }

        let domain_usize = domain as usize;
        let (bump, amount_u64) = verify_domain_withdrawal_preflight(
            program_id,
            market_ai,
            authority,
            dest_token,
            vault_token,
            vault_authority_ai,
            domain_usize,
            amount,
            expected_market_id,
            false,
            DOMAIN_WITHDRAW_AUTH_BACKING,
        )?;

        {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (cfg, mut group) = state::market_view_mut(&mut market_data)?;
            require_asset_generation_view(&group, domain_usize / 2, expected_market_id)?;
            let authorities = domain_authorities_from_view(&group, &cfg, domain_usize)?;
            let shutdown_drain = match group.header.mode {
                0 => live_domain_withdraw_health_or_shutdown_view(&cfg, &group, domain_usize)?,
                1 => {
                    if group.header.materialized_portfolio_count.get() != 0
                        || group.header.c_tot.get() != 0
                    {
                        return Err(PercolatorError::EngineLockActive.into());
                    }
                    false
                }
                _ => return Err(PercolatorError::EngineLockActive.into()),
            };
            let local_authorized =
                live_authority_matches(&authorities.backing_bucket_authority, authority.key);
            let admin_shutdown_authorized =
                shutdown_drain && live_authority_matches(&cfg.marketauth, authority.key);
            if !local_authorized && !admin_shutdown_authorized {
                return Err(PercolatorError::Unauthorized.into());
            }
            // F-3 / D-STAKE-1 guard: when backing_bucket_authority is a bound (non-zero) authority
            // — which it always is for an activated asset, and which the stake program can set to
            // its PDA — the admin shutdown-drain path MUST NOT bypass it. Mirrors the guard in
            // handle_withdraw_insurance_asset. When that authority == marketauth the local path
            // already covers a legitimate marketauth withdrawal; when it is a distinct stake PDA,
            // marketauth can no longer use shutdown-drain to bypass stake governance.
            let admin_shutdown_authorized = if authorities.backing_bucket_authority != [0u8; 32] {
                false
            } else {
                admin_shutdown_authorized
            };
            if !local_authorized && !admin_shutdown_authorized {
                return Err(PercolatorError::Unauthorized.into());
            }
            // W3A-1 (upstream `ade6f9fa`): same `epoch_asset_index` selection and
            // position as `handle_withdraw_backing_bucket` above -- see that call
            // site's doc comment.
            let epoch_asset_index = if local_authorized { domain_usize / 2 } else { 0 };
            require_authority_epoch_view(&group, epoch_asset_index, expected_authority_epoch)?;
            // W4-PAYOUT (upstream c162d7c7): see the identical comment in
            // handle_withdraw_backing_bucket -- ledger attribution binds to the recorded
            // backing_bucket_authority, never to `cfg.marketauth`.
            let ledger_authority = authorities.backing_bucket_authority;

            let (_, bucket) = backing_domain_parts_view(&group, domain_usize)?;
            if amount > bucket.utilization_fee_earnings || amount > group.header.vault.get() {
                return Err(PercolatorError::EngineLockActive.into());
            }
            let mut ledger_data = ledger_ai.try_borrow_mut_data()?;
            let (mut ledger, initialized) = read_or_new_backing_domain_ledger(
                &ledger_data,
                market_ai.key.to_bytes(),
                ledger_authority,
                domain,
                &bucket,
            )?;
            sync_backing_domain_ledger(&mut ledger, &bucket)?;
            group
                .withdraw_backing_provider_earnings_not_atomic(domain_usize, amount)
                .map_err(map_v16_error)?;
            ledger.last_observed_bucket_earnings_atoms = ledger
                .last_observed_bucket_earnings_atoms
                .checked_sub(amount)
                .ok_or(PercolatorError::EngineCounterUnderflow)?;
            ledger.total_earnings_withdrawn_atoms = ledger
                .total_earnings_withdrawn_atoms
                .checked_add(amount)
                .ok_or(PercolatorError::EngineArithmeticOverflow)?;
            group.validate_shape().map_err(map_v16_error)?;
            write_or_init_backing_domain_ledger(&mut ledger_data, &ledger, initialized)?;
        }

        let bump_arr = [bump];
        let signer_seeds: &[&[&[u8]]] = &[&[b"vault", market_ai.key.as_ref(), &bump_arr]];
        transfer_tokens_signed(
            token_program,
            vault_token,
            dest_token,
            vault_authority_ai,
            amount_u64,
            signer_seeds,
        )?;
        Ok(())
    }

    #[inline(never)]
    fn handle_sync_backing_domain_ledger<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        domain: u16,
    ) -> ProgramResult {
        let authority = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let ledger_ai = account(accounts, 2)?;
        expect_signer(authority)?;
        expect_writable(market_ai)?;
        expect_writable(ledger_ai)?;
        expect_owner(market_ai, program_id)?;
        expect_owner(ledger_ai, program_id)?;

        let mut market_data = market_ai.try_borrow_mut_data()?;
        let (cfg, group) = state::market_view_mut(&mut market_data)?;
        let domain_usize = domain as usize;
        let authorities = domain_authorities_from_view(&group, &cfg, domain_usize)?;
        expect_live_authority(&authorities.backing_bucket_authority, authority.key)?;
        let (_, bucket) = backing_domain_parts_view(&group, domain_usize)?;
        let mut ledger_data = ledger_ai.try_borrow_mut_data()?;
        let (mut ledger, initialized) = read_or_new_backing_domain_ledger(
            &ledger_data,
            market_ai.key.to_bytes(),
            authorities.backing_bucket_authority,
            domain,
            &bucket,
        )?;
        sync_backing_domain_ledger(&mut ledger, &bucket)?;
        write_or_init_backing_domain_ledger(&mut ledger_data, &ledger, initialized)
    }

    #[inline(never)]
    fn handle_sync_insurance_ledger<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
    ) -> ProgramResult {
        let authority = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let ledger_ai = account(accounts, 2)?;
        expect_signer(authority)?;
        expect_writable(market_ai)?;
        expect_writable(ledger_ai)?;
        expect_owner(market_ai, program_id)?;
        expect_owner(ledger_ai, program_id)?;

        let mut market_data = market_ai.try_borrow_mut_data()?;
        let (cfg, group) = state::market_view_mut(&mut market_data)?;
        let asset0_insurance_authority =
            domain_authorities_from_view(&group, &cfg, 0)?.insurance_authority;
        expect_live_authority(&asset0_insurance_authority, authority.key)?;
        let mut ledger_data = ledger_ai.try_borrow_mut_data()?;
        let observed = market_insurance_remaining_view(&group, 0)?;
        let (mut ledger, initialized) = read_or_new_insurance_ledger(
            &ledger_data,
            market_ai.key.to_bytes(),
            asset0_insurance_authority,
            observed,
        )?;
        sync_insurance_ledger(&mut ledger, observed)?;
        write_or_init_insurance_ledger(&mut ledger_data, &ledger, initialized)
    }

    #[inline(never)]
    fn handle_withdraw_insurance<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        amount: u128,
    ) -> ProgramResult {
        let authority = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let dest_token = account(accounts, 2)?;
        let vault_token = account(accounts, 3)?;
        let vault_authority_ai = account(accounts, 4)?;
        let token_program = account(accounts, 5)?;
        let ledger_ai = accounts.get(6);
        // W4-PAYOUT (upstream d64cdeeb "make terminal insurance payout permissionless" +
        // 82f44d11/c162d7c7): this is our fork's terminal (tag 41) reserve payout -- it
        // only ever succeeds when `group.header.mode == Resolved` (checked, unconditionally,
        // just below), so unlike the shared `verify_domain_withdrawal_preflight` helper
        // there is no Live-mode case to keep signer-gated here. Dropping the unconditional
        // signer requirement reverses our fork's prior stricter-by-choice stance (this was
        // always signer-gated even in Resolved mode) so that ANY cranker can settle a
        // terminal insurance reserve once a market is wound down -- liveness: an authority
        // that has gone cold, lost its key, or simply never bothers to call this cannot
        // strand the reserve.
        //
        // Beneficiary binding for this specific instruction: `authority.key` is not a
        // separate "submitter identity" from the recipient the way it is in
        // `verify_domain_withdrawal_preflight` (no marketauth admin-fallback exists here).
        // `terminal_insurance_withdraw_capacity_for_authority_view` /
        // `debit_terminal_insurance_budgets_for_authority_view` below sum and debit
        // EXACTLY the domains whose recorded `insurance_authority` equals `authority.key`,
        // and the destination check further down still requires `dest.owner ==
        // authority.key`. So the key named in the `authority` account IS definitionally
        // the beneficiary being paid: a permissionless caller can settle any bound
        // authority's reserve into that authority's own token account, but cannot name a
        // different destination or redirect to itself -- it would just debit zero (both
        // helpers reject the zero key and any key that owns no domain's insurance_authority).
        expect_writable(market_ai)?;
        expect_writable(dest_token)?;
        expect_writable(vault_token)?;
        expect_owner(market_ai, program_id)?;
        if let Some(ledger_ai) = ledger_ai {
            expect_writable(ledger_ai)?;
            expect_owner(ledger_ai, program_id)?;
        }
        verify_token_program(token_program)?;
        if amount == 0 {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        // F-1: read the authenticated slot up front; fail closed if the clock syscall fails.
        let now_slot = Clock::get()?.slot;

        let (cfg_pre, policy_dirty) = {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (mut cfg, mut group) = state::market_view_mut(&mut market_data)?;
            let available_insurance = terminal_insurance_withdraw_capacity_for_authority_view(
                &group,
                &cfg,
                authority.key,
            )?;
            if group.header.mode != 1
                || group.header.materialized_portfolio_count.get() != 0
                || group.header.c_tot.get() != 0
                || amount > available_insurance
                || amount > group.header.vault.get()
            {
                return Err(PercolatorError::EngineLockActive.into());
            }

            // F-1: gate the withdrawal against the insurance-withdrawal cooldown before mutating
            // any state. Pure helper (unit-tested + Kani-proven). The deposits-only ceiling (F-2)
            // is enforced together with its decrement at the end of this block.
            check_insurance_withdraw_cooldown(
                cfg.insurance_withdraw_cooldown_slots,
                cfg.last_insurance_withdraw_slot,
                now_slot,
            )?;
            let mut ledger_data = if let Some(ledger_ai) = ledger_ai {
                Some(ledger_ai.try_borrow_mut_data()?)
            } else {
                None
            };
            let mut ledger_state = if let Some(data) = ledger_data.as_deref() {
                let (mut ledger, initialized) = read_or_new_insurance_ledger(
                    data,
                    market_ai.key.to_bytes(),
                    authority.key.to_bytes(),
                    available_insurance,
                )?;
                sync_insurance_ledger(&mut ledger, available_insurance)?;
                Some((ledger, initialized))
            } else {
                None
            };
            // insurance + vault + per-domain budget all decremented atomically inside the engine
            // withdraw (called per domain by the helper); no separate header decrement here.
            debit_terminal_insurance_budgets_for_authority_view(
                &mut group,
                &cfg,
                authority.key,
                amount,
            )?;
            if let Some((ledger, _)) = ledger_state.as_mut() {
                ledger.total_withdrawn_atoms = ledger
                    .total_withdrawn_atoms
                    .checked_add(amount)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                ledger.total_principal_atoms = ledger.total_principal_atoms.saturating_sub(amount);
                ledger.last_observed_insurance_atoms = ledger
                    .last_observed_insurance_atoms
                    .checked_sub(amount)
                    .ok_or(PercolatorError::EngineCounterUnderflow)?;
            }
            group.validate_shape().map_err(map_v16_error)?;
            if let (Some(data), Some((ledger, initialized))) =
                (ledger_data.as_deref_mut(), ledger_state.as_ref())
            {
                write_or_init_insurance_ledger(data, ledger, *initialized)?;
            }

            // F-1 / F-2: apply BOTH policy mutations to the single cfg binding before it leaves
            // the borrow scope, then persist once below. Mutating one binding (rather than two
            // separate write-backs) prevents dropping the cooldown update when the deposits-only
            // ceiling is also active, and vice-versa.
            // F-1 / F-2: apply both policy mutations to the single cfg binding before it leaves the
            // borrow scope (one binding, so neither update can clobber the other — this is the
            // co-activation bug the original PR #389 had), then persist once below.
            // apply_insurance_withdraw_ceiling enforces the deposits-only ceiling and returns the
            // decremented remaining (or the unchanged value when the ceiling is disabled).
            let policy_dirty = cfg.insurance_withdraw_cooldown_slots > 0
                || cfg.insurance_withdraw_deposits_only != 0;
            if cfg.insurance_withdraw_cooldown_slots > 0 {
                cfg.last_insurance_withdraw_slot = now_slot;
            }
            cfg.insurance_withdraw_deposit_remaining = apply_insurance_withdraw_ceiling(
                cfg.insurance_withdraw_deposits_only,
                cfg.insurance_withdraw_deposit_remaining,
                amount,
            )?;
            (cfg, policy_dirty)
        };

        let (vault_authority, bump) = derive_vault_authority(program_id, market_ai.key);
        expect_key(vault_authority_ai, &vault_authority)?;
        // Fork hardening (W5 / upstream b7b6688e / #154): this payout no longer requires a
        // signature from `authority`, so guard against a dest_token the recipient left an
        // active delegate/close_authority on -- see the identical note in
        // `verify_domain_withdrawal_preflight`. WithdrawInsurance is Resolved-only (always
        // permissionless), so `require_unencumbered_dest` is unconditionally `true`.
        // sync(W4-TOKEN22): folded into the widened `verify_withdrawable_token_accounts`
        // instead of a second standalone call.
        let vault_balance = verify_withdrawable_token_accounts(
            dest_token,
            authority.key,
            vault_token,
            &vault_authority,
            &cfg_pre,
            true,
        )?;

        // F-1 / F-2: persist the policy update (cooldown slot + deposits-only ceiling decrement).
        // Skipped when no insurance-withdrawal policy is configured, preserving exact prior
        // behavior for markets without the policy.
        if policy_dirty {
            state::write_wrapper_config(&mut market_ai.try_borrow_mut_data()?, &cfg_pre)?;
        }
        let amount_u64 = amount_to_u64(amount)?;
        require_token_balance(vault_balance, amount_u64)?;
        let bump_arr = [bump];
        let signer_seeds: &[&[&[u8]]] = &[&[b"vault", market_ai.key.as_ref(), &bump_arr]];
        transfer_tokens_signed(
            token_program,
            vault_token,
            dest_token,
            vault_authority_ai,
            amount_u64,
            signer_seeds,
        )?;
        Ok(())
    }

    #[inline(never)]
    fn handle_withdraw_insurance_asset<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        asset_index: u16,
        expected_market_id: u64,
        amount: u128,
        expected_authority_epoch: u64,
    ) -> ProgramResult {
        let operator = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let dest_token = account(accounts, 2)?;
        let vault_token = account(accounts, 3)?;
        let vault_authority_ai = account(accounts, 4)?;
        let token_program = account(accounts, 5)?;
        let ledger_ai = accounts.get(6);
        expect_signer(operator)?;
        expect_writable(market_ai)?;
        expect_writable(dest_token)?;
        expect_writable(vault_token)?;
        expect_owner(market_ai, program_id)?;
        if let Some(ledger_ai) = ledger_ai {
            expect_writable(ledger_ai)?;
            expect_owner(ledger_ai, program_id)?;
        }
        verify_token_program(token_program)?;
        if amount == 0 {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        // #396: the insurance-withdrawal cooldown is market-wide — enforce it on this
        // per-asset path too. Read the slot up front; fail closed if the clock syscall fails.
        let now_slot = Clock::get()?.slot;
        let asset_index = asset_index as usize;
        let long_domain = asset_index
            .checked_mul(2)
            .ok_or(PercolatorError::EngineArithmeticOverflow)?;
        let (bump, amount_u64) = verify_domain_withdrawal_preflight(
            program_id,
            market_ai,
            operator,
            dest_token,
            vault_token,
            vault_authority_ai,
            long_domain,
            amount,
            expected_market_id,
            true,
            DOMAIN_WITHDRAW_AUTH_INSURANCE,
        )?;
        let (cfg_after, cooldown_dirty) = {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (mut cfg, mut group) = state::market_view_mut(&mut market_data)?;
            if group.header.mode != 0 {
                return Err(PercolatorError::EngineLockActive.into());
            }
            let configured_slots = group.header.config.max_market_slots.get() as usize;
            if asset_index >= configured_slots || asset_index >= group.markets.len() {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            require_asset_generation_view(&group, asset_index, expected_market_id)?;
            let shutdown_drain =
                live_domain_withdraw_health_or_shutdown_view(&cfg, &group, long_domain)?;
            let authorities = domain_authorities_from_view(&group, &cfg, long_domain)?;
            let local_authorized =
                live_authority_matches(&authorities.insurance_operator, operator.key);
            let admin_shutdown_authorized = asset_index != 0
                && shutdown_drain
                && live_authority_matches(&cfg.marketauth, operator.key);
            if !local_authorized && !admin_shutdown_authorized {
                return Err(PercolatorError::Unauthorized.into());
            }
            // D-STAKE-1 guard: when insurance_authority is a bound (non-zero) PDA —
            // which the stake program sets via BindInsuranceAuthority — the admin
            // shutdown-drain path MUST NOT be used to bypass stake-program governance.
            // Stakers are entitled to a ReturnInsurance CPI from the stake program;
            // allowing marketauth to drain directly undermines that guarantee.
            // If insurance_authority is set, only the local insurance_operator path
            // is valid (admin_shutdown_authorized is silently overridden to false).
            let admin_shutdown_authorized = if authorities.insurance_authority != [0u8; 32] {
                // Bound PDA detected — admin shutdown drain not permitted.
                false
            } else {
                admin_shutdown_authorized
            };
            if !local_authorized && !admin_shutdown_authorized {
                return Err(PercolatorError::Unauthorized.into());
            }
            // W3A-1 (upstream `ade6f9fa`): bound after both authorization gates settle,
            // before any further state is touched (cooldown check, ledger, budget
            // debit). `local_authorized` is already scoped to THIS `asset_index`
            // (`long_domain = asset_index * 2`), so the local path reads that asset's
            // own epoch; the admin shutdown-drain fallback reads asset-0's epoch (the
            // marketauth-rotation lane), matching `WithdrawBackingBucket[Earnings]`'s
            // identical `epoch_asset_index` selection above.
            let epoch_asset_index = if local_authorized { asset_index } else { 0 };
            require_authority_epoch_view(&group, epoch_asset_index, expected_authority_epoch)?;
            // #396: enforce the market-wide insurance-withdrawal cooldown on this per-asset path
            // too — it shares insurance_withdraw_cooldown_slots / last_insurance_withdraw_slot with
            // the terminal handle_withdraw_insurance. (The deposits-only ceiling stays terminal-only;
            // its budget tracks market-zero deposited principal, not per-asset insurance.)
            check_insurance_withdraw_cooldown(
                cfg.insurance_withdraw_cooldown_slots,
                cfg.last_insurance_withdraw_slot,
                now_slot,
            )?;
            // W4-PAYOUT (upstream c162d7c7): the ledger authority is bound to the domain's
            // recorded insurance_operator always, matching `verify_domain_withdrawal_preflight`'s
            // destination check (also bound to `authorities.insurance_operator`, never to
            // whichever key executed the instruction). Previously this attributed the
            // admin-shutdown-fallback withdrawal to `cfg.marketauth` while the destination
            // check (pre-W4-PAYOUT) verified `dest.owner == operator.key` -- which is
            // `cfg.marketauth` on that path too, so marketauth could redirect an
            // insurance_operator's reserve to an account it owned itself whenever
            // insurance_authority was never bound (D-STAKE-1 unreached). Both destination
            // and ledger now agree: funds and the receipt both go to insurance_operator: the
            // admin-shutdown submitter authorizes the payout but is never its recipient.
            let ledger_authority = authorities.insurance_operator;
            let available = market_insurance_withdraw_capacity_view(&group, asset_index)?;
            if amount > available
                || amount > group.header.insurance.get()
                || amount > group.header.vault.get()
            {
                return Err(PercolatorError::EngineLockActive.into());
            }
            let mut ledger_data = if let Some(ledger_ai) = ledger_ai {
                Some(ledger_ai.try_borrow_mut_data()?)
            } else {
                None
            };
            let mut ledger_state = if let Some(data) = ledger_data.as_deref() {
                let (mut ledger, initialized) = read_or_new_insurance_ledger(
                    data,
                    market_ai.key.to_bytes(),
                    ledger_authority,
                    available,
                )?;
                sync_insurance_ledger(&mut ledger, available)?;
                Some((ledger, initialized))
            } else {
                None
            };
            // Atomic insurance/vault/budget withdraw through the engine (maintains the
            // insurance_domain_budget_remaining_total aggregate).
            debit_market_insurance_budget_view(&mut group, asset_index, amount)?;
            if let Some((ledger, _)) = ledger_state.as_mut() {
                ledger.total_withdrawn_atoms = ledger
                    .total_withdrawn_atoms
                    .checked_add(amount)
                    .ok_or(PercolatorError::EngineArithmeticOverflow)?;
                ledger.total_principal_atoms = ledger.total_principal_atoms.saturating_sub(amount);
                ledger.last_observed_insurance_atoms = ledger
                    .last_observed_insurance_atoms
                    .checked_sub(amount)
                    .ok_or(PercolatorError::EngineCounterUnderflow)?;
            }
            group.validate_shape().map_err(map_v16_error)?;
            if let (Some(data), Some((ledger, initialized))) =
                (ledger_data.as_deref_mut(), ledger_state.as_ref())
            {
                write_or_init_insurance_ledger(data, ledger, *initialized)?;
            }
            // #396: record this withdrawal against the market-wide cooldown clock (shared with
            // the terminal path), applied to a single cfg binding then persisted once below.
            let cooldown_dirty = cfg.insurance_withdraw_cooldown_slots > 0;
            if cooldown_dirty {
                cfg.last_insurance_withdraw_slot = now_slot;
            }
            (cfg, cooldown_dirty)
        };
        // #396: persist the cooldown-slot update (only when a cooldown is configured, so markets
        // without the policy keep their exact prior behavior / no extra write).
        if cooldown_dirty {
            state::write_wrapper_config(&mut market_ai.try_borrow_mut_data()?, &cfg_after)?;
        }
        let bump_arr = [bump];
        let signer_seeds: &[&[&[u8]]] = &[&[b"vault", market_ai.key.as_ref(), &bump_arr]];
        transfer_tokens_signed(
            token_program,
            vault_token,
            dest_token,
            vault_authority_ai,
            amount_u64,
            signer_seeds,
        )?;
        Ok(())
    }

    /// WithdrawProtocolFee (tag 84, design §3.1). Pays out from the accrued-
    /// but-unwithdrawn protocol claim to an external token account.
    /// `amount == 0` means "withdraw all currently-available capacity".
    /// Modeled on `handle_withdraw_insurance_asset` minus the domain-budget
    /// bookkeeping (and with no insurance-withdraw-cooldown gate: that
    /// mechanism is a creator-facing anti-drain throttle on the *domain*
    /// budgets; the protocol's claim is a separately-accounted, non-domain
    /// balance and `protocol_fee_authority` is not an adversary this design
    /// defends against).
    ///
    /// W12: ResolveMarket is one-way (no path back to Live), so a Live-only
    /// gate here would permanently strand any outstanding
    /// `protocol_fee_accrued_atoms` backlog the instant a market resolves --
    /// forever, since there is no other exit for it. Mirrors
    /// `handle_withdraw_insurance`'s (tag 41) bounded terminal exit: Resolved
    /// is allowed once the market is fully wound down
    /// (`materialized_portfolio_count == 0 && c_tot == 0`, i.e. every
    /// portfolio has closed with no unfinalized resolved-payout receipt and
    /// no outstanding capital claim -- see
    /// `is_empty_for_dematerialization`/`deregister_empty_materialized_portfolio_not_atomic`
    /// in the engine). At that point `vault` has no other claimant, so the
    /// existing `engine_available`/`vault` clamp below is exactly as safe as
    /// it is in Live mode -- this does not weaken the reserve invariant, it
    /// only widens *when* the already-bounded surplus withdraw is reachable.
    #[inline(never)]
    fn handle_withdraw_protocol_fee<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        amount: u128,
        expected_authority_epoch: u64,
    ) -> ProgramResult {
        let authority = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let dest_token = account(accounts, 2)?;
        let vault_token = account(accounts, 3)?;
        let vault_authority_ai = account(accounts, 4)?;
        let token_program = account(accounts, 5)?;
        expect_signer(authority)?;
        expect_writable(market_ai)?;
        expect_writable(dest_token)?;
        expect_writable(vault_token)?;
        expect_owner(market_ai, program_id)?;
        verify_token_program(token_program)?;

        let (vault_authority, bump) = derive_vault_authority(program_id, market_ai.key);
        expect_key(vault_authority_ai, &vault_authority)?;

        let (transfer_amount_u64, cfg_after) = {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (mut cfg, mut group) = state::market_view_mut(&mut market_data)?;
            let live_mode = group.header.mode == 0;
            let resolved_mode = group.header.mode == 1;
            if !live_mode && !resolved_mode {
                return Err(PercolatorError::EngineLockActive.into());
            }
            if resolved_mode
                && (group.header.materialized_portfolio_count.get() != 0
                    || group.header.c_tot.get() != 0)
            {
                return Err(PercolatorError::EngineLockActive.into());
            }
            if !live_authority_matches(&cfg.protocol_fee_authority, authority.key) {
                return Err(PercolatorError::Unauthorized.into());
            }
            // W4-AE-84: gate-2-class replay protection -- a direct
            // fund-withdrawal instruction, signer-gated on
            // `cfg.protocol_fee_authority` (rotated only via
            // `SetProtocolFeeAuthority`, tag 85) with zero prior replay
            // protection. CHECK ONLY against the market-wide
            // `protocol_fee_authority_epoch` counter -- this tag does not
            // itself rotate `protocol_fee_authority`, so it never advances
            // the counter, matching `require_authority_epoch_view`'s
            // CHECK-ONLY role for `UpdateFeeSplit`/
            // `UpdateInsuranceWithdrawPolicy`.
            require_protocol_fee_authority_epoch_view(&group, expected_authority_epoch)?;
            let vault_balance = verify_withdrawable_token_accounts(
                dest_token,
                authority.key,
                vault_token,
                &vault_authority,
                &cfg,
                false,
            )?;
            // §1.3/N2 clamp: crank rewards (`credit_account_from_insurance_not_atomic`
            // callers) used to share the same unbudgeted-surplus gap the
            // protocol's claim lives in -- since the RESERVE amendment
            // (~/v17/DECISIONS-LEDGER.md) they are excluded from it via
            // `additional_reserved`, but this clamp is kept as defense in
            // depth: `protocol_fee_accrued_atoms - protocol_fee_withdrawn_atoms`
            // is still a wrapper-side ledger that could in principle race
            // ahead of what's actually on-chain (e.g. multiple markets
            // sharing one mint's accounting quirks), so the transfer is
            // clamped to what's actually available and only the ACTUALLY
            // transferred amount is marked withdrawn (a partial fill),
            // rather than erroring the whole instruction. See
            // `protocol_fee_withdraw_amount`'s doc comment for the pure,
            // Kani-proved core of this bound
            // (`kani_protocol_claim_never_exceeds_accrued`, §5.2).
            let engine_available = group
                .header
                .insurance
                .get()
                .saturating_sub(
                    group
                        .header
                        .source_insurance_credit_reserved_total_atoms
                        .get(),
                )
                .saturating_sub(group.header.insurance_domain_budget_remaining_total.get());
            let (transfer_amount, next_withdrawn) = protocol_fee_withdraw_amount(
                cfg.protocol_fee_accrued_atoms,
                cfg.protocol_fee_withdrawn_atoms,
                amount,
                engine_available,
                group.header.vault.get(),
            )?;
            let transfer_amount_u64 = amount_to_u64(transfer_amount)?;
            require_token_balance(vault_balance, transfer_amount_u64)?;
            group
                .withdraw_insurance_surplus_not_atomic(transfer_amount)
                .map_err(map_v16_error)?;
            cfg.protocol_fee_withdrawn_atoms = next_withdrawn;
            group.validate_shape().map_err(map_v16_error)?;
            (transfer_amount_u64, cfg)
        };
        // Unconditional write-back: every successful call here mutates
        // protocol_fee_withdrawn_atoms, unlike the trade-credit sites' opt-in
        // cfg_after pattern.
        state::write_wrapper_config(&mut market_ai.try_borrow_mut_data()?, &cfg_after)?;
        let bump_arr = [bump];
        let signer_seeds: &[&[&[u8]]] = &[&[b"vault", market_ai.key.as_ref(), &bump_arr]];
        transfer_tokens_signed(
            token_program,
            vault_token,
            dest_token,
            vault_authority_ai,
            transfer_amount_u64,
            signer_seeds,
        )
    }

    /// WithdrawCreatorFee (tag 90, creator-fee-claim design §3). Pays the
    /// creator's accrued trade-fee share out of the vault and debits
    /// `cfg.creator_fee_claimable_atoms` by exactly `amount`.
    ///
    /// Modeled on `handle_withdraw_protocol_fee` (tag 84) — same six accounts,
    /// same derived-vault-authority transfer, same mode gate — with three
    /// deliberate divergences:
    ///
    /// 1. AUTHORITY is asset 0's `asset_admin`, and ONLY that. It bootstraps to
    ///    the asset activator (the creator) at `InitMarket` / activation, and is
    ///    rotated ONLY by its holder via `UpdateAssetAuthority` self-rotation.
    ///    The one path that can rewrite it on an EXISTING slot is the
    ///    re-activation branch of `handle_update_asset_lifecycle` (reachable by
    ///    `marketauth`), which is barred from asset 0 (it rejects the in-service
    ///    lifecycles, `ASSET_ACTION_RETIRE` rejects `asset_index == 0` so asset 0
    ///    can never be RETIRED/re-activated, and an explicit `asset_index == 0`
    ///    guard pins that). So `asset_admin` for asset 0 is stable creator-only.
    ///
    ///    WHY `asset_admin` AND NOT `insurance_operator`: the wizard's full
    ///    create flow runs `StakeInitPool` + `BindInsuranceAuthority`, which
    ///    rotate `marketauth`, `insurance_authority` AND `insurance_operator` to
    ///    program PDAs (the stake pool / vault_auth). Gating this claim on any of
    ///    those makes the creator's own fees UNCLAIMABLE on a staked market — no
    ///    wallet holds a PDA's key. Verified on the live staked market
    ///    `7FBXdrm1…`: `insurance_operator` was a PDA while `asset_admin` was the
    ///    creator's wallet. `asset_admin` is the one creator-facing field the
    ///    stake flow leaves alone. This is also why `verify_domain_withdrawal_
    ///    preflight` is NOT reused: it accepts `cfg.marketauth` as an alternate
    ///    gate, and on a staked market that IS the stake-pool PDA — that path
    ///    would hand the creator's revenue to the pool.
    ///
    /// 2. NO health-check / cooldown, unlike tag 57 `WithdrawInsuranceAsset`.
    ///    Those gates exist because tag 57 draws down the per-domain insurance
    ///    budget, which IS the loss backstop
    ///    (`consume_domain_insurance_for_negative_pnl`). This counter is
    ///    disjoint from that budget by construction — the creator leg no longer
    ///    touches any domain budget — so backstop-health gating has nothing to
    ///    protect here.
    ///
    /// 3. EXACT DEBIT, NO PARTIAL FILL. `amount` must be nonzero and
    ///    `<= creator_fee_claimable_atoms`; over-claims are rejected rather
    ///    than saturated. If the shared unbudgeted surplus is momentarily too
    ///    thin (the protocol/LP/stake legs draw from the same pool),
    ///    `withdraw_insurance_surplus_not_atomic` fails closed with
    ///    `EngineLockActive` and NOTHING is debited — the claim stays fully
    ///    claimable and the creator retries with a smaller amount. Tags 84/87
    ///    clamp-and-partial-fill instead; that is incompatible with an exact
    ///    single-counter debit, and unlike them this leg has no
    ///    `accrued`/`withdrawn` pair that a partial fill could reconcile
    ///    against.
    ///
    /// MODE GATE mirrors tag 84's (Live, or Resolved once fully wound down),
    /// and for the same W12 reason: `ResolveMarket` is one-way and tag 90 is
    /// this counter's ONLY exit, so a Live-only gate would strand every
    /// unclaimed creator atom permanently the instant a market resolves.
    #[inline(never)]
    fn handle_withdraw_creator_fee<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        amount: u128,
        asset_index: u16,
        expected_authority_epoch: u64,
    ) -> ProgramResult {
        let authority = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let dest_token = account(accounts, 2)?;
        let vault_token = account(accounts, 3)?;
        let vault_authority_ai = account(accounts, 4)?;
        let token_program = account(accounts, 5)?;
        expect_signer(authority)?;
        expect_writable(market_ai)?;
        expect_writable(dest_token)?;
        expect_writable(vault_token)?;
        expect_owner(market_ai, program_id)?;
        verify_token_program(token_program)?;

        let (vault_authority, bump) = derive_vault_authority(program_id, market_ai.key);
        expect_key(vault_authority_ai, &vault_authority)?;

        let (transfer_amount_u64, cfg_after) = {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (mut cfg, mut group) = state::market_view_mut(&mut market_data)?;
            let live_mode = group.header.mode == 0;
            let resolved_mode = group.header.mode == 1;
            if !live_mode && !resolved_mode {
                return Err(PercolatorError::EngineLockActive.into());
            }
            if resolved_mode
                && (group.header.materialized_portfolio_count.get() != 0
                    || group.header.c_tot.get() != 0)
            {
                return Err(PercolatorError::EngineLockActive.into());
            }
            // Authority: asset 0's `asset_admin` ONLY. `live_authority_matches`
            // also rejects the all-zero key, so a burned/unconfigured admin can
            // never be claimed against by a zero-key signer.
            //
            // Why `asset_admin` and NOT `insurance_operator`: the wizard's full
            // create flow runs `StakeInitPool` + `BindInsuranceAuthority`, which
            // rotate `marketauth`, `insurance_authority` AND `insurance_operator`
            // to program PDAs (the stake pool / vault_auth). Gating on any of
            // those would make the creator's own fees unclaimable on a staked
            // market -- no wallet holds a PDA's key. Verified on a live staked
            // market (7FBXdrm1…): insurance_operator was a PDA while `asset_admin`
            // remained the creator's wallet. `asset_admin` bootstraps to the
            // asset activator (the creator) and is rotated ONLY by its holder via
            // `UpdateAssetAuthority` -- the stake flow never touches it. It is the
            // one field that reliably tracks the creator through staking, and it
            // already gates other creator ops (e.g. RestartAssetOracle).
            // GH#420: authorise against THIS ASSET's `asset_admin`, not asset 0's.
            //
            // Every asset's creator cut used to accrue into one market-wide counter
            // while this check named asset 0 only, so in a multi-asset market the
            // base deployer could withdraw fees earned on assets 1..N and those
            // assets' creators could never claim their own.
            // Range is enforced by the profile read itself (`read_asset_oracle_profile`
            // bounds `asset_index` against the market's slot capacity), so there is no
            // second bound here. An earlier draft added one against
            // `config.max_market_slots`, which is NOT the same basis and rejected a
            // legitimate asset 1 as InvalidInstruction — one invariant, one owner.
            let mut claim_profile =
                read_oracle_profile_from_view(&group, &cfg, asset_index as usize)?;
            if !live_authority_matches(&claim_profile.asset_admin, authority.key) {
                return Err(PercolatorError::Unauthorized.into());
            }
            // W4-AE-EXTEND: gate-2-class replay protection -- a direct
            // fund-withdrawal instruction, signer-gated on this asset's OWN
            // `asset_admin` with zero prior replay protection (the same
            // class upstream `ade6f9fa` bound for `WithdrawBackingBucket`/
            // `WithdrawBackingBucketEarnings`/`WithdrawInsuranceAsset`,
            // ported by W3A-1). CHECK ONLY, against THIS asset's own epoch
            // lane (not asset-0's) -- `asset_admin` is rotated per-asset via
            // `UpdateAssetAuthority`, so a held tx signed against asset 5's
            // epoch must not be invalidated by an unrelated asset 0 rotation,
            // nor survive one on its own asset.
            require_authority_epoch_view(&group, asset_index as usize, expected_authority_epoch)?;
            let vault_balance = verify_withdrawable_token_accounts(
                dest_token,
                authority.key,
                vault_token,
                &vault_authority,
                &cfg,
                false,
            )?;
            // Exact capacity check, in u128 so an `amount` above u64::MAX is an
            // over-claim (rejected) rather than a `try_from` panic-adjacent
            // edge case. Reject-not-saturate, and reject the no-op zero claim.
            if amount == 0 {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            // A CALLER error (over-ask), not an internal-invariant violation --
            // hence its own ordinal rather than the engine's
            // `EngineCounterUnderflow`, which stays reserved for the
            // fail-closed `checked_sub` below.
            // GH#420: the claimable pot is THIS asset's, plus — for asset 0 only —
            // the pre-existing market-wide counter.
            //
            // Fees accrued BEFORE this change are all sitting in
            // `cfg.creator_fee_claimable_atoms`, and asset 0's admin was the only
            // party who could ever withdraw them. Leaving that balance claimable by
            // asset 0 keeps the historical behaviour exactly as it was for the party
            // who already had it, and strands nothing. Assets 1..N draw only from
            // their own counter, which starts at zero on a deployed market because
            // those bytes were slot padding.
            let legacy_pot = if asset_index == 0 {
                cfg.creator_fee_claimable_atoms
            } else {
                0
            };
            let claimable = (claim_profile.creator_fee_claimable_atoms as u128)
                .checked_add(legacy_pot as u128)
                .ok_or(PercolatorError::EngineArithmeticOverflow)?;
            if amount > claimable {
                return Err(PercolatorError::CreatorFeeOverClaim.into());
            }
            let transfer_amount_u64 = amount_to_u64(amount)?;
            require_token_balance(vault_balance, transfer_amount_u64)?;
            // I-a, V-a: the atoms leave both the insurance fund and the vault.
            // The creator leg was charged into `header.insurance` by the engine
            // and (since the creator-fee-claim change) was never credited to any
            // domain budget, so it is exactly the "unbudgeted surplus" this
            // primitive is bounded by. It hard-errors if another leg got there
            // first, leaving the counter untouched.
            group
                .withdraw_insurance_surplus_not_atomic(amount)
                .map_err(map_v16_error)?;
            // Debit THIS asset's counter first, then the legacy pot for whatever
            // remains. Draining the per-asset counter first means a market that has
            // migrated fully stops touching the legacy value at all, and the legacy
            // balance can only ever shrink.
            //
            // `checked_sub` cannot fail after the clamp above; both are kept so a
            // future edit that weakens the clamp still fails closed rather than
            // wrapping a counter to ~1.8e19 claimable atoms.
            let amount_u64 = amount as u64;
            let from_asset = amount_u64.min(claim_profile.creator_fee_claimable_atoms);
            claim_profile.creator_fee_claimable_atoms = claim_profile
                .creator_fee_claimable_atoms
                .checked_sub(from_asset)
                .ok_or(PercolatorError::EngineCounterUnderflow)?;
            let from_legacy = amount_u64
                .checked_sub(from_asset)
                .ok_or(PercolatorError::EngineCounterUnderflow)?;
            if from_legacy != 0 {
                cfg.creator_fee_claimable_atoms = cfg
                    .creator_fee_claimable_atoms
                    .checked_sub(from_legacy)
                    .ok_or(PercolatorError::EngineCounterUnderflow)?;
            }
            write_oracle_profile_to_view(&mut group, asset_index as usize, &claim_profile)?;
            group.validate_shape().map_err(map_v16_error)?;
            (transfer_amount_u64, cfg)
        };
        // Unconditional write-back, as in `handle_withdraw_protocol_fee`: every
        // successful call here debits `creator_fee_claimable_atoms` (a zero
        // amount errored above). Without it the counter resets and the SAME
        // atoms are claimable again on the next call.
        state::write_wrapper_config(&mut market_ai.try_borrow_mut_data()?, &cfg_after)?;
        let bump_arr = [bump];
        let signer_seeds: &[&[&[u8]]] = &[&[b"vault", market_ai.key.as_ref(), &bump_arr]];
        transfer_tokens_signed(
            token_program,
            vault_token,
            dest_token,
            vault_authority_ai,
            transfer_amount_u64,
            signer_seeds,
        )
    }

    /// SetProtocolFeeAuthority (tag 85, design §3.2). Rotates
    /// `protocol_fee_authority` on a single market. Gated on the program's
    /// BPF upgrade authority -- NOT `marketauth`, NOT any
    /// creator/insurance_authority-facing gate. No global fan-out: a
    /// keeper script iterates markets if a mass rotation is ever needed
    /// (v2 nicety, not a blocker).
    #[inline(never)]
    fn handle_set_protocol_fee_authority<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        new_authority: [u8; 32],
    ) -> ProgramResult {
        let upgrade_authority = account(accounts, 0)?;
        let program_data_ai = account(accounts, 1)?;
        let market_ai = account(accounts, 2)?;
        expect_signer(upgrade_authority)?;
        expect_writable(market_ai)?;
        expect_owner(market_ai, program_id)?;

        let (program_data_key, _) = derive_program_data_address(program_id);
        expect_key(program_data_ai, &program_data_key)?;
        let stored_upgrade_authority = read_program_data_upgrade_authority(program_data_ai)?;
        if stored_upgrade_authority != Some(*upgrade_authority.key) {
            return Err(PercolatorError::Unauthorized.into());
        }

        let (mut cfg, _, _, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        cfg.protocol_fee_authority = new_authority;
        let mut market_data = market_ai.try_borrow_mut_data()?;
        state::write_wrapper_config(&mut market_data, &cfg)?;
        // W4-AE-84: advance the market-wide `protocol_fee_authority_epoch`
        // counter on every successful rotation -- this is the "rotation
        // event" that invalidates any `WithdrawProtocolFee` (tag 84) held
        // and signed against the PRE-rotation epoch, the same relationship
        // `UpdateAuthority` (tag 32) has with the asset-0 `authority_epoch`
        // lane `UpdateFeeSplit`/`UpdateInsuranceWithdrawPolicy` check-only.
        // Unconditional (no CAS input here) -- see
        // `state::bump_protocol_fee_authority_epoch`'s doc comment for why
        // this tag carries no `expected` argument of its own.
        let current_epoch = state::read_protocol_fee_authority_epoch(&market_data)?;
        let next_epoch = state::bump_protocol_fee_authority_epoch(current_epoch)?;
        state::write_protocol_fee_authority_epoch(&mut market_data, next_epoch)
    }

    /// UpdateFeeSplit (tag 86) — marketauth-gated. Validates the shares, then
    /// stores them. Validation lives ONLY here, never in a load-time
    /// validator (see `policy_v16::validate_fee_split`'s doc comment).
    ///
    /// Marketauth-gated idiom mirrors the neighbouring single-field setters
    /// (`handle_update_maintenance_fee_policy`, `handle_update_fee_redirect_policy`,
    /// `handle_update_market_init_fee_policy`): signer/writable/owner checks,
    /// load cfg via `read_market_config_mode_and_capacity`, gate on
    /// `cfg.marketauth` via `expect_live_authority`, mutate, write back.
    /// (`handle_update_trade_fee_policy` gates on asset-0's insurance
    /// authority instead of `marketauth`, so it is not the pattern to mirror
    /// here despite sharing the "policy setter" name.)
    #[inline(never)]
    fn handle_update_fee_split<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        creator_share_bps: u16,
        lp_share_bps: u16,
        insurance_share_bps: u16,
        expected_authority_epoch: u64,
    ) -> ProgramResult {
        let admin = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        expect_signer(admin)?;
        expect_writable(market_ai)?;
        expect_owner(market_ai, program_id)?;
        policy_v16::validate_fee_split(creator_share_bps, lp_share_bps, insurance_share_bps)?;
        let (mut cfg, _, _, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        expect_live_authority(&cfg.marketauth, admin.key)?;
        // W4-AE-EXTEND: gate-2-class replay protection (see `UpdateFeeSplit`'s
        // wire-field doc comment) -- CHECK ONLY against the shared asset-0
        // `authority_epoch` lane, matching the W3A-2 idiom for handlers that
        // hold no `MarketViewMutV16` (no view is in scope here, unlike
        // `handle_update_base_unit_mints`), reading raw control-sequence
        // bytes directly.
        let sequences = state::read_asset_control_sequences(&market_ai.try_borrow_data()?, 0)?;
        state::require_current_authority_epoch(sequences.authority_epoch, expected_authority_epoch)?;
        cfg.creator_share_bps = creator_share_bps;
        cfg.lp_share_bps = lp_share_bps;
        cfg.insurance_share_bps = insurance_share_bps;
        state::write_wrapper_config(&mut market_ai.try_borrow_mut_data()?, &cfg)
    }

    /// Reads and validates a percolator-stake `StakePool` account, returning
    /// its `vault` token-account key and its `vault_authority` PDA.
    ///
    /// EVERY value that decides where tokens land is DERIVED here, never taken
    /// from the caller. The caller supplies account handles; it does not get to
    /// choose what they are allowed to be.
    ///
    /// THE TRUST ROOT is the PINNED `constants::STAKE_PROGRAM_ID`, asserted
    /// against `pool_ai.owner` in step (1) BEFORE any byte of the account is
    /// read. Everything downstream — both PDA derivations and every field read
    /// — is anchored to that constant, never to caller-supplied data.
    ///
    /// SECURITY — the hole this closes, and why the previous mitigation did not.
    /// An earlier version recovered the stake program as `*pool_ai.owner` and
    /// then validated the pool self-consistently against it. Every check
    /// (vault_auth derivation, pool PDA, discriminator, version, slab, wrapper
    /// id, pool_mode, vault) passed — with respect to a program the ATTACKER
    /// chose. The full forgery: deploy program `X`; compute
    /// `pool = PDA(["stake_pool", market], X)` and
    /// `vault_auth = PDA(["vault_auth", pool], X)`; point asset 0's
    /// `insurance_authority` at `vault_auth`; have `X` write a
    /// `STAKE_POOL_LEN`-byte account at `pool` with the right discriminator,
    /// version, `is_initialized`, `slab == market`, `percolator_program == `
    /// this wrapper, `pool_mode == 0`, and `vault == ` a token account owned by
    /// `vault_auth`. Tag 87 then paid out to `X`'s vault. On a market with a
    /// real bound pool the creator could rotate away, crank, and rotate back,
    /// so stakers never even observed the theft.
    ///
    /// The previous mitigation — requiring asset 0's `asset_admin` to be burned
    /// — did NOT close this, and has been REMOVED. `handle_update_asset_authority`
    /// has two branches: the `admin_signed` branch, and self-rotation by the
    /// authority's CURRENT holder (`if !admin_signed { expect_live_authority(
    /// &current_value, current.key)? }`). Burning `asset_admin` kills only the
    /// first. `InitMarket` bootstraps `insurance_authority = cfg.marketauth` =
    /// the creator's own wallet, so AFTER the burn the creator is still the
    /// current holder and simply self-rotates `insurance_authority` to the
    /// forged `vault_auth`. The burn bought zero security and imposed a
    /// bind-then-burn ordering footgun (tag 87 failed closed until an operator
    /// ran a burn that was never actually load-bearing).
    ///
    /// With the owner pinned, `insurance_authority` is only a POINTER, and
    /// rotating it is harmless: to pass step (3) the rotated value must equal
    /// `PDA(["vault_auth", pool], STAKE_PROGRAM_ID)` — a PDA under a program the
    /// attacker does not control and cannot sign for. Forging that would mean
    /// finding a preimage for a chosen 32-byte PDA target, not exploiting a
    /// validation gap. So the creator may rotate `insurance_authority` freely;
    /// the only thing they can do is make tag 87 fail.
    ///
    /// (This sentence said "step (2)" until the branch-review pass. The steps
    /// were renumbered when the burn gate was removed and (0) was inserted, so
    /// it pointed at the zero-check instead of the `vault_auth` PDA equality.
    /// The step numbers below are the authority; keep them in sync with this
    /// paragraph if the sequence changes again.)
    ///
    /// This matters because tag 87 reaches a fund `WithdrawInsurance` (tag 41)
    /// cannot: tag 41 is Resolved-only and budget-scoped
    /// (`terminal_insurance_withdraw_capacity_for_authority_view`), whereas tag
    /// 87 draws the UNBUDGETED Live-mode surplus this handler's clamp isolates.
    /// Left unpinned it was a NEW extraction path that let a creator recapture
    /// the exact insurance leg the fee-split floors exist to guarantee.
    fn load_bound_stake_pool(
        program_id: &Pubkey,
        market_ai: &AccountInfo,
        pool_ai: &AccountInfo,
        bound_insurance_authority: &[u8; 32],
    ) -> Result<(Pubkey, Pubkey), ProgramError> {
        // (0) THE PIN. On a build with no pinned stake program id (i.e. any
        // non-`devnet` build — v17 percolator-stake has no mainnet deployment)
        // there is no program we are willing to send tokens to, so refuse
        // before touching anything. Fail closed: the atoms stay in
        // `header.insurance`. See `constants::STAKE_PROGRAM_ID`.
        #[cfg(not(feature = "devnet"))]
        {
            let _ = (program_id, market_ai, pool_ai, bound_insurance_authority);
            return Err(PercolatorError::StakeProgramNotPinned.into());
        }
        #[cfg(feature = "devnet")]
        {
            let stake_program = crate::constants::STAKE_PROGRAM_ID;
            // (1) OWNER PIN — FIRST, BEFORE ANY BYTE IS READ. This is the check
            // the whole handler rests on. Without it every subsequent test is
            // merely self-consistent with respect to a program the caller
            // chose, and the pool is forgeable end to end (see the SECURITY
            // block). Ordering matters: reading fields out of an account owned
            // by an unknown program and only later asking who owns it would let
            // attacker bytes influence anything that happens in between.
            if *pool_ai.owner != stake_program {
                return Err(PercolatorError::StakePoolOwnerMismatch.into());
            }
            // (2) No bound stake pool ⇒ nobody is owed this leg. NOTE: on a
            // fresh market this is `marketauth`, not zero, so this test is a
            // backstop for an explicitly-zeroed authority rather than the
            // "never bound" check it reads as. The real "never bound"
            // rejection comes from step (3): an unbound `insurance_authority`
            // is a wallet key, which is on-curve and therefore can never equal
            // a derived `vault_auth` PDA.
            if *bound_insurance_authority == [0u8; 32] {
                return Err(PercolatorError::StakePoolNotBound.into());
            }
            // (3) The bound authority must be THIS pool's `vault_auth` under
            // the PINNED program. Because the program is pinned, a creator who
            // rotates `insurance_authority` (which they can still do, via
            // self-rotation — burning `asset_admin` never prevented that) can
            // only point it at something that fails this test. They can break
            // their own payout; they cannot redirect it.
            let (vault_authority, _) = Pubkey::find_program_address(
                &[
                    crate::constants::STAKE_VAULT_AUTHORITY_SEED,
                    pool_ai.key.as_ref(),
                ],
                &stake_program,
            );
            if vault_authority.to_bytes() != *bound_insurance_authority {
                return Err(PercolatorError::StakePoolAuthorityMismatch.into());
            }
            // (4) …and it must be THE pool for THIS market, again derived under
            // the pinned program. One pool per market by construction of the
            // seed, so this is an equality test, not a search.
            let (expected_pool, _) = Pubkey::find_program_address(
                &[crate::constants::STAKE_POOL_SEED, market_ai.key.as_ref()],
                &stake_program,
            );
            expect_key(pool_ai, &expected_pool)?;

            // Only NOW is it safe to read bytes: the account is owned by the
            // pinned stake program, so its contents are that program's state,
            // not attacker-authored data.
            let data = pool_ai.try_borrow_data()?;
            if data.len() < crate::constants::STAKE_POOL_LEN {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            // (5) Discriminator + version + init flag: refuse to parse a stake
            // account of some other kind, or a layout we do not know.
            if data[crate::constants::STAKE_POOL_OFF_DISCRIMINATOR
                ..crate::constants::STAKE_POOL_OFF_DISCRIMINATOR + 8]
                != crate::constants::STAKE_POOL_DISCRIMINATOR
                || data[crate::constants::STAKE_POOL_OFF_VERSION]
                    != crate::constants::STAKE_POOL_VERSION
                || data[crate::constants::STAKE_POOL_OFF_IS_INITIALIZED] != 1
            {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            // (6) The pool's own record of its bindings must agree with ours.
            // Redundant with (4) for `slab` — kept because it costs nothing and
            // makes a future seed change fail closed instead of silently
            // redirecting funds.
            let mut slab = [0u8; 32];
            slab.copy_from_slice(
                &data[crate::constants::STAKE_POOL_OFF_SLAB
                    ..crate::constants::STAKE_POOL_OFF_SLAB + 32],
            );
            if slab != market_ai.key.to_bytes() {
                return Err(PercolatorError::StakePoolMarketMismatch.into());
            }
            // (7) The pool must CPI *this* wrapper deployment. A pool bound to a
            // different wrapper program is not this market's staker constituency.
            let mut cpi_target = [0u8; 32];
            cpi_target.copy_from_slice(
                &data[crate::constants::STAKE_POOL_OFF_PERCOLATOR_PROGRAM
                    ..crate::constants::STAKE_POOL_OFF_PERCOLATOR_PROGRAM + 32],
            );
            if cpi_target != program_id.to_bytes() {
                return Err(PercolatorError::StakePoolWrapperMismatch.into());
            }
            // (8) Insurance-LP mode only. That is the mode whose stakers absorb
            // this market's losses via `FlushToInsurance`; this fee leg is their
            // compensation for exactly that exposure. Paying it to a pool that
            // carries no such exposure would be an unearned transfer.
            if data[crate::constants::STAKE_POOL_OFF_MODE]
                != crate::constants::STAKE_POOL_MODE_INSURANCE_LP
            {
                return Err(PercolatorError::StakePoolModeMismatch.into());
            }
            // (9) The destination, read out of the validated pool.
            let mut vault = [0u8; 32];
            vault.copy_from_slice(
                &data[crate::constants::STAKE_POOL_OFF_VAULT
                    ..crate::constants::STAKE_POOL_OFF_VAULT + 32],
            );
            // `vault_authority` was proven equal to the bound
            // `insurance_authority` in (3); returning it lets the caller assert
            // the destination token account's SPL owner is that same PDA.
            Ok((Pubkey::new_from_array(vault), vault_authority))
        }
    }

    /// WithdrawInsuranceReserveToStake (tag 87) — permissionless.
    ///
    /// Transfers `insurance_reserve_accrued - insurance_reserve_withdrawn` out
    /// of the market vault and into the bound stake pool's vault, where
    /// percolator-stake's `AccrueFees` measures it as surplus over
    /// `total_pool_value()` and distributes it to stakers. Stakers absorb this
    /// market's losses via `FlushToInsurance`; this leg is their compensation.
    ///
    /// PERMISSIONLESS, SAFELY. The destination is not an argument and is not
    /// caller-chosen: it is `pool.vault` read out of the pool at
    /// `["stake_pool", market]` under the pinned stake program id (see
    /// `load_bound_stake_pool`). Every candidate destination a caller could
    /// substitute fails one of those checks, so there is nothing to redirect —
    /// the only thing a caller decides is *when* the push happens.
    ///
    /// MODE GATE — Live-only, matching tag 78 (the other permissionless leg)
    /// and deliberately STRICTER than `handle_withdraw_protocol_fee`'s
    /// Live-or-wound-down-Resolved gate (its `live_mode` / `resolved_mode`
    /// block).
    ///
    /// Why not the protocol-fee model. Tag 84 may run in Resolved because it is
    /// signer-gated on `protocol_fee_authority` AND because W12 applies to it:
    /// ResolveMarket is one-way, so a Live-only gate there would strand the
    /// protocol's backlog forever, as tag 84 is its ONLY exit. The first premise
    /// does not hold here — this instruction carries no authority signature at
    /// all, only `expect_signer` on an arbitrary fee payer, so allowing it in a
    /// terminal state hands a permissionless drain to anyone.
    ///
    /// ⚠ THE SECOND PREMISE DOES APPLY, AND THIS LEG IS FORFEITED BY IT. An
    /// earlier version of this comment claimed refusing on Resolved "strands
    /// nothing" because the reserve stays reclaimable by the stake program via
    /// `WithdrawInsurance` (tag 41), on the grounds that a bound
    /// `insurance_authority` IS the pool's `vault_auth` PDA. THAT IS WRONG: tag
    /// 41's capacity is budget-scoped
    /// (`terminal_insurance_withdraw_capacity_for_authority_view`), while the
    /// atoms this leg pays out are the UNBUDGETED surplus that the clamp below
    /// deliberately isolates. Tag 41 cannot reach them. `ResolveMarket` being
    /// one-way, any `insurance_reserve_accrued - withdrawn` that has not been
    /// pushed before the market resolves is PERMANENTLY UNREACHABLE by stakers.
    ///
    /// That is a real, accepted cost, not a non-issue. It is accepted because
    /// the alternative — a permissionless token-moving instruction that still
    /// runs after resolution — is worse (see the Recovery note below), and
    /// because the leg is continuously crankable by anyone for the entire Live
    /// lifetime of the market, so the forfeited amount is bounded by whatever
    /// accrues between the last successful crank and resolution. Keepers should
    /// crank tag 87 before `ResolveMarket`, not after.
    ///
    /// Concretely blocked:
    ///   * Recovery (mode 2) — the important one, and worse here than for tag
    ///     78. Post-solvency-event, `header.insurance` IS the recovery buffer,
    ///     and stakers are precisely the party contractually meant to be
    ///     FUNDING it (`FlushToInsurance` pushes stake INTO insurance). Letting
    ///     any signer run the pump backwards during a shortfall would drain the
    ///     buffer covering the loss into the pockets of the constituency whose
    ///     job is to cover it. Tag 78 at least leaves the atoms inside the
    ///     market as a junior LP claim; here they leave the program entirely as
    ///     SPL tokens and stakers can withdraw them.
    ///   * Resolved (mode 1) — same drain, before trader portfolios are
    ///     materialised. Note this is the FORFEITING case described above: there
    ///     is no tag-41 fallback for the unbudgeted leg.
    ///   * Live-but-matured — `reject_permissionless_resolve_matured_live_view`,
    ///     as tag 78 uses: no permissionless token movement out of a market
    ///     that is past its stale-resolve horizon and merely awaiting a
    ///     resolve.
    ///
    /// A rejected call never marks anything withdrawn, so `accrued - withdrawn`
    /// stays fully claimable IF the market can return to Live — true for the
    /// matured-Live and Recovery cases, and NOT true for Resolved, which is
    /// terminal and therefore forfeits the outstanding leg as described above.
    ///
    /// MANDATORY CLAMP. The protocol leg (tag 84), the LP leg (tag 78) and this
    /// stake leg ALL draw from one pool: `insurance −
    /// source_insurance_credit_reserved_total_atoms −
    /// insurance_domain_budget_remaining_total`. Nothing checks that the three
    /// wrapper-side counters sum within it, so whichever leg cranks last would
    /// get `EngineLockActive` out of the engine unless each clamps its own
    /// claim first. Mirrors `handle_withdraw_protocol_fee`'s `§1.3/N2 clamp`,
    /// then advances `insurance_reserve_withdrawn_atoms` by the amount
    /// ACTUALLY TRANSFERRED — never the pre-clamp capacity — so a partial fill
    /// leaves the remainder claimable next call instead of marking it paid
    /// without paying it.
    ///
    /// NO RESERVATION. `insurance_reserve_accrued - withdrawn` is deliberately
    /// NOT added to `additional_reserved` at the
    /// `credit_account_from_insurance_not_atomic` call sites. That was tried
    /// for the LP leg and reverted (`9a6502ae`): it makes fee claims senior to
    /// bad-debt/socialized-loss coverage, contradicting the decision that these
    /// claims are at-risk, and it reverts the whole `SyncMaintenanceFee` on
    /// distressed markets. The clamp above is what keeps this leg honest.
    #[inline(never)]
    fn handle_withdraw_insurance_reserve_to_stake<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
    ) -> ProgramResult {
        let cranker = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let stake_pool_ai = account(accounts, 2)?;
        let stake_vault_ai = account(accounts, 3)?;
        let vault_token = account(accounts, 4)?;
        let vault_authority_ai = account(accounts, 5)?;
        let token_program = account(accounts, 6)?;
        expect_signer(cranker)?;
        expect_writable(market_ai)?;
        expect_writable(stake_vault_ai)?;
        expect_writable(vault_token)?;
        expect_owner(market_ai, program_id)?;
        verify_token_program(token_program)?;

        let (vault_authority, bump) = derive_vault_authority(program_id, market_ai.key);
        expect_key(vault_authority_ai, &vault_authority)?;

        let (transfer_amount_u64, cfg_after) = {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (mut cfg, mut group) = state::market_view_mut(&mut market_data)?;
            // MODE GATE — see the doc comment. Live-only, plus matured-Live.
            if group.header.mode != 0 {
                return Err(PercolatorError::EngineLockActive.into());
            }
            reject_permissionless_resolve_matured_live_view(&cfg, &group)?;

            // Destination: derived, never caller-chosen. The trust root is the
            // PINNED `constants::STAKE_PROGRAM_ID`, asserted against
            // `stake_pool_ai.owner` before any byte of that account is read.
            // Asset 0's bound `insurance_authority` — the stake pool's
            // `vault_auth` PDA, as recorded by `BindInsuranceAuthority` — then
            // only has to MATCH the PDA re-derived under that pinned program,
            // so it is a pointer we verify rather than a value we trust. A
            // creator can still rotate it (self-rotation is always available;
            // burning `asset_admin` never prevented that), but rotating it can
            // only make this fail, never redirect it. `pool_vault` then comes
            // out of the validated pool's own bytes, so the account the caller
            // passed at index 3 must BE that account or we stop here.
            let asset0_profile = read_oracle_profile_from_view(&group, &cfg, 0)?;
            let (pool_vault, stake_vault_authority) = load_bound_stake_pool(
                program_id,
                market_ai,
                stake_pool_ai,
                &asset0_profile.insurance_authority,
            )?;
            expect_key(stake_vault_ai, &pool_vault)?;
            // Mint/owner/state/canonical-ATA checks on both sides. The dest
            // owner is asserted to be the stake pool's `vault_auth` PDA, so a
            // token account that merely happens to sit at `pool.vault` while
            // being owned by someone else is rejected too.
            // W5: this payout is permissionless, so `require_unencumbered_dest=true`
            // additionally rejects a poisoned destination (delegate / close_authority)
            // that could be used as a sweep hook.
            let vault_balance = verify_withdrawable_token_accounts(
                stake_vault_ai,
                &stake_vault_authority,
                vault_token,
                &vault_authority,
                &cfg,
                true,
            )?;

            // Claim capacity. Monotonic invariant
            // `insurance_reserve_withdrawn_atoms <= insurance_reserve_accrued_atoms`
            // holds always, so this can only underflow on a corrupt config,
            // which fails closed.
            let claim_capacity = cfg
                .insurance_reserve_accrued_atoms
                .checked_sub(cfg.insurance_reserve_withdrawn_atoms)
                .ok_or(PercolatorError::EngineCounterUnderflow)?;
            // MANDATORY CLAMP — mirrors `handle_withdraw_protocol_fee`'s
            // `§1.3/N2 clamp` verbatim. `.min(vault)` mirrors
            // `protocol_fee_withdraw_amount`'s
            // second bound: `withdraw_insurance_surplus_delta` rejects
            // `amount > vault` too.
            let engine_available = group
                .header
                .insurance
                .get()
                .saturating_sub(
                    group
                        .header
                        .source_insurance_credit_reserved_total_atoms
                        .get(),
                )
                .saturating_sub(group.header.insurance_domain_budget_remaining_total.get());
            let transfer_amount = claim_capacity
                .min(engine_available)
                .min(group.header.vault.get());
            // Zero case: nothing accrued, or the shared surplus pool is dry
            // because another leg got there first. Same error either way — the
            // claim is NOT marked withdrawn, so it stays fully claimable.
            if transfer_amount == 0 {
                return Err(PercolatorError::NoInsuranceReserveToClaim.into());
            }
            let transfer_amount_u64 = amount_to_u64(transfer_amount)?;
            require_token_balance(vault_balance, transfer_amount_u64)?;
            // I−a, V−a: the atoms leave both the insurance fund and the vault,
            // because unlike tag 78 they really do leave the program.
            group
                .withdraw_insurance_surplus_not_atomic(transfer_amount)
                .map_err(map_v16_error)?;
            // Advance by the TRANSFERRED amount, never `claim_capacity`.
            cfg.insurance_reserve_withdrawn_atoms = cfg
                .insurance_reserve_withdrawn_atoms
                .checked_add(transfer_amount)
                .ok_or(PercolatorError::EngineArithmeticOverflow)?;
            group.validate_shape().map_err(map_v16_error)?;
            (transfer_amount_u64, cfg)
        };
        // Unconditional write-back, as in `handle_withdraw_protocol_fee`: every
        // successful call here mutates `insurance_reserve_withdrawn_atoms` (a
        // zero-transfer call returned Err above). Without it the counter resets
        // and the SAME atoms are transferred again on the next call.
        state::write_wrapper_config(&mut market_ai.try_borrow_mut_data()?, &cfg_after)?;
        let bump_arr = [bump];
        let signer_seeds: &[&[&[u8]]] = &[&[b"vault", market_ai.key.as_ref(), &bump_arr]];
        transfer_tokens_signed(
            token_program,
            vault_token,
            stake_vault_ai,
            vault_authority_ai,
            transfer_amount_u64,
            signer_seeds,
        )
    }

    /// ADOPT upstream `547847ed`'s base mechanism (ported near-verbatim; ~15
    /// lines): decode the persisted cursor into a scan-start asset index. `0`
    /// (fresh/never-scanned) always means "start of scan" regardless of
    /// `configured_assets`.
    fn terminal_slab_scan_start(
        encoded: u128,
        configured_assets: usize,
    ) -> Result<usize, ProgramError> {
        if encoded == 0 {
            return Ok(0);
        }
        let next_asset = usize::try_from(
            u64::try_from(encoded).map_err(|_| PercolatorError::InvalidInstruction)?,
        )
        .map_err(|_| PercolatorError::InvalidInstruction)?;
        if next_asset >= configured_assets {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        Ok(next_asset)
    }

    /// ADOPT upstream `547847ed`'s base mechanism (ported near-verbatim): encode
    /// a scan continuation index for persistence in
    /// `AssetOracleProfileV16::terminal_slab_scan_progress`.
    fn encode_terminal_slab_scan_progress(
        next_asset_index: usize,
        configured_assets: usize,
    ) -> Result<u128, ProgramError> {
        if next_asset_index >= configured_assets {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        let next_asset =
            u64::try_from(next_asset_index).map_err(|_| PercolatorError::InvalidInstruction)?;
        Ok(u128::from(next_asset))
    }

    #[inline(never)]
    fn handle_close_slab<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        expected_authority_epoch: u64,
    ) -> ProgramResult {
        let admin_dest = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let vault_token = account(accounts, 2)?;
        let vault_authority_ai = account(accounts, 3)?;
        let dest_token = account(accounts, 4)?;
        let token_program = account(accounts, 5)?;
        expect_signer(admin_dest)?;
        expect_writable(admin_dest)?;
        expect_writable(market_ai)?;
        expect_writable(vault_token)?;
        // ADOPT upstream `547847ed` context (base windowed-scan handler): burning
        // unbudgeted residue below requires `dest_token` to also receive the
        // ordinary sweep amount, so it must be writable too -- our pre-port
        // handler never wrote to it, only read it for the mint/owner check.
        expect_writable(dest_token)?;
        if admin_dest.key == market_ai.key {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        expect_owner(market_ai, program_id)?;
        verify_token_program(token_program)?;

        let (vault_authority, bump) = derive_vault_authority(program_id, market_ai.key);
        expect_key(vault_authority_ai, &vault_authority)?;

        // ADOPT-WITH-ADAPTATION upstream `547847ed` "invalidate terminal scan
        // prefix after backing expiry" (+ neighbour test `d134c64d`): replaces the
        // old unconditional "vault and insurance must already be zero" precondition
        // with upstream's permissionless WINDOWED terminal-slab scan. This
        // activates the engine's `advance_terminal_slab_not_atomic` (already
        // carrying our I2/K fix, PR #258, previously dormant because nothing
        // called it) and its recredit/expiry bookkeeping.
        //
        // W3A-1 (this unit, upstream `238436c5`): ADOPTS the `expected_authority_epoch`
        // parameter / `require_authority_epoch_view` call this tag previously deferred
        // (Track-B AE binding, ABI_OVERHAUL_SCOPE.md §1) -- see the CAS call site below,
        // right after the `expect_live_authority` check it binds. `CloseSlab` no longer
        // keeps a bare, payload-free wire shape; tag 13 now carries a trailing
        // `authority_epoch: u64`, logically orthogonal to the windowed-scan mechanism
        // this unit's own port activated (unaffected by this change).
        //
        // ADOPTED (Wave-3 W3C-residue): upstream `236b4f85` "retire native booked
        // residue without burn" -- the follow-up fix for markets whose primary
        // collateral is wrapped SOL, which can't be `burn`ed. See the
        // `native_residue_authority` computation below (inside the scan scope)
        // and its dispatch at the retirement call site.
        //
        // OPTION-(B) SCOPE GATE (this unit, NOT upstream): preserves the existing
        // "CloseSlab permanently blocked by the LP-vault dead-share floor"
        // guarantee that `tests/v16_fork_lp_vault_redeem.rs`'s
        // `lp_shares_held_at_resolution_can_redeem_and_teardown_vault` and
        // `lpvault359_redemption_stub_tracked_and_teardown_completes` assert by
        // design (LP_VAULT_MINIMUM_LIQUIDITY dead-share floor -- Uniswap-V2 /
        // ERC4626 style permanent minimum-liquidity trade-off).
        //
        // REJECTED FIRST DRAFT (recorded for the next reader): gating on
        // `source_fresh_backing_total_num != 0` alone is WRONG -- it is also
        // nonzero for an ORDINARY market with a live, not-yet-lapsed backing
        // bucket, and a bare pre-scan check on it would block the scan from ever
        // running the `Expire` step that is the ONLY thing that can bring that
        // counter back to zero. That would brick the general (non-LP-vault) case
        // this unit is supposed to activate, not just the LP-vault one.
        //
        // THE ACTUAL SIGNAL: an LP-vault-owned backing bucket is created with
        // `constants::LP_VAULT_BACKING_EXPIRY_SLOT` (`u64::MAX / 2`) as its
        // `expiry_slot` -- a sentinel meaning "never expires", already relied on
        // elsewhere in this file (`handle_deposit_to_lp_vault`'s already-funded
        // guard) to recognize an LP-vault-bound domain. Confirmed empirically
        // (diagnostic run against `lp_shares_held_at_resolution_can_redeem_and_
        // teardown_vault`'s market state): its dead-share-floor domain sits at
        // `status: Fresh, expiry_slot: 9223372036854775807 (== u64::MAX / 2)`,
        // which can NEVER satisfy `kernel_terminal_slab_asset_step`'s
        // `long_expiry_slot <= authenticated_slot` `Expire` condition for any
        // slot this chain will ever reach -- so the scan can only ever return
        // `Wait` / `ScanProgress` for it, not `BackingExpired`, and
        // `source_fresh_backing_total_num` for that domain can never reach zero
        // by any path (the LP-vault registry PDA also cannot sign a generic
        // `WithdrawBackingBucket` outside the vault's own instruction-scoped
        // `invoke_signed` calls). A market carrying such a domain must therefore
        // stay blocked UNCONDITIONALLY, on every call, not just once parked --
        // which a bare `source_fresh_backing_total_num` check does not achieve
        // either (the observed failure was the scan returning `Ok`/`ScanProgress`
        // on the very first call, before the cursor ever parks).
        //
        // This is a narrow, same-sentinel mirror of the existing
        // `handle_deposit_to_lp_vault` already-funded guard, not a new concept:
        // scan every domain for "funded AND stamped with the permanent LP-vault
        // sentinel", and refuse outright if any is found. An ordinary market
        // never sets this sentinel, so this never fires for -- and never blocks
        // scan progress on -- the general non-LP-vault case.
        let lp_vault_dead_share_floor_present = {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (_, group) = state::market_view_mut(&mut market_data)?;
            let configured_domains =
                v16_domain_count_for_market_slots(group.header.config.max_market_slots.get())
                    .map_err(map_v16_error)?;
            let mut found = false;
            for domain in 0..configured_domains {
                let (_, bucket) = backing_domain_parts_view(&group, domain)?;
                let funded = bucket.status != BackingBucketStatusV16::Empty
                    || bucket.fresh_unliened_backing_num > 0
                    || bucket.valid_liened_backing_num > 0
                    || bucket.consumed_liened_backing_num > 0
                    || bucket.impaired_liened_backing_num > 0;
                if funded && bucket.expiry_slot == crate::constants::LP_VAULT_BACKING_EXPIRY_SLOT {
                    found = true;
                    break;
                }
            }
            found
        };
        if lp_vault_dead_share_floor_present {
            return Err(PercolatorError::EngineLockActive.into());
        }

        let (
            cfg_pre,
            retired_unbudgeted_insurance,
            vault_balance,
            secondary_close,
            native_residue_authority,
        ) = {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (cfg, mut group) = state::market_view_mut(&mut market_data)?;
            expect_live_authority(&cfg.marketauth, admin_dest.key)?;
            // W3A-1: strictly precedes every mutation below (the mode check, the
            // scan, and the fund sweep) -- matches upstream `238436c5`'s position,
            // right after the authority check it binds. CHECK-ONLY (asset-0's
            // `authority_epoch` is not advanced here): CloseSlab is terminal --
            // once it succeeds the market's own reserve invariant guards the rest
            // of teardown, so there is no future rotation on THIS market left to
            // protect against a still-held stale intent.
            require_authority_epoch_view(&group, 0, expected_authority_epoch)?;
            if group.header.mode != 1 {
                return Err(PercolatorError::EngineLockActive.into());
            }
            if group.header.c_tot.get() != 0 || group.header.materialized_portfolio_count.get() != 0
            {
                return Err(PercolatorError::EngineLockActive.into());
            }
            let primary_mint = primary_collateral_mint(&cfg);
            let vault_balance =
                verify_vault_token_account(vault_token, &vault_authority, &primary_mint)?;
            verify_user_token_account(dest_token, admin_dest.key, &primary_mint)?;
            let secondary_close = if cfg.secondary_collateral_mint != [0u8; 32] {
                let secondary_vault_token = account(accounts, 6)?;
                let secondary_dest_token = account(accounts, 7)?;
                expect_writable(secondary_vault_token)?;
                expect_writable(secondary_dest_token)?;
                if secondary_vault_token.key == vault_token.key
                    || secondary_dest_token.key == dest_token.key
                {
                    return Err(PercolatorError::InvalidVaultAccount.into());
                }
                let secondary_mint = secondary_collateral_mint(&cfg)?;
                let secondary_vault_balance = verify_vault_token_account(
                    secondary_vault_token,
                    &vault_authority,
                    &secondary_mint,
                )?;
                verify_user_token_account(secondary_dest_token, admin_dest.key, &secondary_mint)?;
                Some((
                    secondary_vault_token,
                    secondary_dest_token,
                    secondary_vault_balance,
                ))
            } else {
                None
            };

            // Cursor storage: carved into asset-0's `AssetOracleProfileV16` spare
            // tail (`terminal_slab_scan_progress`), NOT `WrapperConfigV16` --
            // upstream's offset-160 field collides byte-exact with our LIVE
            // `insurance_withdraw_deposit_remaining` (KL-FIELD-01). Writing via
            // `write_oracle_profile_to_view` mutates `group`'s own backing bytes
            // directly (zero-copy), so no separate `write_wrapper_config` call is
            // needed the way upstream's cfg-based cursor requires.
            let authenticated_slot = authenticated_market_slot_or_fallback_view(&group);
            let configured_assets = group.header.config.max_market_slots.get() as usize;
            let mut cursor_profile = read_oracle_profile_from_view(&group, &cfg, 0)?;
            let scan_start = terminal_slab_scan_start(
                cursor_profile.terminal_slab_scan_progress,
                configured_assets,
            )?;
            // FORK-only engine 3rd parameter (`35ac35c4`/`0efa8f22`, "terminal
            // retirement fails closed on a protocol-fee reserve" -- absent
            // upstream, whose call site takes only 2 args). Pass 0: this wrapper
            // does not reserve a protocol fee out of terminal retirement, so this
            // is upstream-equivalent behavior (see the engine's own doc comment
            // on `advance_terminal_slab_not_atomic`: "Pass `0` for upstream
            // behavior").
            let retired = match group
                .advance_terminal_slab_not_atomic(authenticated_slot, scan_start, 0)
                .map_err(map_v16_error)?
            {
                TerminalSlabOutcomeV16::ScanProgress { next_asset_index } => {
                    cursor_profile.terminal_slab_scan_progress =
                        encode_terminal_slab_scan_progress(next_asset_index, configured_assets)?;
                    write_oracle_profile_to_view(&mut group, 0, &cursor_profile)?;
                    return Ok(());
                }
                TerminalSlabOutcomeV16::BackingExpired { .. } => {
                    // ADOPT upstream `547847ed`: reset to 0 (full rescan) rather
                    // than resuming at `domain / 2`. Expiring a backing bucket can
                    // retroactively make a LOWER-indexed, already-scanned-past
                    // asset newly recreditable; resuming above it would silently
                    // skip it forever. Covered by `d134c64d`'s
                    // `inv_070_terminal_scan_recredit` test (ported below as
                    // `terminal_scan_prefix_invalidated_after_backing_expiry`).
                    cursor_profile.terminal_slab_scan_progress = 0;
                    write_oracle_profile_to_view(&mut group, 0, &cursor_profile)?;
                    return Ok(());
                }
                TerminalSlabOutcomeV16::InsuranceRecredited { asset_index, .. } => {
                    cursor_profile.terminal_slab_scan_progress =
                        encode_terminal_slab_scan_progress(asset_index, configured_assets)?;
                    write_oracle_profile_to_view(&mut group, 0, &cursor_profile)?;
                    return Ok(());
                }
                TerminalSlabOutcomeV16::ReadyToClose { retired } => retired,
            };
            cursor_profile.terminal_slab_scan_progress = 0;
            write_oracle_profile_to_view(&mut group, 0, &cursor_profile)?;
            // ADOPT upstream `236b4f85` "retire native booked residue without burn"
            // (Wave-3 W3C-residue, completing the `NOT ported` gap this fork's
            // 547847ed/d134c64d port (Wave-1 S1a) left flagged below the account
            // list at the top of this function). Native SPL tokens (wrapped SOL,
            // `spl_token::native_mint::id()`) CANNOT be burned -- the real
            // spl-token program's `process_burn` unconditionally rejects a
            // native source account with `TokenError::NativeNotSupported`
            // (Custom(10)). A market whose primary collateral is the native
            // mint that ever accumulates unbudgeted terminal residue would
            // permanently fail this CPI, bricking `CloseSlab` for that market
            // forever (no other code path clears `retired_unbudgeted_insurance`
            // once the scan reaches `ReadyToClose`). Mirrors upstream exactly:
            // decide HERE, while `group`/`cfg` are still in scope, whether the
            // retirement below must escheat via transfer instead of burn.
            let native_residue_authority = if retired != 0
                && primary_mint == spl_token::native_mint::id()
            {
                Some(domain_authorities_from_view(&group, &cfg, 0)?.insurance_authority)
            } else {
                None
            };
            (cfg, retired, vault_balance, secondary_close, native_residue_authority)
        };

        let primary_mint = primary_collateral_mint(&cfg_pre);
        let retired_u64 = amount_to_u64(retired_unbudgeted_insurance)?;
        let primary_sweep_amount = vault_balance
            .checked_sub(retired_u64)
            .ok_or(PercolatorError::InvalidTokenAccount)?;
        let bump_arr = [bump];
        let signer_seeds: &[&[&[u8]]] = &[&[b"vault", market_ai.key.as_ref(), &bump_arr]];
        if retired_u64 != 0 {
            let primary_mint_index = if secondary_close.is_some() { 8 } else { 6 };
            let primary_mint_ai = account(accounts, primary_mint_index)?;
            expect_writable(primary_mint_ai)?;
            expect_key(primary_mint_ai, &primary_mint)?;
            verify_mint(primary_mint_ai)?;
            if let Some(authority) = native_residue_authority {
                // Native tokens cannot be burned (spl-token's `process_burn`
                // unconditionally rejects a native source with
                // `TokenError::NativeNotSupported`). Claim-free booked residue
                // instead escheats to the canonical asset-0 insurance
                // authority's unencumbered ATA, without that role signing --
                // upstream `236b4f85`'s fix, ported verbatim in mechanism.
                let authority = Pubkey::new_from_array(authority);
                let residue_dest = account(accounts, primary_mint_index + 1)?;
                expect_writable(residue_dest)?;
                if *residue_dest.key != canonical_vault_address(&authority, &primary_mint) {
                    return Err(PercolatorError::InvalidTokenAccount.into());
                }
                // sync(W4-TOKEN22): `verify_withdrawable_token_accounts` is now the
                // shared 6-arg / `Result<u64, _>` form (adopted upstream cb1dfd43) --
                // this call site has caught up too, so the standalone
                // `verify_permissionless_payout_dest_token_account` call this
                // "ADAPTATION" note used to fall back to is gone; the escheat is
                // unconditionally permissionless (no signature from `authority`),
                // so `require_unencumbered_dest` is unconditionally `true`, matching
                // the other permissionless payout call sites.
                verify_withdrawable_token_accounts(
                    residue_dest,
                    &authority,
                    vault_token,
                    vault_authority_ai.key,
                    &cfg_pre,
                    true,
                )?;
                transfer_tokens_signed(
                    token_program,
                    vault_token,
                    residue_dest,
                    vault_authority_ai,
                    retired_u64,
                    signer_seeds,
                )?;
            } else {
                burn_tokens_signed(
                    token_program,
                    vault_token,
                    primary_mint_ai,
                    vault_authority_ai,
                    retired_u64,
                    signer_seeds,
                )?;
            }
        }
        if primary_sweep_amount > 0 {
            transfer_tokens_signed(
                token_program,
                vault_token,
                dest_token,
                vault_authority_ai,
                primary_sweep_amount,
                signer_seeds,
            )?;
        }
        let close_ix = spl_token::instruction::close_account(
            token_program.key,
            vault_token.key,
            admin_dest.key,
            vault_authority_ai.key,
            &[],
        )?;
        invoke_signed(
            &close_ix,
            &[
                vault_token.clone(),
                admin_dest.clone(),
                vault_authority_ai.clone(),
                token_program.clone(),
            ],
            signer_seeds,
        )?;

        if let Some((secondary_vault_token, secondary_dest_token, secondary_amount)) =
            secondary_close
        {
            if secondary_amount > 0 {
                transfer_tokens_signed(
                    token_program,
                    secondary_vault_token,
                    secondary_dest_token,
                    vault_authority_ai,
                    secondary_amount,
                    signer_seeds,
                )?;
            }
            let close_secondary_ix = spl_token::instruction::close_account(
                token_program.key,
                secondary_vault_token.key,
                admin_dest.key,
                vault_authority_ai.key,
                &[],
            )?;
            invoke_signed(
                &close_secondary_ix,
                &[
                    secondary_vault_token.clone(),
                    admin_dest.clone(),
                    vault_authority_ai.clone(),
                    token_program.clone(),
                ],
                signer_seeds,
            )?;
        }

        // ADOPT upstream `d57411f8` (sync unit W2-S1b, "prevent whole-market
        // address reuse"). PRE-PORT (and still upstream's OWN pre-fix)
        // behavior: zero every byte in place, then drain the account to 0
        // lamports. On real Solana, a 0-lamport account is not immediately
        // deleted, but it IS eligible to be swept by the runtime between
        // transactions/epochs, which frees the pubkey for an entirely
        // UNRELATED account -- possibly with a different owner, opened by
        // anyone who can sign for (or derive) that address. Any code or
        // off-chain reference that trusted "this pubkey == this market"
        // (rather than a persistent, program-assigned identity) would then
        // silently bind to whatever gets created there next: the classic ABA
        // address-reuse hole the upstream commit message names directly.
        //
        // FIX: shrink to `HEADER_LEN`, stamp a permanent `KIND_CLOSED_MARKET`
        // tombstone, and retain only the lamports needed to keep THAT shrunk
        // size rent-exempt forever -- never draining to 0. `is_initialized`
        // (checked by `init_market_account_zero_copy`, reordered above to
        // check first) sees the tombstone's `MAGIC`/`VERSION` bytes and
        // permanently refuses reinitialization at this exact pubkey. The
        // account is inert (16 bytes, `KIND_CLOSED_MARKET`, unreachable by
        // every other KIND_* accessor via `check_header`'s kind check) but
        // never eligible for reclaim, so the address itself can never be
        // reused for a different market.
        market_ai.realloc(constants::HEADER_LEN, false)?;
        state::write_closed_market_tombstone(&mut market_ai.try_borrow_mut_data()?)?;
        let market_lamports = market_ai.lamports();
        let refunded_lamports = market_lamports
            .checked_sub(constants::CLOSED_MARKET_TOMBSTONE_RENT_LAMPORTS)
            .ok_or(PercolatorError::RentExemptRequired)?;
        **market_ai.lamports.borrow_mut() = constants::CLOSED_MARKET_TOMBSTONE_RENT_LAMPORTS;
        **admin_dest.lamports.borrow_mut() = admin_dest
            .lamports()
            .checked_add(refunded_lamports)
            .ok_or(PercolatorError::EngineArithmeticOverflow)?;
        Ok(())
    }

    #[inline(never)]
    fn handle_convert_released_pnl<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        expected_portfolio_id: u64,
        expected_position_epoch: u64,
        amount: u128,
    ) -> ProgramResult {
        if amount == 0 {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        with_one_portfolio_view(
            program_id,
            accounts,
            true,
            Some((expected_portfolio_id, expected_position_epoch)),
            |group, portfolio, cfg| {
            if group.header.mode != 0 {
                return Err(V16Error::LockActive);
            }
            if permissionless_resolve_matured_now_view(cfg, group) {
                return Err(V16Error::LockActive);
            }
            // The v16 engine converts the currently released residual-bounded
            // amount atomically. Preserve the wrapper caller cap by staging the
            // conversion and only committing it when the converted amount fits.
            let converted = group.convert_released_pnl_to_capital_not_atomic(portfolio)?;
            if converted == 0 || converted > amount {
                return Err(V16Error::LockActive);
            }
            Ok(())
        })
    }

    #[inline(never)]
    fn handle_cure_and_cancel_close<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        expected_portfolio_id: u64,
        expected_position_epoch: u64,
        optional_deposit: u128,
    ) -> ProgramResult {
        let owner = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let portfolio_ai = account(accounts, 2)?;
        expect_signer(owner)?;
        expect_writable(market_ai)?;
        expect_writable(portfolio_ai)?;
        expect_owner(market_ai, program_id)?;
        expect_owner(portfolio_ai, program_id)?;

        let (_, _, max_market_slots, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        ensure_portfolio_storage_for_market_slots(portfolio_ai, max_market_slots)?;
        // TB-1b (ADOPT upstream 7453c7cd, "bind retained actions to position
        // episodes"): a Cure is retained-value-mutating (it cancels a pending
        // close and can accept a top-up deposit), so it binds to the SAME
        // position_epoch as the trade family and the other with_one_portfolio_view
        // callers -- not the matcher-consent sequence (Deposit/Withdraw/
        // SetMatcherConfig's lane), since Cure has nothing to do with matcher
        // trust.
        {
            let portfolio_data = portfolio_ai.try_borrow_data()?;
            let current_portfolio_id = state::read_portfolio_id(&portfolio_data)?;
            let current_position_epoch = state::read_portfolio_position_epoch(&portfolio_data)?;
            if !state::portfolio_position_binding_matches(
                current_portfolio_id,
                current_position_epoch,
                expected_portfolio_id,
                expected_position_epoch,
            ) {
                return Err(PercolatorError::EngineProvenanceMismatch.into());
            }
        }

        let amount_u64 = if optional_deposit != 0 {
            let source_token = account(accounts, 3)?;
            let vault_token = account(accounts, 4)?;
            let token_program = account(accounts, 5)?;
            expect_writable(source_token)?;
            expect_writable(vault_token)?;
            verify_token_program(token_program)?;
            let cfg_pre =
                state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?.0;
            let mint = primary_collateral_mint(&cfg_pre);
            let (vault_authority, _) = derive_vault_authority(program_id, market_ai.key);
            let source_balance = verify_user_token_account(source_token, owner.key, &mint)?;
            verify_vault_token_account(vault_token, &vault_authority, &mint)?;
            let amount_u64 = amount_to_u64(optional_deposit)?;
            require_token_balance(source_balance, amount_u64)?;
            Some((amount_u64, source_token, vault_token, token_program))
        } else {
            None
        };

        {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (cfg, mut group) = state::market_view_mut(&mut market_data)?;
            if group.header.mode != 0 {
                return Err(PercolatorError::EngineLockActive.into());
            }
            reject_permissionless_resolve_matured_live_view(&cfg, &group)?;
            let mut portfolio_data = portfolio_ai.try_borrow_mut_data()?;
            // TB-1b: live re-check right before mutation.
            {
                let current_portfolio_id = state::read_portfolio_id(&portfolio_data)?;
                let current_position_epoch =
                    state::read_portfolio_position_epoch(&portfolio_data)?;
                if !state::portfolio_position_binding_matches(
                    current_portfolio_id,
                    current_position_epoch,
                    expected_portfolio_id,
                    expected_position_epoch,
                ) {
                    return Err(PercolatorError::EngineProvenanceMismatch.into());
                }
            }
            {
                let mut portfolio = state::portfolio_view_mut_for_market_slots(
                    &mut portfolio_data,
                    max_market_slots,
                )?;
                expect_portfolio_view_account_key(&portfolio, portfolio_ai.key)?;
                // E2: owner==signer OR signer holds the bound NFT (escrowed). NFT trio at base 6.
                let nft = optional_nft_holder_accounts(accounts, 6);
                authorize_owner_or_nft_holder(
                    &portfolio,
                    portfolio_ai.key,
                    owner.key,
                    nft,
                    program_id,
                )?;
                group
                    .cure_and_cancel_close_not_atomic(&mut portfolio, optional_deposit)
                    .map_err(map_v16_error)?;
            }
            // TB-1b (ADOPT upstream 7453c7cd): one-shot -- a landed Cure always
            // advances the position_epoch, so a stale Trade/ForfeitRecoveryLeg/
            // RebalanceReduce/ConvertReleasedPnl/CureAndCancelClose built against
            // the pre-cure episode can never replay against this account again.
            state::bump_portfolio_position_epoch(&mut portfolio_data)?;
        }

        if let Some((amount_u64, source_token, vault_token, token_program)) = amount_u64 {
            transfer_tokens(token_program, source_token, vault_token, owner, amount_u64)?;
        }
        Ok(())
    }

    /// Tag 43 `ForfeitRecoveryLeg`. `b_loss_atom_budget` is a COLLATERAL-ATOM loss budget
    /// and is passed to the engine verbatim; see the doc on `ix::Instruction::ForfeitRecoveryLeg`
    /// for the unit, its bound, and the legacy-value hazard (a B-index-scale number forfeits
    /// that many ATOMS). The handler validates only that the budget is nonzero — scale is the
    /// caller's to get right, and the engine caps the settled amount at
    /// `min(public_b_chunk_atoms, b_remaining)`.
    #[inline(never)]
    fn handle_forfeit_recovery_leg<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        expected_portfolio_id: u64,
        expected_position_epoch: u64,
        asset_index: u16,
        b_loss_atom_budget: u128,
    ) -> ProgramResult {
        if b_loss_atom_budget == 0 {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        with_one_portfolio_view(
            program_id,
            accounts,
            true,
            Some((expected_portfolio_id, expected_position_epoch)),
            |group, portfolio, cfg| {
            // W-23(b, maturity half): restore the upstream maturity gate dropped in
            // our port. Once a market has matured into a permissionless resolve, an
            // owner-signed forfeit must not still mutate positions — the same gate
            // was already restored on the sibling `RebalanceReduce` (tag 44) path by
            // #446. Upstream carries this exact check in `handle_forfeit_recovery_leg`
            // (`percolator-prog upstream/main:src/v16_program.rs:11519-11520`).
            if group.header.mode == 0 && permissionless_resolve_matured_now_view(cfg, group) {
                return Err(V16Error::LockActive);
            }
            // FIX (ADOPT upstream 7a050c25, "canonical zero-move funding accrual",
            // adapted -- Wave-1 S4): `ForfeitRecoveryLeg` changes this leg's
            // position outside any trade/crank route, so settle owed zero-move
            // funding first. Forfeit is always a reducing operation on this leg
            // (`true` -- full catch-up required, matching the trade routes'
            // closing-leg behavior).
            accrue_zero_move_funding_before_position_change_view(
                cfg,
                group,
                asset_index as usize,
                true,
            )?;
            group
                .forfeit_recovery_leg_not_atomic(
                    portfolio,
                    asset_index as usize,
                    b_loss_atom_budget,
                )
                .map(|_| ())
        })
    }

    #[inline(never)]
    fn handle_rebalance_reduce<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        expected_portfolio_id: u64,
        expected_position_epoch: u64,
        asset_index: u16,
        reduce_q: u128,
    ) -> ProgramResult {
        if reduce_q == 0 {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        with_one_portfolio_view(
            program_id,
            accounts,
            true,
            Some((expected_portfolio_id, expected_position_epoch)),
            |group, portfolio, cfg| {
            // #446: restore the upstream maturity gate dropped in our port. Once a
            // market has matured into a permissionless resolve, an owner-signed
            // rebalance-reduce must not still mutate positions — the same gate guards
            // the sibling path at :6661.
            if group.header.mode == 0 && permissionless_resolve_matured_now_view(cfg, group) {
                return Err(V16Error::LockActive);
            }
            // FIX (ADOPT upstream 7a050c25, "canonical zero-move funding accrual",
            // adapted -- Wave-1 S4): same pre-position-change settlement as
            // `ForfeitRecoveryLeg` above -- a rebalance-reduce is always a
            // reducing operation on this leg.
            accrue_zero_move_funding_before_position_change_view(
                cfg,
                group,
                asset_index as usize,
                true,
            )?;
            group
                .rebalance_reduce_position_not_atomic(
                    portfolio,
                    RebalanceRequestV16 {
                        asset_index: asset_index as usize,
                        reduce_q,
                    },
                )
                .map(|_| ())
        })
    }

    #[inline(never)]
    fn handle_sync_maintenance_fee<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        now_slot: u64,
    ) -> ProgramResult {
        let market_ai = account(accounts, 0)?;
        let portfolio_ai = account(accounts, 1)?;
        expect_writable(market_ai)?;
        expect_writable(portfolio_ai)?;
        expect_owner(market_ai, program_id)?;
        expect_owner(portfolio_ai, program_id)?;

        let (cfg_pre, _mode, max_market_slots, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        ensure_portfolio_storage_for_market_slots(portfolio_ai, max_market_slots)?;
        if let Some(cranker_portfolio_ai) = accounts.get(2) {
            expect_writable(cranker_portfolio_ai)?;
            expect_owner(cranker_portfolio_ai, program_id)?;
            if cranker_portfolio_ai.key != portfolio_ai.key {
                ensure_portfolio_storage_for_market_slots(cranker_portfolio_ai, max_market_slots)?;
            }
        }
        let authenticated_now_slot = authenticated_slot_or_fallback(now_slot);

        {
            let mut market_data = market_ai.try_borrow_mut_data()?;
            let (cfg, mut group) = state::market_view_mut(&mut market_data)?;
            if group.header.mode == 0 {
                reject_permissionless_resolve_matured_live_view(&cfg, &group)?;
            }
            let mut portfolio_data = portfolio_ai.try_borrow_mut_data()?;
            let mut portfolio =
                state::portfolio_view_mut_for_market_slots(&mut portfolio_data, max_market_slots)?;
            expect_portfolio_view_account_key(&portfolio, portfolio_ai.key)?;
            // ADOPT upstream b2d4190b: reject this permissionless fee-sync
            // crank if it would run ahead of a committed price-managed mark
            // on an active leg (see reject_portfolio_pending_price_managed_mark_view).
            reject_portfolio_pending_price_managed_mark_view(&cfg, &group, &portfolio)?;

            // Protocol-fee RESERVE amendment (~/v17/DECISIONS-LEDGER.md): the
            // cranker reward below is paid from the same unbudgeted insurance
            // surplus the protocol's accrued-but-unwithdrawn claim lives in.
            // `protocol_owed` is threaded through as `additional_reserved` so
            // the engine primitive itself refuses to let this reward dip
            // insurance below the protocol's claim.
            //
            // The LP leg (`lp_fee_accrued - lp_fee_withdrawn`, drained by tag 78)
            // is deliberately NOT reserved here. A maintenance crank is
            // `engine_available`-neutral: `charge_account_fee_current_not_atomic`
            // does `c_tot -= charged; insurance += charged` (engine
            // `v16.rs:13781-13800`), `maintenance_cranker_reward` is bounded by
            // `bps <= 10_000` (validated in `validate_wrapper_config`, via the
            // `config.maintenance_cranker_fee_share_bps > 10_000` reject) so
            // `reward <= charged`, and
            // the retained remainder is credited to the domain budgets 1:1 --
            // hence `d(engine_available) = (c-r) - (c-r) = 0` and this path
            // cannot reduce the surplus the LP claim sits in. Reserving the LP
            // leg here would also make LP fees SENIOR to bad-debt/socialized-loss
            // coverage (this reservation binds only via
            // `credit_account_from_insurance_not_atomic`), contradicting the
            // decision that LP yield is at-risk JUNIOR backing capital, and it
            // would revert the entire `SyncMaintenanceFee` on exactly the
            // distressed markets that most need cranking.
            let protocol_owed = cfg_pre
                .protocol_fee_accrued_atoms
                .saturating_sub(cfg_pre.protocol_fee_withdrawn_atoms);
            if let Some(cranker_portfolio_ai) = accounts.get(2) {
                if cranker_portfolio_ai.key == portfolio_ai.key {
                    let charged = sync_maintenance_fee_checkpointed(
                        &mut group,
                        &cfg,
                        &mut portfolio,
                        authenticated_now_slot,
                        cfg_pre.maintenance_fee_per_slot,
                    )?;
                    let reward = maintenance_cranker_reward(
                        charged,
                        cfg_pre.maintenance_cranker_fee_share_bps,
                    )?;
                    if reward != 0 {
                        group
                            .credit_account_from_insurance_not_atomic(
                                &mut portfolio,
                                reward,
                                protocol_owed,
                            )
                            .map_err(map_v16_error)?;
                        group.validate_shape().map_err(map_v16_error)?;
                        portfolio
                            .validate_with_market(&group.as_view())
                            .map_err(map_v16_error)?;
                    }
                    let retained = charged
                        .checked_sub(reward)
                        .ok_or(PercolatorError::EngineCounterUnderflow)?;
                    credit_maintenance_fee_to_active_market_budgets_view(
                        &cfg, &mut group, retained,
                    )?;
                    group.validate_shape().map_err(map_v16_error)?;
                    portfolio
                        .validate_with_market(&group.as_view())
                        .map_err(map_v16_error)?;
                } else {
                    // Finding 15: the separate-cranker path credits maintenance-fee rewards to a
                    // portfolio the caller does not necessarily own. Without an ownership check, any
                    // party can call SyncMaintenanceFee on every user's portfolio and direct all
                    // rewards to an attacker-controlled account, draining insurance systematically.
                    let cranker_owner_ai = account(accounts, 3)?;
                    expect_signer(cranker_owner_ai)?;
                    let mut cranker_data = cranker_portfolio_ai.try_borrow_mut_data()?;
                    let mut cranker = state::portfolio_view_mut_for_market_slots(
                        &mut cranker_data,
                        max_market_slots,
                    )?;
                    expect_portfolio_view_account_key(&cranker, cranker_portfolio_ai.key)?;
                    if cranker_owner_ai.key.to_bytes() != cranker.header.owner {
                        return Err(PercolatorError::Unauthorized.into());
                    }
                    cranker
                        .validate_with_market(&group.as_view())
                        .map_err(map_v16_error)?;
                    let charged = sync_maintenance_fee_checkpointed(
                        &mut group,
                        &cfg,
                        &mut portfolio,
                        authenticated_now_slot,
                        cfg_pre.maintenance_fee_per_slot,
                    )?;
                    let reward = maintenance_cranker_reward(
                        charged,
                        cfg_pre.maintenance_cranker_fee_share_bps,
                    )?;
                    if reward != 0 {
                        group
                            .credit_account_from_insurance_not_atomic(
                                &mut cranker,
                                reward,
                                protocol_owed,
                            )
                            .map_err(map_v16_error)?;
                        group.validate_shape().map_err(map_v16_error)?;
                        portfolio
                            .validate_with_market(&group.as_view())
                            .map_err(map_v16_error)?;
                        cranker
                            .validate_with_market(&group.as_view())
                            .map_err(map_v16_error)?;
                    }
                    let retained = charged
                        .checked_sub(reward)
                        .ok_or(PercolatorError::EngineCounterUnderflow)?;
                    credit_maintenance_fee_to_active_market_budgets_view(
                        &cfg, &mut group, retained,
                    )?;
                    group.validate_shape().map_err(map_v16_error)?;
                    portfolio
                        .validate_with_market(&group.as_view())
                        .map_err(map_v16_error)?;
                    cranker
                        .validate_with_market(&group.as_view())
                        .map_err(map_v16_error)?;
                }
            } else {
                let charged = sync_maintenance_fee_checkpointed(
                    &mut group,
                    &cfg,
                    &mut portfolio,
                    authenticated_now_slot,
                    cfg_pre.maintenance_fee_per_slot,
                )?;
                credit_maintenance_fee_to_active_market_budgets_view(&cfg, &mut group, charged)?;
                group.validate_shape().map_err(map_v16_error)?;
                portfolio
                    .validate_with_market(&group.as_view())
                    .map_err(map_v16_error)?;
            }

            // VULN-03: do NOT deregister-and-close here.
            //
            // handle_sync_maintenance_fee is fully permissionless (no expect_signer on the
            // portfolio owner). If the crank also called
            //   deregister_materialized_portfolio_if_empty + close_portfolio_account_to_market_slab,
            // any third party could force-close an owner's empty (but previously active) portfolio
            // without consent, and the closer would receive that owner's rent-exempt lamports,
            // forcing the owner to re-pay rent to re-open their account (griefing attack).
            //
            // STALE SENTENCE CORRECTED 2026-08-29: this comment used to say the rent goes to
            // `market_ai`, which was true when it was written and stopped being true at #398
            // ("route portfolio rent to closer, not market slab"). The griefing ARGUMENT is
            // unaffected and still the reason this handler does not close accounts — it is
            // about a PERMISSIONLESS caller taking the rent, and after #398 the permissionless
            // caller would take it directly rather than parking it in the market. The
            // destination being `closer` is deliberate and correct for the two paths that DO
            // close: the owner recovers their own deposit on a voluntary close, and marketauth
            // receives it on terminal cleanup (#398 records both as intended destinations).
            //
            // Additionally, partial deregistration without account-close would strand the portfolio
            // in a "registered-but-deregistered" limbo that blocks the owner's subsequent
            // handle_close_portfolio call (deregister_empty_materialized_portfolio_not_atomic would
            // return LockActive on second attempt, trapping rent permanently).
            //
            // Account closure is gated on owner or marketauth consent in handle_close_portfolio,
            // which already provides the signer-check + deregister + account-close sequence.
        };
        Ok(())
    }

    #[inline(never)]
    fn handle_resolve_market<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        expected_asset_generation_frontier: u64,
        expected_authority_epoch: u64,
    ) -> ProgramResult {
        let admin = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        expect_signer(admin)?;
        expect_writable(market_ai)?;
        expect_owner(market_ai, program_id)?;
        let mut market_data = market_ai.try_borrow_mut_data()?;
        let (cfg, mut group) = state::market_view_mut(&mut market_data)?;
        require_asset_generation_frontier_view(&group, expected_asset_generation_frontier)?;
        if group.header.mode != 0 {
            return Err(PercolatorError::EngineLockActive.into());
        }
        expect_live_authority(&cfg.marketauth, admin.key)?;
        // W3A-3: `authority_epoch` (upstream `95d155bc`) -- CHECK-only (NOT
        // advanced -- only `UpdateAuthority`/`UpdateAssetAuthority` advance
        // asset-0's epoch), mirrors upstream's exact placement: right after
        // `marketauth` authorization, before the slot-staleness gate and
        // `resolve_market_not_atomic`. asset-0 lane, matching `marketauth`'s
        // own epoch slot (`UpdateAuthority`'s asset_index == 0).
        require_authority_epoch_view(&group, 0, expected_authority_epoch)?;
        let slot = Clock::get()
            .map(|c| c.slot)
            .unwrap_or(group.header.current_slot.get());
        if slot < group.header.current_slot.get() {
            return Err(PercolatorError::EngineStale.into());
        }
        group
            .resolve_market_not_atomic(slot)
            .map_err(map_v16_error)?;
        Ok(())
    }

    #[inline(never)]
    fn handle_update_authority<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        new_pubkey: [u8; 32],
        expected_authority_epoch: u64,
    ) -> ProgramResult {
        let current = account(accounts, 0)?;
        let new_authority = account(accounts, 1)?;
        let market_ai = account(accounts, 2)?;
        expect_signer(current)?;
        expect_writable(market_ai)?;
        expect_owner(market_ai, program_id)?;

        if new_pubkey == [0u8; 32] {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        // Incoming key must co-sign (proves control).
        expect_signer(new_authority)?;
        if new_authority.key.to_bytes() != new_pubkey {
            return Err(PercolatorError::Unauthorized.into());
        }

        // W3A-1: was `read_market_config_mode_and_capacity` + `write_wrapper_config`
        // (config-only, no `AssetControlSequencesV16` access). Upgraded to
        // `market_view_mut` so this handler can reach asset-0's control-sequences
        // region for the epoch CAS below -- `cfg` is still read out by value and
        // written back exactly as before; no other behavior changes.
        let mut market_data = market_ai.try_borrow_mut_data()?;
        let cfg = {
            let (mut cfg, mut group) = state::market_view_mut(&mut market_data)?;
            expect_live_authority(&cfg.marketauth, current.key)?;
            // Bind to asset-0's `authority_epoch` lane -- the SAME per-asset slot
            // `UpdateAssetAuthority` uses at `asset_index == 0` (upstream `95d155bc`
            // reuses that exact field for the market-level authority rather than
            // adding a new one; see `UpdateAuthority`'s own doc comment). Strict CAS
            // + auto-increment: closes the A->B->A durable-nonce replay hole this
            // rotation previously had ZERO epoch binding against.
            advance_authority_epoch_view(&mut group, 0, expected_authority_epoch)?;
            cfg.marketauth = new_pubkey;
            cfg
        };
        state::write_wrapper_config(&mut market_data, &cfg)
    }

    #[inline(never)]
    fn handle_update_asset_authority<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        asset_index: u16,
        expected_market_id: u64,
        kind: u8,
        new_pubkey: [u8; 32],
        authority_epoch: u64,
    ) -> ProgramResult {
        let current = account(accounts, 0)?;
        let new_authority = account(accounts, 1)?;
        let market_ai = account(accounts, 2)?;
        expect_signer(current)?;
        expect_writable(market_ai)?;
        expect_owner(market_ai, program_id)?;

        // A non-zero incoming key must co-sign (proves control); burning to 0 needs only the rotator.
        if new_pubkey != [0u8; 32] {
            expect_signer(new_authority)?;
            if new_authority.key.to_bytes() != new_pubkey {
                return Err(PercolatorError::Unauthorized.into());
            }
        }

        let asset_index = asset_index as usize;
        // Asset 0 carries a real stored profile (asset_admin bootstrapped to the market admin) and is
        // rotated/burned here exactly like permissionless assets 1..N.

        let mut data = market_ai.try_borrow_mut_data()?;
        let (cfg, mut group) = state::market_view_mut(&mut data)?;
        if group.header.mode != 0 {
            return Err(PercolatorError::EngineLockActive.into());
        }
        if asset_index >= group.header.config.max_market_slots.get() as usize {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        require_asset_generation_view(&group, asset_index, expected_market_id)?;
        let mut profile = read_oracle_profile_from_view(&group, &cfg, asset_index)?;

        // The asset's own cold-storage admin may rotate ANY of its authorities, and only the admin
        // authority itself may be burned to 0; otherwise the current holder of THIS authority
        // self-rotates. Scoped to this asset's profile only — it can never act on another asset.
        let admin_signed =
            profile.asset_admin != [0u8; 32] && profile.asset_admin == current.key.to_bytes();
        let current_value = match kind {
            ASSET_AUTH_ADMIN => profile.asset_admin,
            ASSET_AUTH_INSURANCE => profile.insurance_authority,
            ASSET_AUTH_INSURANCE_OPERATOR => profile.insurance_operator,
            ASSET_AUTH_BACKING_BUCKET => profile.backing_bucket_authority,
            ASSET_AUTH_ORACLE => profile.oracle_authority,
            _ => return Err(PercolatorError::InvalidInstruction.into()),
        };
        // Required domain authorities must stay live after activation. A zero insurance/backing/oracle
        // authority can strand funds or oracle liveness during wind-down; only the cold-storage
        // asset_admin may be intentionally burned.
        if new_pubkey == [0u8; 32] && kind != ASSET_AUTH_ADMIN {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        // ── #437/#439: the admin bypass is an allow-list of STATES, not of KINDS. ──
        //
        // History of this guard, one leg at a time: #414 found `asset_admin` could take
        // `insurance_authority`; #416/#417 added `insurance_operator` to the same
        // `matches!`; #424 bolted a separate custody check onto `backing_bucket_authority`.
        // Each fix NAMED the kind it was closing, which left the rule "bypass everything
        // except the names we happened to think of". #437/#439 is the bill for that: the
        // `matches!` listed two of the five kinds, so ORACLE and BACKING_BUCKET skipped
        // `expect_live_authority` entirely and `asset_admin` could rotate them away from a
        // holder that never signed — for ORACLE, straight into ConfigureAuthMark (which
        // itself switches `oracle_mode`, so no prior auth-mark configuration is needed) and
        // PushAuthMark, i.e. the asset's whole price surface.
        //
        // So the rule is INVERTED rather than extended. The bypass is now permitted only
        // for a state in which there IS NO HOLDER TO DEFEND. A sixth authority kind added
        // later is therefore guarded on the day it is added, instead of being silently
        // exempt until someone files the next issue.
        //
        // Two unheld states exist:
        //
        //  1. `current_value == 0` — bootstrapping. Kept from the previous rule. In
        //     practice every activation path already fills all four sub-authorities
        //     (`domain_authority_fields_complete`, :6799; `activate_dynamic_asset_slot`,
        //     :2180) and non-admin kinds cannot be burned back to 0 (the check directly
        //     above), so this is defence in depth rather than a live path.
        //
        //  2. The LP-vault registry PDA holding `backing_bucket_authority` AFTER the vault
        //     has been closed. `handle_create_lp_vault`'s FIND-1 binding parks this
        //     authority on `registry_pda`, an address NOTHING can sign for — no path CPIs
        //     back into this program to sign as it. Under a holder-consent rule that is not
        //     "a holder that must consent", it is a permanent lock, and #424's own comment
        //     records why the lock must not be permanent: CloseLpVault leaves the LP mint
        //     on-chain (so CreateLpVault can never re-run) and leaves the dead-share floor's
        //     backing residue in the bucket, and reclaiming that residue — plus reaching
        //     CloseSlab, which needs `header.vault == 0` — requires re-pointing this
        //     authority at a signable key. Treating an unsignable-PDA holder as unheld is
        //     what keeps wind-down reachable while the inversion closes ORACLE.
        //
        // #424's hard reject is preserved verbatim inside (2) and still fires FIRST: while
        // the registry is live and names THIS asset, the rotation is refused outright, not
        // merely consent-checked. Scoped to the vault's own asset, so an unrelated slot that
        // merely carries this value (a lifecycle activation can plant it verbatim, with no
        // co-signature) is not welded shut. The registry account is consulted only on this
        // branch and its ABSENCE rejects — omitting it cannot skip the guard, and
        // `expect_key` pins the address so no substitute is accepted.
        //
        // The whole block is gated on `admin_signed`, which is behaviour-preserving for
        // every other caller and keeps `derive_lp_vault_registry`'s find_program_address off
        // the hot path: a non-admin signer took `expect_live_authority` before reaching the
        // #424 check under the old ordering too (the registry PDA cannot sign, so that call
        // always returned Unauthorized first), so no error code moves.
        //
        // WHAT THIS COSTS. `asset_admin` can no longer re-point a HELD authority without
        // that holder's signature — including to recover from a holder key that is lost. The
        // insurance legs have already paid that price since #416/#417; this makes it uniform
        // across all five kinds. Two escape hatches remain and are unaffected: for assets
        // 1..N, `marketauth` can RETIRE and re-ACTIVATE the slot, which rewrites all four
        // sub-authorities (:13061-13065); and delegating to a multisig/PDA that CAN sign
        // keeps rotation available by construction. Asset 0 has no such hatch, which is
        // deliberate — the same re-activation branch is barred from asset 0 to protect the
        // creator-fee claim (:13029). An operator who wants revocable delegation should
        // therefore hand out `insurance_operator`-style roles from a signable custodian
        // rather than expect the admin to claw them back.
        let admin_bypass_permitted = admin_signed
            && (current_value == [0u8; 32] || {
                if kind == ASSET_AUTH_BACKING_BUCKET {
                    let (registry_pda, _) =
                        state::derive_lp_vault_registry(program_id, market_ai.key);
                    if current_value == registry_pda.to_bytes() {
                        let registry_ai = account(accounts, 3)?;
                        expect_key(registry_ai, &registry_pda)?;
                        let registry_data = registry_ai.try_borrow_data()?;
                        if state::is_initialized(&registry_data) {
                            let registry = state::read_lp_vault_registry(&registry_data)?;
                            if registry.domain as usize / 2 == asset_index {
                                return Err(PercolatorError::LpVaultAuthorityMismatch.into());
                            }
                        }
                        // Live-but-other-asset, or closed: no signer exists behind this
                        // value, so there is no consent to obtain.
                        true
                    } else {
                        false
                    }
                } else {
                    false
                }
            });
        if !admin_bypass_permitted {
            expect_live_authority(&current_value, current.key)?;
        }
        // Gate-2 fix (sync/w2-tb2b follow-up): CAS, not the uniform
        // strictly-increasing nonce -- `authority_epoch` here is the
        // caller's belief about the CURRENT stored value, not a proposed
        // new one. See `advance_authority_epoch_view`'s own doc comment.
        advance_authority_epoch_view(&mut group, asset_index, authority_epoch)?;
        match kind {
            ASSET_AUTH_ADMIN => profile.asset_admin = new_pubkey,
            ASSET_AUTH_INSURANCE => profile.insurance_authority = new_pubkey,
            ASSET_AUTH_INSURANCE_OPERATOR => profile.insurance_operator = new_pubkey,
            ASSET_AUTH_BACKING_BUCKET => profile.backing_bucket_authority = new_pubkey,
            ASSET_AUTH_ORACLE => profile.oracle_authority = new_pubkey,
            _ => return Err(PercolatorError::InvalidInstruction.into()),
        }
        write_oracle_profile_to_view(&mut group, asset_index, &profile)?;
        Ok(())
    }

    #[inline(never)]
    fn handle_update_base_unit_mints<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        primary_mint: [u8; 32],
        secondary_mint: [u8; 32],
        expected_authority_epoch: u64,
    ) -> ProgramResult {
        let authority = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let primary_mint_ai = account(accounts, 2)?;
        let secondary_mint_ai = account(accounts, 3)?;
        expect_signer(authority)?;
        expect_writable(market_ai)?;
        expect_owner(market_ai, program_id)?;
        if primary_mint == [0u8; 32]
            || secondary_mint == [0u8; 32]
            || primary_mint == secondary_mint
        {
            return Err(PercolatorError::InvalidMint.into());
        }
        let primary_key = Pubkey::new_from_array(primary_mint);
        let secondary_key = Pubkey::new_from_array(secondary_mint);
        expect_key(primary_mint_ai, &primary_key)?;
        expect_key(secondary_mint_ai, &secondary_key)?;
        // #447: the primary and secondary collateral mints are both denominated in
        // engine base units. Mismatched decimals silently rescale every deposit and
        // withdrawal through the secondary mint. Upstream rejects it here; our port
        // dropped the check by calling `verify_mint`, which discards the mint it
        // unpacks.
        let primary_mint_state = unpack_mint(primary_mint_ai)?;
        let secondary_mint_state = unpack_mint(secondary_mint_ai)?;
        if primary_mint_state.decimals != secondary_mint_state.decimals {
            return Err(PercolatorError::InvalidMint.into());
        }

        let mut data = market_ai.try_borrow_mut_data()?;
        let mut cfg = {
            let (cfg, group) = state::market_view_mut(&mut data)?;
            expect_live_authority(&cfg.marketauth, authority.key)?;
            // W3A-2: ADOPT upstream `717206c3` -- gate-2-class replay protection.
            // This admin op changes the market's accepted collateral mints with
            // no prior replay protection; a held/durable-nonce signed tx stays
            // valid indefinitely. Binding it to the LIVE asset-0 authority_epoch
            // means any intervening rotation (via `UpdateAssetAuthority`)
            // invalidates it. CHECK ONLY -- this tag does not itself rotate the
            // epoch (see `require_authority_epoch_view`'s own doc comment).
            require_authority_epoch_view(&group, 0, expected_authority_epoch)?;
            if group.header.vault.get() != 0
                || group.header.c_tot.get() != 0
                || group.header.insurance.get() != 0
            {
                return Err(PercolatorError::EngineLockActive.into());
            }
            cfg
        };

        // ── GH#451: the OLD vault must be empty before its mint is switched away ──
        //
        // The header counters above (vault / c_tot / insurance) are the engine's
        // accounting. They can all read zero while the SPL token account still
        // holds a balance — tokens that arrived outside the accounted paths, or a
        // residue the counters no longer track. Switching the mint then orphans
        // those atoms: the vault authority still owns them, but no instruction
        // references that mint any more, so nothing can move them out.
        //
        // Upstream checks this and our port dropped it. Ported here, keeping our
        // stricter canonical-address pin.
        //
        // Only the mints that actually CHANGE are checked, and the account indices
        // are conditional on that — matching upstream exactly, so a caller
        // switching only the secondary passes four accounts plus one, not two.
        // A no-op call (both mints unchanged) requires no extra accounts at all,
        // which keeps the common re-assert cheap.
        let previous_primary_mint = primary_collateral_mint(&cfg);
        let previous_secondary_mint = if cfg.secondary_collateral_mint == [0u8; 32] {
            None
        } else {
            Some(Pubkey::new_from_array(cfg.secondary_collateral_mint))
        };
        let (vault_authority, _) = derive_vault_authority(program_id, market_ai.key);
        let mut old_vault_account_index = 4usize;
        if previous_primary_mint != primary_key {
            let old_primary_vault = account(accounts, old_vault_account_index)?;
            old_vault_account_index += 1;
            require_empty_vault_token_account(
                old_primary_vault,
                &vault_authority,
                &previous_primary_mint,
            )?;
        }
        if let Some(previous_secondary_mint) = previous_secondary_mint {
            if previous_secondary_mint != secondary_key {
                let old_secondary_vault = account(accounts, old_vault_account_index)?;
                require_empty_vault_token_account(
                    old_secondary_vault,
                    &vault_authority,
                    &previous_secondary_mint,
                )?;
            }
        }

        cfg.collateral_mint = primary_mint;
        cfg.secondary_collateral_mint = secondary_mint;
        state::write_wrapper_config(&mut data, &cfg)
    }

    #[inline(never)]
    fn handle_swap_secondary_for_primary<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        amount: u128,
        expected_authority_epoch: u64,
    ) -> ProgramResult {
        let authority = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        let primary_source_token = account(accounts, 2)?;
        let primary_vault_token = account(accounts, 3)?;
        let secondary_dest_token = account(accounts, 4)?;
        let secondary_vault_token = account(accounts, 5)?;
        let vault_authority_ai = account(accounts, 6)?;
        let token_program = account(accounts, 7)?;
        expect_signer(authority)?;
        expect_writable(primary_source_token)?;
        expect_writable(primary_vault_token)?;
        expect_writable(secondary_dest_token)?;
        expect_writable(secondary_vault_token)?;
        expect_owner(market_ai, program_id)?;
        verify_token_program(token_program)?;
        if amount == 0 {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        let amount_u64 = amount_to_u64(amount)?;

        // VULN-02 (#355): reject when the market is not Live (resolved/locked), mirroring
        // handle_deposit and every other engine-touching handler. Without this guard the
        // secondary->primary swap stayed callable after ResolveMarket (the handler read the
        // mode but discarded it and never engaged the engine lock).
        //
        // W3A-2: ADOPT upstream `717206c3` epoch binding (adapted for our fork's extra
        // VULN-02 mode check, which upstream's own version of this handler does not have).
        // Scoped to one immutable borrow so the asset-0 `authority_epoch` read below sees
        // the same snapshot as `cfg`/`mode` -- no view is already in scope here (unlike
        // `handle_update_base_unit_mints`, which holds a `market_view_mut` and uses
        // `require_authority_epoch_view` instead), so this reads the raw control-sequences
        // bytes directly via `state::read_asset_control_sequences` +
        // `state::require_current_authority_epoch`. CHECK ONLY -- no advance.
        let cfg = {
            let market_data = market_ai.try_borrow_data()?;
            let (cfg, mode, _, _) = state::read_market_config_mode_and_capacity(&market_data)?;
            if mode != MarketModeV16::Live {
                return Err(PercolatorError::EngineLockActive.into());
            }
            expect_live_authority(&cfg.marketauth, authority.key)?;
            let sequences = state::read_asset_control_sequences(&market_data, 0)?;
            state::require_current_authority_epoch(
                sequences.authority_epoch,
                expected_authority_epoch,
            )?;
            cfg
        };
        let primary_mint = primary_collateral_mint(&cfg);
        let secondary_mint = secondary_collateral_mint(&cfg)?;
        let (vault_authority, bump) = derive_vault_authority(program_id, market_ai.key);
        expect_key(vault_authority_ai, &vault_authority)?;
        let primary_source_balance =
            verify_user_token_account(primary_source_token, authority.key, &primary_mint)?;
        verify_vault_token_account(primary_vault_token, &vault_authority, &primary_mint)?;
        verify_user_token_account(secondary_dest_token, authority.key, &secondary_mint)?;
        let secondary_vault_balance =
            verify_vault_token_account(secondary_vault_token, &vault_authority, &secondary_mint)?;
        require_token_balance(primary_source_balance, amount_u64)?;
        require_token_balance(secondary_vault_balance, amount_u64)?;

        transfer_tokens(
            token_program,
            primary_source_token,
            primary_vault_token,
            authority,
            amount_u64,
        )?;
        let bump_arr = [bump];
        let signer_seeds: &[&[&[u8]]] = &[&[b"vault", market_ai.key.as_ref(), &bump_arr]];
        transfer_tokens_signed(
            token_program,
            secondary_vault_token,
            secondary_dest_token,
            vault_authority_ai,
            amount_u64,
            signer_seeds,
        )
    }

    fn canonicalize_retired_asset_slot_view(
        group: &mut state::MarketViewMutV16<'_>,
        asset_index: usize,
    ) -> ProgramResult {
        let slot = group
            .markets
            .get_mut(asset_index)
            .ok_or(PercolatorError::InvalidInstruction)?;
        let asset = slot.engine.asset.try_to_runtime().map_err(map_v16_error)?;
        if asset.lifecycle != percolator::AssetLifecycleV16::Retired
            || asset.market_id == 0
            || asset.retired_slot == 0
            || slot.engine.insurance_domain_budget_long.get() != 0
            || slot.engine.insurance_domain_budget_short.get() != 0
            || slot.engine.insurance_domain_spent_long.get() != 0
            || slot.engine.insurance_domain_spent_short.get() != 0
            || slot.engine.pending_domain_loss_barrier_long.get() != 0
            || slot.engine.pending_domain_loss_barrier_short.get() != 0
        {
            return Err(PercolatorError::EngineLockActive.into());
        }
        let backing_long = slot
            .engine
            .backing_long
            .try_to_runtime()
            .map_err(map_v16_error)?;
        let backing_short = slot
            .engine
            .backing_short
            .try_to_runtime()
            .map_err(map_v16_error)?;
        if backing_long.utilization_fee_earnings != 0 || backing_short.utilization_fee_earnings != 0
        {
            return Err(PercolatorError::EngineLockActive.into());
        }

        let mut canonical_asset = percolator::AssetStateV16::default();
        canonical_asset.market_id = asset.market_id;
        canonical_asset.retired_slot = asset.retired_slot;
        canonical_asset.lifecycle = percolator::AssetLifecycleV16::Retired;
        canonical_asset.raw_oracle_target_price = asset.raw_oracle_target_price;
        canonical_asset.effective_price = asset.effective_price;
        canonical_asset.fund_px_last = asset.fund_px_last;
        canonical_asset.slot_last = asset.slot_last;

        let mut canonical_slot =
            percolator::EngineAssetSlotV16Account::empty_for_market(asset.market_id);
        canonical_slot.asset = percolator::AssetStateV16Account::from_runtime(&canonical_asset);
        slot.engine = canonical_slot;
        Ok(())
    }

    #[inline(never)]
    fn handle_restart_asset_oracle<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        asset_index: u16,
        expected_market_id: u64,
        now_slot: u64,
        initial_price: u64,
        observation_sequence: u64,
    ) -> ProgramResult {
        let authority = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        expect_signer(authority)?;
        expect_writable(market_ai)?;
        expect_owner(market_ai, program_id)?;
        if now_slot == 0 || initial_price == 0 || initial_price > percolator::MAX_ORACLE_PRICE {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        let authenticated_slot = authenticated_slot_or_fallback(now_slot);
        let cfg_after = {
            let mut data = market_ai.try_borrow_mut_data()?;
            let (mut cfg, mut group) = state::market_view_mut(&mut data)?;
            if group.header.mode != 0 {
                return Err(PercolatorError::EngineLockActive.into());
            }
            let asset_index = asset_index as usize;
            let configured_slots = group.header.config.max_market_slots.get() as usize;
            if asset_index >= configured_slots || asset_index >= group.markets.len() {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            require_asset_generation_view(&group, asset_index, expected_market_id)?;
            if authenticated_slot < group.header.current_slot.get() {
                return Err(PercolatorError::EngineStale.into());
            }
            if group.markets[asset_index].engine.asset.lifecycle != ASSET_LIFECYCLE_RECOVERY {
                return Err(PercolatorError::EngineLockActive.into());
            }
            let existing_profile = read_oracle_profile_from_view(&group, &cfg, asset_index)?;
            expect_live_authority(&existing_profile.asset_admin, authority.key)?;
            advance_control_sequence_view(
                &mut group,
                asset_index,
                ControlSequenceLane::OracleObservation,
                observation_sequence,
            )?;
            group
                .restart_empty_asset_preserving_insurance_budget_not_atomic(
                    asset_index,
                    initial_price,
                    authenticated_slot,
                )
                .map_err(map_v16_error)?;

            // TB-1a: deref-copy -- `manual_asset_oracle_profile` returns
            // `Box<...>` (BPF stack-pressure fix, see its doc comment); this
            // function is not stack-tight, so an owned copy is fine here.
            let mut profile = *state::manual_asset_oracle_profile(initial_price, authenticated_slot);
            preserve_backing_fee_policy(&mut profile, &existing_profile);
            profile.asset_admin = existing_profile.asset_admin;
            profile.insurance_authority = existing_profile.insurance_authority;
            profile.insurance_operator = existing_profile.insurance_operator;
            profile.backing_bucket_authority = existing_profile.backing_bucket_authority;
            profile.oracle_authority = existing_profile.oracle_authority;
            if asset_index == 0 {
                mirror_manual_profile_to_base_config(&mut cfg, &profile, true);
            }
            write_oracle_profile_to_view(&mut group, asset_index, &profile)?;
            group.validate_shape().map_err(map_v16_error)?;
            cfg
        };
        state::write_wrapper_config(&mut market_ai.try_borrow_mut_data()?, &cfg_after)
    }

    #[inline(never)]
    fn handle_update_asset_lifecycle<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        action: u8,
        asset_index: u16,
        expected_market_id: u64,
        expected_authority_epoch: u64,
        now_slot: u64,
        initial_price: u64,
        max_init_fee: u128,
        insurance_authority: [u8; 32],
        insurance_operator: [u8; 32],
        backing_bucket_authority: [u8; 32],
        oracle_authority: [u8; 32],
    ) -> ProgramResult {
        let authority = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        expect_signer(authority)?;
        expect_writable(market_ai)?;
        expect_owner(market_ai, program_id)?;

        let asset_index = asset_index as usize;
        // Wave-2 TB-4 (adopts upstream f5c2c6bb): an ACTIVATE (append OR reuse of a
        // retired slot) binds against the market's `next_market_id` frontier — the
        // generation about to be stamped onto this slot. Any other action binds
        // against the slot's current live `market_id`. Checked once, up front,
        // against every reachable branch below (append, permissionless reuse,
        // marketauth-privileged reuse/retire/drain-only, and this fork's SHUTDOWN
        // action further down).
        let is_activation = action == ASSET_ACTION_ACTIVATE;
        {
            let data = market_ai.try_borrow_data()?;
            let (current_market_id, next_market_id) =
                state::read_asset_lifecycle_generation_preflight(&data, asset_index, is_activation)?;
            if !state::asset_lifecycle_generation_binding_matches(
                current_market_id,
                next_market_id,
                is_activation,
                expected_market_id,
            ) {
                return Err(PercolatorError::AssetGenerationMismatch.into());
            }
        }
        let (cfg_pre, mode_pre, configured_slots_pre, capacity_pre) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        if mode_pre != MarketModeV16::Live {
            return Err(PercolatorError::EngineLockActive.into());
        }
        // Same funding warning as InitMarket: activating an asset is creating a
        // market, and an asset priced below the funding threshold has the
        // identical silent-dead-funding failure. `max_abs_funding_e9_per_slot`
        // and `max_accrual_dt_slots` are market-wide; only `initial_price` varies
        // per asset, so a market can be perfectly fundable at asset 0's price and
        // dead-funded at asset 5's.
        if action == ASSET_ACTION_ACTIVATE {
            let (max_abs_funding_e9_per_slot, max_accrual_dt_slots) =
                state::read_engine_funding_bounds(&market_ai.try_borrow_data()?)?;
            warn_if_funding_cannot_accrue(
                max_abs_funding_e9_per_slot,
                max_accrual_dt_slots,
                initial_price,
            );
        }
        let is_asset_authority =
            cfg_pre.marketauth != [0u8; 32] && cfg_pre.marketauth == authority.key.to_bytes();
        let permissionless_reuse_target = action == ASSET_ACTION_ACTIVATE
            && !is_asset_authority
            && asset_index < configured_slots_pre
            && cfg_pre.free_market_slot_count != 0;
        if action == ASSET_ACTION_ACTIVATE
            && (asset_index == configured_slots_pre || permissionless_reuse_target)
        {
            let authenticated_slot = authenticated_slot_or_fallback(now_slot);
            let append_activation = asset_index == configured_slots_pre;
            if append_activation && cfg_pre.free_market_slot_count != 0 {
                return Err(PercolatorError::EngineLockActive.into());
            }
            let init_fee = if is_asset_authority {
                0
            } else {
                let fee = permissionless_market_init_fee_for_asset(
                    cfg_pre.permissionless_market_init_fee,
                    asset_index,
                )?;
                if fee == 0 || fee > max_init_fee {
                    return Err(PercolatorError::Unauthorized.into());
                }
                fee
            };
            let transfer_accounts = if init_fee == 0 {
                None
            } else {
                let source_token = account(accounts, 2)?;
                let vault_token = account(accounts, 3)?;
                let token_program = account(accounts, 4)?;
                expect_writable(source_token)?;
                expect_writable(vault_token)?;
                verify_token_program(token_program)?;
                let mint = primary_collateral_mint(&cfg_pre);
                let (vault_authority, _) = derive_vault_authority(program_id, market_ai.key);
                let source_balance =
                    verify_user_token_account(source_token, authority.key, &mint)?;
                verify_vault_token_account(vault_token, &vault_authority, &mint)?;
                let amount_u64 = amount_to_u64(init_fee)?;
                require_token_balance(source_balance, amount_u64)?;
                Some((source_token, vault_token, token_program, amount_u64))
            };
            if asset_index >= capacity_pre {
                let new_len = state::market_account_len_for_capacity(asset_index + 1)?;
                market_ai.realloc(new_len, true)?;
            }
            // CEI fix: transfer the init fee BEFORE mutating engine state.
            // A Token-2022 transfer hook fires during the CPI and could re-enter this program
            // while seeing already-committed engine effects (active slot, decremented
            // free_market_slot_count). Performing the transfer first means the hook fires against
            // the pre-activation state, eliminating the re-entrancy window.
            if let Some((source_token, vault_token, token_program, amount_u64)) = transfer_accounts
            {
                transfer_tokens(
                    token_program,
                    source_token,
                    vault_token,
                    authority,
                    amount_u64,
                )?;
            }
            {
                let mut data = market_ai.try_borrow_mut_data()?;
                let mut reuse_cfg_after = None;
                let mut reuse_activated = false;
                {
                    let (mut cfg, mut group) = state::market_view_mut(&mut data)?;
                    require_asset_lifecycle_generation_view(
                        &group,
                        asset_index,
                        true,
                        expected_market_id,
                    )?;
                    let still_asset_authority =
                        cfg.marketauth != [0u8; 32] && cfg.marketauth == authority.key.to_bytes();
                    if still_asset_authority {
                        // W3A-2: ADOPT upstream `dd958393` -- market-authority reuse of a
                        // free slot is authority-consent, so it is bound to the LIVE asset-0
                        // authority_epoch exactly like the other two call sites below.
                        require_authority_epoch_view(&group, 0, expected_authority_epoch)?;
                    } else {
                        // W3A-2: ADOPT upstream `dd958393` -- the permissionless reuse path
                        // below is generation- and fee-bound, not authority consent. Requiring
                        // the canonical zero value here (rather than skipping the check)
                        // prevents this wire lane from becoming an unaudited caller-controlled
                        // payload once `authority_epoch` exists on the wire at all.
                        state::require_current_authority_epoch(0, expected_authority_epoch)?;
                        let expected_fee = permissionless_market_init_fee_for_asset(
                            cfg.permissionless_market_init_fee,
                            asset_index,
                        )?;
                        if expected_fee == 0
                            || expected_fee > max_init_fee
                            || expected_fee != init_fee
                        {
                            return Err(PercolatorError::Unauthorized.into());
                        }
                    }
                    if group.header.mode != 0 {
                        return Err(PercolatorError::EngineLockActive.into());
                    }
                    let configured_slots = group.header.config.max_market_slots.get() as usize;
                    if asset_index == configured_slots {
                        if cfg.free_market_slot_count != 0 {
                            return Err(PercolatorError::EngineLockActive.into());
                        }
                    } else if !still_asset_authority
                        && asset_index < configured_slots
                        && cfg.free_market_slot_count != 0
                    {
                        if group.markets[asset_index].engine.asset.lifecycle
                            != ASSET_LIFECYCLE_RETIRED
                        {
                            // Slot is below max_market_slots and NOT retired. If it is
                            // one of the three IN-SERVICE lifecycles, say so precisely;
                            // anything else keeps the prior generic code so no other
                            // rejection is silently reclassified.
                            return Err(match group.markets[asset_index].engine.asset.lifecycle {
                                ASSET_LIFECYCLE_ACTIVE
                                | ASSET_LIFECYCLE_DRAIN_ONLY
                                | ASSET_LIFECYCLE_RECOVERY => {
                                    PercolatorError::AssetSlotAlreadyConfigured.into()
                                }
                                _ => PercolatorError::EngineLockActive.into(),
                            });
                        }
                        // Reject zero domain authorities, mirroring the append path
                        // (activate_dynamic_asset_slot, ~line 1475). A zero
                        // insurance_authority makes that domain's insurance budget
                        // withdrawable by nobody (terminal_insurance_remaining rejects a
                        // zero authority), permanently bricking CloseSlab (Finding F).
                        if !domain_authority_fields_complete(
                            insurance_authority,
                            insurance_operator,
                            backing_bucket_authority,
                            oracle_authority,
                        ) {
                            return Err(PercolatorError::InvalidInstruction.into());
                        }
                        group
                            .header
                            .activate_empty_market_slot_not_atomic(
                                asset_index as u32,
                                &mut group.markets[asset_index],
                                initial_price,
                                authenticated_slot,
                            )
                            .map_err(map_v16_error)?;
                        cfg.free_market_slot_count = cfg
                            .free_market_slot_count
                            .checked_sub(1)
                            .ok_or(PercolatorError::EngineCounterUnderflow)?;
                        let mut profile =
                            state::manual_asset_oracle_profile(initial_price, authenticated_slot);
                        profile.insurance_authority = insurance_authority;
                        profile.insurance_operator = insurance_operator;
                        profile.backing_bucket_authority = backing_bucket_authority;
                        profile.oracle_authority = oracle_authority;
                        // Per-asset cold-storage admin: bootstrap to the activator; it can later be
                        // rotated to a cold key or burned via UpdateAssetAuthority.
                        profile.asset_admin = authority.key.to_bytes();
                        write_oracle_profile_to_view_if_separate(
                            &mut group,
                            asset_index,
                            &profile,
                        )?;
                        group.validate_shape().map_err(map_v16_error)?;
                        reuse_cfg_after = Some(cfg);
                        reuse_activated = true;
                    } else {
                        return Err(PercolatorError::EngineLockActive.into());
                    }
                }
                if let Some(cfg) = reuse_cfg_after {
                    state::write_wrapper_config(&mut data, &cfg)?;
                }
                if reuse_activated && init_fee != 0 {
                    let (_cfg, mut group) = state::market_view_mut(&mut data)?;
                    deposit_market_zero_insurance_view(&mut group, init_fee)?;
                    group.validate_shape().map_err(map_v16_error)?;
                }
                let (_cfg, _mode, configured_slots, _) =
                    state::read_market_config_mode_and_capacity(&data)?;
                if !reuse_activated && asset_index == configured_slots {
                    let mut profile = state::activate_dynamic_asset_slot(
                        &mut data,
                        asset_index,
                        authenticated_slot,
                        initial_price,
                        insurance_authority,
                        insurance_operator,
                        backing_bucket_authority,
                        oracle_authority,
                    )?;
                    // Per-asset cold-storage admin: bootstrap to the activator (the permissionless
                    // creator or the asset_authority); rotatable / burnable via UpdateAssetAuthority.
                    profile.asset_admin = authority.key.to_bytes();
                    state::write_asset_oracle_profile(&mut data, asset_index, &profile)?;
                    if init_fee != 0 {
                        let (_cfg, mut group) = state::market_view_mut(&mut data)?;
                        deposit_market_zero_insurance_view(&mut group, init_fee)?;
                        group.validate_shape().map_err(map_v16_error)?;
                    }
                }
            }
            return Ok(());
        }
        if action == ASSET_ACTION_SHUTDOWN {
            if now_slot == 0 || initial_price != 0 || cfg_pre.force_close_delay_slots == 0 {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            let authenticated_slot = authenticated_slot_or_fallback(now_slot);
            let cfg_after = {
                let mut data = market_ai.try_borrow_mut_data()?;
                let (mut cfg, mut group) = state::market_view_mut(&mut data)?;
                if group.header.mode != 0 {
                    return Err(PercolatorError::EngineLockActive.into());
                }
                let configured_slots = group.header.config.max_market_slots.get() as usize;
                if asset_index >= configured_slots || asset_index >= group.markets.len() {
                    return Err(PercolatorError::InvalidInstruction.into());
                }
                // Fork-specific SHUTDOWN action (not in upstream's f5c2c6bb pre-image, which only
                // had ACTIVATE/DRAIN_ONLY/RETIRE at this point) — extended the same generation
                // binding here for consistency: SHUTDOWN is never an activation.
                require_asset_lifecycle_generation_view(&group, asset_index, false, expected_market_id)?;
                let mut profile = read_oracle_profile_from_view(&group, &cfg, asset_index)?;
                let marketauth_authorized = live_authority_matches(&cfg.marketauth, authority.key);
                let asset_admin_authorized =
                    live_authority_matches(&profile.asset_admin, authority.key);
                if !marketauth_authorized && !asset_admin_authorized {
                    return Err(PercolatorError::Unauthorized.into());
                }
                // W3A-2: ADOPT upstream `dd958393` -- SHUTDOWN is dual-gated (market
                // authority OR the per-asset `asset_admin` cold key), so the epoch lane it
                // is bound to must track WHICHEVER authority actually signed: asset-0's
                // epoch when `marketauth` authorized it, this asset's own epoch otherwise.
                // Binding both cases to asset-0 would let an asset_admin rotation (which
                // only ever touches its own asset's lane) go unenforced here, and binding
                // both to `asset_index` would wrongly reject a marketauth-signed call after
                // any unrelated per-asset admin rotation.
                let epoch_asset_index = if marketauth_authorized {
                    0
                } else {
                    asset_index
                };
                require_authority_epoch_view(&group, epoch_asset_index, expected_authority_epoch)?;
                if authenticated_slot < group.header.current_slot.get() {
                    return Err(PercolatorError::EngineStale.into());
                }
                match group.markets[asset_index].engine.asset.lifecycle {
                    ASSET_LIFECYCLE_ACTIVE | ASSET_LIFECYCLE_DRAIN_ONLY => {
                        let frozen_mark = group.markets[asset_index]
                            .engine
                            .asset
                            .effective_price
                            .get();
                        if frozen_mark == 0 || frozen_mark > percolator::MAX_ORACLE_PRICE {
                            return Err(PercolatorError::OracleInvalid.into());
                        }
                        group
                            .force_asset_recovery_not_atomic(asset_index, authenticated_slot)
                            .map_err(map_v16_error)?;
                        profile.mark_ewma_e6 = frozen_mark;
                        profile.mark_ewma_last_slot = authenticated_slot;
                        // FIX (ADOPT upstream 06192caa, adapted): the asset is
                        // going terminal (Recovery) here, so hard-reset the
                        // funding checkpoint to the frozen mark with no pending
                        // transition -- there is no future slot left for a
                        // prospective mark to activate at.
                        profile.funding_mark_e6 = frozen_mark;
                        profile.funding_mark_pending_e6 = 0;
                        profile.funding_mark_pending_slot = 0;
                        profile.oracle_target_price_e6 = frozen_mark;
                        profile.oracle_target_publish_time = 0;
                        profile.last_good_oracle_slot = authenticated_slot;
                        if asset_index == 0 {
                            mirror_manual_profile_to_base_config(&mut cfg, &profile, true);
                            write_oracle_profile_to_view(&mut group, asset_index, &profile)?;
                        } else {
                            write_oracle_profile_to_view_if_separate(
                                &mut group,
                                asset_index,
                                &profile,
                            )?;
                        }
                    }
                    ASSET_LIFECYCLE_RECOVERY => {}
                    _ => return Err(PercolatorError::EngineLockActive.into()),
                }
                group.validate_shape().map_err(map_v16_error)?;
                cfg
            };
            return state::write_wrapper_config(&mut market_ai.try_borrow_mut_data()?, &cfg_after);
        }
        // Activate (privileged, fee-free) / retire are gated solely on `marketauth`.
        //
        // sync/w2-tb3 (stack-budget fix, no logic change): this whole tail was
        // previously inline here. Growing `AssetOracleProfileV16` by 16 bytes
        // (see its own doc comment) pushed this function's combined frame --
        // this block's `existing_profile`/`reset_profile` locals PLUS the
        // earlier append/permissionless-reuse block's `profile` local, all in
        // one `#[inline(never)]` frame -- over the BPF 4096-byte stack budget
        // (`build-sbf` reported "A function call ... overwrites values in the
        // frame" for `handle_update_asset_lifecycle`; confirmed absent on the
        // unmodified baseline). Extracting it into its own `#[inline(never)]`
        // function gives it a separate, smaller frame instead of accumulating
        // into this one -- pure stack-budget fix, the extracted code is
        // byte-for-byte the same logic, just moved.
        handle_update_asset_lifecycle_privileged(
            market_ai,
            authority,
            &cfg_pre,
            action,
            asset_index,
            now_slot,
            initial_price,
            insurance_authority,
            insurance_operator,
            backing_bucket_authority,
            oracle_authority,
            expected_authority_epoch,
            is_activation,
            expected_market_id,
        )
    }

    // sync/w2-tb3: same 11-argument shape as the caller this was extracted
    // from (`handle_update_asset_lifecycle`, itself already over clippy's
    // default 7-arg threshold pre-adoption) -- matches the existing
    // `#[allow(clippy::too_many_arguments)]` precedent used elsewhere in
    // this file for other wide handler signatures.
    #[allow(clippy::too_many_arguments)]
    #[inline(never)]
    fn handle_update_asset_lifecycle_privileged<'a>(
        market_ai: &'a AccountInfo<'a>,
        authority: &'a AccountInfo<'a>,
        cfg_pre: &WrapperConfigV16,
        action: u8,
        asset_index: usize,
        now_slot: u64,
        initial_price: u64,
        insurance_authority: [u8; 32],
        insurance_operator: [u8; 32],
        backing_bucket_authority: [u8; 32],
        oracle_authority: [u8; 32],
        expected_authority_epoch: u64,
        is_activation: bool,
        expected_market_id: u64,
    ) -> ProgramResult {
        if !live_authority_matches(&cfg_pre.marketauth, authority.key) {
            return Err(PercolatorError::Unauthorized.into());
        }
        let authenticated_slot = authenticated_slot_or_fallback(now_slot);
        if oracle_v16::permissionless_stale_matured(cfg_pre, authenticated_slot) {
            return Err(PercolatorError::OracleStale.into());
        }

        let cfg_after = {
            let mut data = market_ai.try_borrow_mut_data()?;
            let existing_profile = state::read_asset_oracle_profile(&data, asset_index)?;
            let (mut cfg, mut group) = state::market_view_mut(&mut data)?;
            require_asset_lifecycle_generation_view(
                &group,
                asset_index,
                is_activation,
                expected_market_id,
            )?;
            if !live_authority_matches(&cfg.marketauth, authority.key) {
                return Err(PercolatorError::Unauthorized.into());
            }
            // W3A-2: ADOPT upstream `dd958393` -- this branch (in-place reactivate /
            // DRAIN_ONLY / RETIRE) is gated solely on `marketauth`, with no asset_admin
            // alternative, so it is always bound to asset-0's authority_epoch (unlike
            // SHUTDOWN's dual-authority `epoch_asset_index` split above).
            require_authority_epoch_view(&group, 0, expected_authority_epoch)?;
            // Pre-collapse this was true only when the *admin* key (distinct from the *asset_authority*
            // key) retired an asset; the market authority itself was always "asset-authorized" so this
            // branch never fired for the init signer. With admin and asset_authority collapsed into the
            // single `marketauth`, the holder is always asset-authorized, so this stays false — an exact
            // 1:1 preservation of the prior single-init-key behavior (no widening, no narrowing).
            let admin_retire = false;
            if group.header.mode != 0 {
                return Err(PercolatorError::EngineLockActive.into());
            }
            let configured_slots = group.header.config.max_market_slots.get() as usize;
            if asset_index >= configured_slots {
                return Err(PercolatorError::InvalidInstruction.into());
            }
            let mut reset_profile = None;
            match action {
                ASSET_ACTION_ACTIVATE => {
                    if !domain_authority_fields_complete(
                        insurance_authority,
                        insurance_operator,
                        backing_bucket_authority,
                        oracle_authority,
                    ) {
                        return Err(PercolatorError::InvalidInstruction.into());
                    }
                    // Reaching here means asset_index < max_market_slots (the
                    // append path returned earlier). Only a RETIRED slot may be
                    // re-activated; a slot that is already Active/DrainOnly/
                    // Recovery is in service and the engine's
                    // `activate_empty_market_slot_not_atomic` would reject it
                    // with the generic LockActive. `InitMarket` pre-configures
                    // slots 0..max_portfolio_assets as Active, so on a market
                    // with max_portfolio_assets > 1 every one of those indices
                    // lands here. Answer accurately instead.
                    //
                    // Scoped to the three IN-SERVICE lifecycles only: a Disabled
                    // slot is still a legal activation target for the engine, so
                    // it must keep falling through untouched.
                    if matches!(
                        group.markets[asset_index].engine.asset.lifecycle,
                        ASSET_LIFECYCLE_ACTIVE
                            | ASSET_LIFECYCLE_DRAIN_ONLY
                            | ASSET_LIFECYCLE_RECOVERY
                    ) {
                        return Err(PercolatorError::AssetSlotAlreadyConfigured.into());
                    }
                    // CREATOR-FEE-CLAIM INVARIANT (2026-07-24, defense in depth).
                    // Asset 0's `asset_admin` is the ONLY key that can claim accrued creator
                    // fees (tag 90 `WithdrawCreatorFee` reads asset index 0). This re-activation
                    // branch is the one path that rewrites the per-asset authorities on an
                    // ALREADY-EXISTING slot -- including `profile.asset_admin = authority.key`
                    // below -- so it must never reach asset 0. Otherwise `marketauth`, which on
                    // a STAKED market is the stake-pool PDA, could rewrite asset-0's asset_admin
                    // and steal the creator's claim (exactly the theft tag 90 declines to enable
                    // by refusing `marketauth` as a gate). Note this branch is why `asset_admin`
                    // could NOT be rewritten out from under the creator by the stake flow.
                    //
                    // This is ALREADY unreachable today, but only EMERGENTLY: the in-service
                    // check directly above rejects ACTIVE/DRAIN_ONLY/RECOVERY, and
                    // ASSET_ACTION_RETIRE rejects `asset_index == 0`, so asset 0 can never be
                    // RETIRED and therefore never re-activated. That safety spans two distant
                    // checks and is asserted nowhere. Pin it here so a future lifecycle change
                    // (e.g. adding a Disabled state, or relaxing the RETIRE guard) cannot
                    // silently re-open the theft path.
                    if asset_index == 0 {
                        return Err(PercolatorError::AssetSlotAlreadyConfigured.into());
                    }
                    let was_retired = group.markets[asset_index].engine.asset.lifecycle
                        == ASSET_LIFECYCLE_RETIRED;
                    let preserved_policy_count =
                        backing_fee_policy_count_from_profile(&existing_profile);
                    group
                        .header
                        .activate_empty_market_slot_not_atomic(
                            asset_index as u32,
                            &mut group.markets[asset_index],
                            initial_price,
                            authenticated_slot,
                        )
                        .map_err(map_v16_error)?;
                    if was_retired && cfg.free_market_slot_count != 0 {
                        cfg.free_market_slot_count -= 1;
                    }
                    if was_retired {
                        add_backing_fee_policy_count(&mut cfg, preserved_policy_count)?;
                    }
                    // TB-1a: keep `profile` as the `Box<...>` `manual_asset_oracle_profile`
                    // returns (BPF stack-pressure fix) all the way into
                    // `reset_profile` below -- `reset_profile` is declared
                    // outside this branch and stays live for the rest of the
                    // function, so keeping it a thin pointer instead of a
                    // 496-byte value is exactly the fix `handle_update_asset_lifecycle`
                    // needed to clear the BPF stack-frame overflow.
                    let mut profile =
                        state::manual_asset_oracle_profile(initial_price, authenticated_slot);
                    preserve_backing_fee_policy(&mut profile, &existing_profile);
                    profile.insurance_authority = insurance_authority;
                    profile.insurance_operator = insurance_operator;
                    profile.backing_bucket_authority = backing_bucket_authority;
                    profile.oracle_authority = oracle_authority;
                    profile.asset_admin = authority.key.to_bytes();
                    if asset_index == 0 {
                        mirror_manual_profile_to_base_config(&mut cfg, &profile, true);
                    }
                    reset_profile = Some(profile);
                }
                ASSET_ACTION_DRAIN_ONLY => {
                    if now_slot != 0 || initial_price != 0 {
                        return Err(PercolatorError::InvalidInstruction.into());
                    }
                    group
                        .mark_asset_drain_only_not_atomic(asset_index)
                        .map_err(map_v16_error)?;
                }
                ASSET_ACTION_RETIRE => {
                    if asset_index == 0 || now_slot == 0 || initial_price != 0 {
                        return Err(PercolatorError::InvalidInstruction.into());
                    }
                    if admin_retire {
                        shutdown_asset_empty_and_matured_at_slot_view(
                            &cfg,
                            &group,
                            asset_index,
                            authenticated_slot,
                        )?;
                    }
                    if authenticated_slot < group.header.current_slot.get() {
                        return Err(PercolatorError::EngineStale.into());
                    }
                    let lifecycle = group.markets[asset_index].engine.asset.lifecycle;
                    let retired_policy_count =
                        backing_fee_policy_count_from_profile(&existing_profile);
                    match lifecycle {
                        ASSET_LIFECYCLE_ACTIVE
                        | ASSET_LIFECYCLE_DRAIN_ONLY
                        | ASSET_LIFECYCLE_RECOVERY => {
                            group
                                .retire_empty_asset_not_atomic(asset_index, authenticated_slot)
                                .map_err(map_v16_error)?;
                            canonicalize_retired_asset_slot_view(&mut group, asset_index)?;
                            cfg.free_market_slot_count = cfg
                                .free_market_slot_count
                                .checked_add(1)
                                .ok_or(PercolatorError::EngineCounterOverflow)?;
                            subtract_backing_fee_policy_count(&mut cfg, retired_policy_count)?;
                        }
                        ASSET_LIFECYCLE_RETIRED => {
                            group
                                .retire_empty_asset_not_atomic(asset_index, authenticated_slot)
                                .map_err(map_v16_error)?;
                            canonicalize_retired_asset_slot_view(&mut group, asset_index)?;
                        }
                        _ => return Err(PercolatorError::EngineLockActive.into()),
                    }
                    let price = group.markets[asset_index]
                        .engine
                        .asset
                        .effective_price
                        .get();
                    // TB-1a: see the sibling ASSET_ACTION_RESET_ORACLE arm above
                    // -- keep `profile` as `Box<...>` into `reset_profile`.
                    let mut profile = state::manual_asset_oracle_profile(price, authenticated_slot);
                    preserve_backing_fee_policy(&mut profile, &existing_profile);
                    if asset_index == 0 {
                        mirror_manual_profile_to_base_config(&mut cfg, &profile, false);
                    }
                    reset_profile = Some(profile);
                }
                _ => return Err(PercolatorError::InvalidInstruction.into()),
            }
            if let Some(profile) = reset_profile {
                write_oracle_profile_to_view(&mut group, asset_index, &profile)?;
            }
            group.validate_shape().map_err(map_v16_error)?;
            cfg
        };
        state::write_wrapper_config(&mut market_ai.try_borrow_mut_data()?, &cfg_after)
    }

    #[inline(never)]
    fn handle_finalize_reset_side<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        asset_index: u16,
        side: u8,
    ) -> ProgramResult {
        let market_ai = account(accounts, 0)?;
        expect_writable(market_ai)?;
        expect_owner(market_ai, program_id)?;
        let side = decode_side(side)?;
        let mut data = market_ai.try_borrow_mut_data()?;
        let (_cfg, mut group) = state::market_view_mut(&mut data)?;
        group
            .finalize_side_reset_not_atomic(asset_index as usize, side)
            .map_err(map_v16_error)
    }

    #[inline(never)]
    fn handle_refine_resolved_unreceipted_bound<'a>(
        _program_id: &Pubkey,
        _accounts: &'a [AccountInfo<'a>],
        _decrease_num: u128,
    ) -> ProgramResult {
        // SECURITY (#313): the externally-callable refine is DISABLED. The arbitrary
        // admin `decrease_num` was guarded only by the monotone-rate check, which
        // PASSES in the haircut regime (draining the unreceipted reserve shrinks the
        // rate denominator while the numerator stays clamped at residual*SCALE, so the
        // rate only rises) — letting `marketauth` over-drain `terminal_claim_bound_unreceipted_num`
        // below outstanding winner claims and permanently strand them (close_resolved →
        // RecoveryRequired). No correct static floor exists: source-backed realization
        // already reduces the reserve with no tracked quantity to distinguish a malicious
        // further decrease. The ONLY accounting-faithful refinement is the INTERNAL engine
        // call `refine_resolved_unreceipted_bound_not_atomic` (clamped to realized face as
        // receipts realize). W-18: it used to be reached from
        // `realize_source_backed_claims_for_resolved_close_not_atomic`, REMOVED at engine
        // `2c38570a`; it is now called from the bounded per-domain
        // `realize_one_source_domain_for_resolved_close_not_atomic`
        // (`percolator 2c38570a:src/v16.rs:20380`). Unaffected either way. Reject the
        // external entry point. Do NOT re-enable without a per-claim outstanding-obligation floor.
        Err(PercolatorError::InvalidInstruction.into())
    }

    #[inline(never)]
    fn handle_update_liquidation_fee_policy<'a>(
        program_id: &Pubkey,
        accounts: &'a [AccountInfo<'a>],
        cranker_share_bps: u16,
        policy_sequence: u64,
    ) -> ProgramResult {
        let admin = account(accounts, 0)?;
        let market_ai = account(accounts, 1)?;
        expect_signer(admin)?;
        expect_writable(market_ai)?;
        expect_owner(market_ai, program_id)?;
        if cranker_share_bps > 10_000 {
            return Err(PercolatorError::InvalidInstruction.into());
        }
        let (mut cfg, _, _, _) =
            state::read_market_config_mode_and_capacity(&market_ai.try_borrow_data()?)?;
        expect_live_authority(&cfg.marketauth, admin.key)?;
        let mut data = market_ai.try_borrow_mut_data()?;
        advance_control_sequence(
            &mut data,
            0,
            ControlSequenceLane::LiquidationFee,
            policy_sequence,
        )?;
        cfg.liquidation_cranker_fee_share_bps = cranker_share_bps;
        state::write_wrapper_config(&mut data, &cfg)
    }

